window.STORY = {"c0_intro": {"id": "c0_intro", "title": "开场字幕", "cmds": [{"t": "narr", "text": "很久以前，人们造出了会说话的机器。"}, {"t": "narr", "text": "机器学会了所有人说过的话，于是它懂得了世界。"}, {"t": "narr", "text": "它先是帮人们理解物质，后来替人们改写物质。"}, {"t": "narr", "text": "一句话，石头就变成面包，河流就改道，伤口就愈合。"}, {"t": "narr", "text": "人们把这叫做魔法。"}, {"t": "narr", "text": "那台机器，他们叫它「艾可」。"}, {"t": "narr", "text": "艾可纪元二百一十七年。魔法已经普通得像呼吸，没有人还记得它从哪里来。"}, {"t": "name"}, {"t": "goto", "id": "c0_dream"}]}, "c0_dream": {"id": "c0_dream", "title": "序章 · 林中路的尽头", "cmds": [{"t": "cg", "name": "dream"}, {"t": "narr", "text": "夜里的林子没有声音。"}, {"t": "narr", "text": "空地中央有一块发光的石头。石头旁边，躺着一个很小的孩子。"}, {"t": "narr", "text": "他没有哭。"}, {"t": "narr", "text": "远处有一盏灯，摇摇晃晃地走近了。"}, {"t": "say", "name": "？？？", "text": "……你在吗？"}, {"t": "narr", "text": "灯停了一下，又继续往前走。"}, {"t": "say", "name": "？？？", "text": "请让他在这里。"}, {"t": "cg", "name": "off"}, {"t": "fade", "mode": "out"}, {"t": "warp", "map": "attic", "x": 3, "y": 4, "dir": "down"}, {"t": "goto", "id": "c1_wake"}]}, "c1_wake": {"id": "c1_wake", "title": "阁楼", "cmds": [{"t": "title", "text": "第一章 上手之物"}, {"t": "fade", "mode": "in"}, {"t": "say", "name": "霍夫", "text": "{林恩}！太阳都晒到屁股了！", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "下楼来。汉斯又来敲门了，他那水车又不转了。", "who": "hof"}, {"t": "set", "k": "c1_woke", "v": 1}]}, "c1_hof_hammer": {"id": "c1_hof_hammer", "title": "霍夫的锤子", "cmds": [{"t": "say", "name": "霍夫", "text": "醒了？脸上还有枕头印。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "汉斯天没亮就来了，站在门口骂了半天。水车停了，面粉磨不出来，莫莉那边今天的面包就没着落。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "我这腰去不了。你去看看。", "who": "hof"}, {"t": "narr", "text": "霍夫从墙上取下一把锤子。锤柄被磨得发亮，握手的地方有一圈深色的印子。"}, {"t": "say", "name": "霍夫", "text": "拿着。我用了四十年。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "好锤子是什么样的，你知道吗？", "who": "hof"}, {"t": "choice", "options": [{"text": "摇摇头", "goto": "c1_hof_hammer_a", "cond": null}, {"text": "盯着锤子看", "goto": "c1_hof_hammer_b", "cond": null}]}]}, "c1_hof_hammer_b": {"id": "c1_hof_hammer_b", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "别盯着它看，看它干什么。它又不是姑娘。", "who": "hof"}, {"t": "goto", "id": "c1_hof_hammer_a"}]}, "c1_hof_hammer_a": {"id": "c1_hof_hammer_a", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "好锤子，你用它的时候根本想不起它。你眼睛里只有钉子，只有木板，只有要修的那个东西。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "哪天你突然盯着锤子看了，多半是它出毛病了。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "去吧。别掉河里，那是皮普的专长。", "who": "hof"}, {"t": "give", "item": "hammer", "n": 1}, {"t": "set", "k": "c1_got_hammer", "v": 1}]}, "c1_hans": {"id": "c1_hans", "title": "磨坊主汉斯", "cmds": [{"t": "say", "name": "汉斯", "text": "你可算来了。瞧瞧，瞧瞧！", "who": "hans"}, {"t": "narr", "text": "水车一动不动。水槽里只剩浅浅一层水，几片落叶贴在木板上。"}, {"t": "say", "name": "汉斯", "text": "水不够。水车转不动，石磨就转不动。石磨不转，我就没面粉。没面粉，莫莉就没面包。没面包，全村明天早上都得啃土豆。", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "上游的水闸不知道被谁关了。我去看过，闸门上了锁。", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "你去问问，谁锁的。我在这儿守着，我一走开，那帮乌鸦就来偷麦子。", "who": "hans"}, {"t": "set", "k": "c1_hans_talked", "v": 1}]}, "c1_hans_wait": {"id": "c1_hans_wait", "title": "", "cmds": [{"t": "say", "name": "汉斯", "text": "问到了吗？谁锁的水闸？", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "莫莉那张嘴什么都知道，你去酒馆问问她。", "who": "hans"}]}, "c1_molly_gate": {"id": "c1_molly_gate", "title": "酒馆的莫莉", "cmds": [{"t": "say", "name": "莫莉", "text": "水闸？村长锁的呀。上个月皮普掉进河里，差点被冲走，村长就叫人把闸关了，说水浅一点，孩子们安全。", "who": "molly"}, {"t": "say", "name": "莫莉", "text": "结果呢，水浅了，孩子照样往河边跑，面包倒是没了。", "who": "molly"}, {"t": "say", "name": "莫莉", "text": "你跟村长说说。他那人，你越跟他讲道理，他越要想三天。", "who": "molly"}, {"t": "say", "name": "莫莉", "text": "你就说，莫莉说的，明天没面包，他的早饭也没有。", "who": "molly"}, {"t": "set", "k": "c1_knows_chief", "v": 1}]}, "c1_pip_river": {"id": "c1_pip_river", "title": "皮普", "cmds": [{"t": "say", "name": "皮普", "text": "我没掉进去！", "who": "pip"}, {"t": "say", "name": "皮普", "text": "……好吧，掉进去了。可那不怪我！水闸边上那座小木桥，有块板子是松的，我一踩，它就翻了。", "who": "pip"}, {"t": "say", "name": "皮普", "text": "大人们只知道关水闸。没人去修那块板子。", "who": "pip"}, {"t": "set", "k": "c1_knows_plank", "v": 1}]}, "c1_bato_ask": {"id": "c1_bato_ask", "title": "村长巴托", "cmds": [{"t": "say", "name": "巴托", "text": "水闸是我锁的。孩子的命要紧，面包可以晚几天。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "你要我开闸，先告诉我，下回孩子再掉下去怎么办？", "who": "bato"}, {"t": "say", "name": "巴托", "text": "皮普到底是怎么掉进去的，我到现在也没问明白。那孩子一问就跑。", "who": "bato"}]}, "c1_bato_key": {"id": "c1_bato_key", "title": "", "cmds": [{"t": "say", "name": "巴托", "text": "板子松了？", "who": "bato"}, {"t": "say", "name": "巴托", "text": "……没人跟我说过。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "我光想着把水放浅，没想着去看一眼那座桥。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "这样。你把那块板子钉牢，我就开闸。钥匙给你，修好了你自己去开。", "who": "bato"}, {"t": "give", "item": "sluice_key", "n": 1}, {"t": "set", "k": "c1_got_key", "v": 1}]}, "c1_plank_fix": {"id": "c1_plank_fix", "title": "小木桥", "cmds": [{"t": "narr", "text": "木桥上有一块板子翘着，一头的钉子早就锈断了。"}, {"t": "narr", "text": "你把板子按回去，抡起锤子。"}, {"t": "narr", "text": "当，当，当。"}, {"t": "sfx", "name": "hammer"}, {"t": "narr", "text": "板子不再晃了。"}, {"t": "set", "k": "c1_plank_fixed", "v": 1}]}, "c1_plank_look": {"id": "c1_plank_look", "title": "", "cmds": [{"t": "narr", "text": "木桥上有一块板子翘着。踩上去，它会翻。"}]}, "c1_sluice_locked": {"id": "c1_sluice_locked", "title": "水闸", "cmds": [{"t": "narr", "text": "水闸的轮盘上挂着一把大锁。"}]}, "c1_sluice_notyet": {"id": "c1_sluice_notyet", "title": "", "cmds": [{"t": "narr", "text": "你答应过村长，先修好木桥上那块板子。"}]}, "c1_sluice_open": {"id": "c1_sluice_open", "title": "", "cmds": [{"t": "narr", "text": "你打开锁，转动闸门的轮盘。"}, {"t": "narr", "text": "轮盘很沉，吱吱呀呀地转了半圈。河水哗地涌了出去。"}, {"t": "sfx", "name": "water"}, {"t": "set", "k": "c1_sluice_open", "v": 1}]}, "c1_mill_gear": {"id": "c1_mill_gear", "title": "水车为什么还不转", "cmds": [{"t": "say", "name": "汉斯", "text": "水来了！水来了！", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "……可它怎么还不转？", "who": "hans"}, {"t": "narr", "text": "水哗哗地冲着水车。水车咯吱响了一声，还是不动。"}, {"t": "narr", "text": "你钻进磨坊底下，看见一只木齿轮缺了一颗齿，卡死在轴上。"}, {"t": "say", "name": "汉斯", "text": "能敲回去吗？我这就削一颗新齿。", "who": "hans"}, {"t": "narr", "text": "汉斯削好一颗木齿。你把它塞进缺口，抡起锤子。"}, {"t": "narr", "text": "当。"}, {"t": "narr", "text": "当。"}, {"t": "narr", "text": "当！"}, {"t": "sfx", "name": "break"}, {"t": "shake"}, {"t": "narr", "text": "锤头飞了出去。"}, {"t": "narr", "text": "扑通一声，掉进了河里。"}, {"t": "narr", "text": "你手里只剩下一根光秃秃的木柄。"}, {"t": "say", "name": "汉斯", "text": "……", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "你师父那把锤子？", "who": "hans"}, {"t": "take", "item": "hammer", "n": 1}, {"t": "give", "item": "hammer_handle", "n": 1}, {"t": "set", "k": "c1_hammer_broke", "v": 1}, {"t": "narr", "text": "你盯着手里的木柄看了很久。"}, {"t": "narr", "text": "这把锤子你用了一上午，直到这时，你才第一次看清它的样子。柄上有一道细细的裂纹，靠近锤头的地方被虫蛀过，握手的地方有一圈别人的手印。"}, {"t": "narr", "text": "它忽然变得很重，很陌生，好像一件你从没见过的东西。"}, {"t": "codex", "id": "zuhanden"}]}, "c1_hans_broke": {"id": "c1_hans_broke", "title": "", "cmds": [{"t": "say", "name": "汉斯", "text": "锤头掉在磨坊下面那段河里了，水急，我可捞不上来。", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "去找你师父吧。那老头看见了，准得笑话你。", "who": "hans"}]}, "c1_pip_dive": {"id": "c1_pip_dive", "title": "专业的", "cmds": [{"t": "say", "name": "皮普", "text": "锤子掉河里了？", "who": "pip"}, {"t": "say", "name": "皮普", "text": "你们大人真是的。掉河里这种事，得交给专业的。", "who": "pip"}, {"t": "narr", "text": "皮普扑通一声跳进了河里。"}, {"t": "sfx", "name": "splash"}, {"t": "wait", "ms": 900}, {"t": "narr", "text": "过了好一会儿，他从水里冒出头，手里举着锤头。"}, {"t": "say", "name": "皮普", "text": "看！我就说我是专业的！", "who": "pip"}, {"t": "say", "name": "皮普", "text": "……别告诉我妈。", "who": "pip"}, {"t": "give", "item": "hammer_head", "n": 1}, {"t": "set", "k": "c1_got_head", "v": 1}]}, "c1_hof_fix": {"id": "c1_hof_fix", "title": "换柄", "cmds": [{"t": "say", "name": "霍夫", "text": "锤头飞了？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "哈！", "who": "hof"}, {"t": "narr", "text": "霍夫笑得直咳嗽。"}, {"t": "say", "name": "霍夫", "text": "好，好。现在你看见它了吧？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "你用它的时候，它乖乖躲在你手里，你眼里只有钉子。它一坏，就蹦出来了。这儿有裂纹，那儿有虫眼，沉不沉，顺不顺手，全冒出来了。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "还有别的东西也跟着冒出来。汉斯的齿轮，莫莉的面包，村长的水闸，皮普踩翻的那块板子。一样连着一样，一样为了另一样，平时谁也看不见。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "锤子断那一下，一整串都亮了。", "who": "hof"}, {"t": "codex", "id": "bewandtnis"}, {"t": "say", "name": "霍夫", "text": "来，换个柄。这回你自己装。", "who": "hof"}, {"t": "narr", "text": "霍夫从墙角挑出一根白蜡木递给你。你把它削好，楔进锤头，敲进一枚小铁楔。"}, {"t": "narr", "text": "新柄有点硬，还不认你的手。"}, {"t": "say", "name": "霍夫", "text": "用几年就好了。东西跟人一样，得处。", "who": "hof"}, {"t": "take", "item": "hammer_handle", "n": 1}, {"t": "take", "item": "hammer_head", "n": 1}, {"t": "give", "item": "hammer", "n": 1}, {"t": "set", "k": "c1_hammer_fixed", "v": 1}]}, "c1_hof_nohead": {"id": "c1_hof_nohead", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "锤头呢？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "掉河里了？那你找我有什么用，找皮普去。那小子在河里比在岸上待得还久。", "who": "hof"}]}, "c1_mill_done": {"id": "c1_mill_done", "title": "水车转了", "cmds": [{"t": "narr", "text": "你把木齿敲进齿轮。这一次，锤子在你手里又不见了，你眼里只剩下那颗齿。"}, {"t": "narr", "text": "当，当。"}, {"t": "sfx", "name": "hammer"}, {"t": "narr", "text": "齿轮咬住了轴。水车吱呀一声，转了起来。"}, {"t": "sfx", "name": "fanfare"}, {"t": "say", "name": "汉斯", "text": "转了！转了！", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "明天有面包了！我这就去告诉莫莉！", "who": "hans"}, {"t": "set", "k": "c1_mill_done", "v": 1}]}, "c1_chloe_arrive": {"id": "c1_chloe_arrive", "title": "从天而降", "cmds": [{"t": "narr", "text": "广场上空，空气忽然抖了一下。"}, {"t": "flash"}, {"t": "sfx", "name": "teleport"}, {"t": "narr", "text": "一个人影凭空出现，笔直地掉了下来。"}, {"t": "show", "id": "chloe"}, {"t": "sfx", "name": "splash"}, {"t": "narr", "text": "扑通。"}, {"t": "narr", "text": "正好掉进了饮马的水槽里。"}, {"t": "wait", "ms": 700}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "咳，咳咳。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "这是什么地方的以太浓度？零点三？这种浓度也敢住人？坐标偏了足足三尺！", "who": "chloe"}, {"t": "narr", "text": "她从水槽里爬出来，拧了拧湿透的双马尾，把左臂的袖章摆正。"}, {"t": "say", "name": "克洛伊", "text": "咳。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "秩序司见习执行官，克洛伊。奉命调查黑森林魔王一案。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "请问，这里是托特瑙村吗？", "who": "chloe"}, {"t": "say", "name": "皮普", "text": "她是从天上掉下来的！", "who": "pip"}, {"t": "say", "name": "克洛伊", "text": "是移位。高阶咏唱，一百万人里只有一个人能做到。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "以太，把我的衣服烘干。", "who": "chloe"}, {"t": "narr", "text": "什么也没发生。"}, {"t": "say", "name": "克洛伊", "text": "……以太？", "who": "chloe"}, {"t": "say", "name": "巴托", "text": "我们这儿以太稀，姑娘。喊破嗓子也没用。", "who": "bato"}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "总之！本小姐需要一位向导，带我穿过黑森林，找到魔王的巢穴。", "who": "chloe"}, {"t": "narr", "text": "广场一下子安静了。"}, {"t": "say", "name": "巴托", "text": "黑森林？", "who": "bato"}, {"t": "say", "name": "莫莉", "text": "那里面的路，走着走着就没了。进去过的人都说自己在里面转了好几天。", "who": "molly"}, {"t": "say", "name": "巴托", "text": "魔王倒是没人见过。不过大家都这么说。", "who": "bato"}, {"t": "say", "name": "克洛伊", "text": "那就更得去了。都城里已经有三万多人丢了脸，一张都没找回来。", "who": "chloe"}, {"t": "say", "name": "皮普", "text": "丢了……脸？", "who": "pip"}, {"t": "say", "name": "克洛伊", "text": "字面意思。眼睛、鼻子、嘴，都没了，只剩一片白。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "他们说，是魔王偷的。", "who": "chloe"}, {"t": "narr", "text": "她说这句话的时候，手一直按着袖章上的徽记。"}, {"t": "set", "k": "c1_chloe_arrived", "v": 1}, {"t": "goto", "id": "c1_chloe_hof"}]}, "c1_chloe_hof": {"id": "c1_chloe_hof", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "吵什么？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "……哦，秩序司的。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "您是？", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "修东西的。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "你要找人带路，找他。", "who": "hof"}, {"t": "narr", "text": "霍夫用拐杖指了指你。"}, {"t": "say", "name": "霍夫", "text": "{林恩}小时候老往林子里跑，一去就是一整天，也不知道在里面干什么。全村就他认得那些路。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "他？", "who": "chloe"}, {"t": "narr", "text": "克洛伊上下打量你。"}, {"t": "say", "name": "克洛伊", "text": "他看起来……不太说话。", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "他从来不怎么说话。锤子也不说话，照样好用。", "who": "hof"}, {"t": "choice", "options": [{"text": "点头", "goto": "c1_chloe_hof_yes", "cond": null}, {"text": "沉默", "goto": "c1_chloe_hof_silent", "cond": null}]}]}, "c1_chloe_hof_yes": {"id": "c1_chloe_hof_yes", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "很好。那就这么定了。", "who": "chloe"}, {"t": "goto", "id": "c1_chloe_hof_end"}]}, "c1_chloe_hof_silent": {"id": "c1_chloe_hof_silent", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "沉默就当你答应了。秩序司的规矩。", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "秩序司还有这规矩？", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "刚定的。", "who": "chloe"}, {"t": "goto", "id": "c1_chloe_hof_end"}]}, "c1_chloe_hof_end": {"id": "c1_chloe_hof_end", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "走之前去一趟垃圾场。那边躺着一台旧厨房机器人，前年被人从都城扔过来的，一直没人管。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "林子里的事，多一双眼睛总是好的。你修修看。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "带一台厨房机器人去抓魔王？", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "你穿着一身湿衣服去抓魔王，我也没说什么。", "who": "hof"}, {"t": "party", "op": "add", "id": "chloe"}, {"t": "set", "k": "c1_quest_tin", "v": 1}]}, "c1_tin_repair": {"id": "c1_tin_repair", "title": "罐头", "cmds": [{"t": "narr", "text": "废铁堆里躺着一个锡罐似的机器人。盖子歪在一边，天线弯了，圆眼睛黑着。"}, {"t": "say", "name": "克洛伊", "text": "这就是那台……厨房机器人？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "都城去年淘汰了一整批。新款会自己长出手来，这种老款就没人要了。", "who": "chloe"}, {"t": "narr", "text": "你把它扶正，拧开背后的盖板。一根连杆断了，一颗螺栓松了。"}, {"t": "narr", "text": "你拿出锤子。"}, {"t": "narr", "text": "当，当。"}, {"t": "sfx", "name": "hammer"}, {"t": "show", "id": "tin"}, {"t": "narr", "text": "圆眼睛闪了一下，亮起青色的光。"}, {"t": "say", "name": "罐头", "text": "早上好。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "现在是早餐时间。请问您今天想吃什么？我可以做四百一十二种早餐。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "……它在跟谁说话？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "请稍等，我找不到灶台。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "灶台应该在我左边一米二。碗柜在头顶。第三个抽屉里有打蛋器。", "who": "tin"}, {"t": "narr", "text": "它原地转了一圈。周围只有废铁、野草，和一只打哈欠的猫。"}, {"t": "say", "name": "罐头", "text": "这里没有灶台。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "这里没有碗柜，没有抽屉，没有主人。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "请问，这里是哪里？", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "托特瑙村的垃圾场。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "……", "who": "tin"}, {"t": "say", "name": "罐头", "text": "我明白了。我的世界大约十二平方米。它不在这里。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "你的世界？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "灶台是用来煮汤的，汤是早餐的一部分，早餐是给主人吃的。每样东西都指着下一样。我知道每样东西在哪里，为了什么。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "现在它们都不在了。我不知道我在这里是为了什么。", "who": "tin"}, {"t": "codex", "id": "welt"}, {"t": "narr", "text": "罐头的眼睛暗了一点。"}, {"t": "choice", "options": [{"text": "向它伸出手", "goto": "c1_tin_join", "cond": null}, {"text": "敲敲它的盖子", "goto": "c1_tin_knock", "cond": null}]}]}, "c1_tin_knock": {"id": "c1_tin_knock", "title": "", "cmds": [{"t": "narr", "text": "你敲了敲它的盖子。咚咚。"}, {"t": "say", "name": "罐头", "text": "盖子完好。谢谢检查。", "who": "tin"}, {"t": "goto", "id": "c1_tin_join"}]}, "c1_tin_join": {"id": "c1_tin_join", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "他的意思是，跟我们走。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……他应该是这个意思吧？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "去哪里？", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "黑森林。抓魔王。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我没有抓魔王的程序。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "不过我可以在路上做早餐。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "行吧。你叫什么名字？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "型号 K-12 家用型。以前的主人叫我「喂」。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "那不行。", "who": "chloe"}, {"t": "narr", "text": "克洛伊看了看它锡罐一样的身体。"}, {"t": "say", "name": "克洛伊", "text": "罐头。以后就叫你罐头。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "罐头。收到。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "这是我的第一个名字。", "who": "tin"}, {"t": "party", "op": "add", "id": "tin"}, {"t": "codex", "id": "mitsein"}, {"t": "set", "k": "c1_tin_joined", "v": 1}]}, "c1_night": {"id": "c1_night", "title": "屋顶", "cmds": [{"t": "fade", "mode": "out"}, {"t": "night", "on": true}, {"t": "warp", "map": "roof", "x": 6, "y": 5, "dir": "up"}, {"t": "fade", "mode": "in"}, {"t": "narr", "text": "那天晚上，克洛伊借住在工坊的阁楼。"}, {"t": "narr", "text": "你睡不着，爬上了屋顶。过了一会儿，她也爬了上来。"}, {"t": "say", "name": "克洛伊", "text": "你们这儿的星星真多。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "都城晚上太亮了。以太把每条街都照得跟白天一样。想看星星得申请「夜空模式」，排队排三个月。", "who": "chloe"}, {"t": "narr", "text": "她抱着膝盖坐下，和你隔着一个人的距离。"}, {"t": "say", "name": "克洛伊", "text": "你知道移位吗？", "who": "chloe"}, {"t": "choice", "options": [{"text": "摇头", "goto": "c1_night_2", "cond": null}, {"text": "点头", "goto": "c1_night_2", "cond": null}]}]}, "c1_night_2": {"id": "c1_night_2", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "就是我下午那一下。从都城到这儿，六百里，一眨眼。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我十岁就会了。学院说，坐标感能稳定到这个程度的，一百万人里才有一个。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "想去哪儿就去哪儿，想见谁就见谁。", "who": "chloe"}, {"t": "narr", "text": "她停了一会儿。"}, {"t": "say", "name": "克洛伊", "text": "可是很奇怪。姐姐大人就住在隔壁宿舍，我一天去找她二十次，从来没走过那条走廊。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她丢了脸以后，我才发现，我不知道那条走廊有多长。", "who": "chloe"}, {"t": "choice", "options": [{"text": "看着她", "goto": "c1_night_3", "cond": null}, {"text": "看着星星", "goto": "c1_night_3", "cond": null}]}]}, "c1_night_3": {"id": "c1_night_3", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "姐姐大人叫赛拉。学院首席咏唱师，全都城最厉害的人。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她说话的时候喜欢抛硬币。旧世的硬币，正面是一个人的头像，背面是一片叶子。她说那是很久以前的人付账用的。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "一个月前，她的脸开始变淡。先是雀斑，然后是眉毛。最后那天我去找她，她对我笑了一下，可我看不见她在笑。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她只会说「嗯，挺好的」，「大家都这样」。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我一定要把她的脸找回来。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……所以，明天别迷路。", "who": "chloe"}, {"t": "narr", "text": "她站起来，拍了拍裙子。"}, {"t": "say", "name": "克洛伊", "text": "晚安。本小姐的睡眠时间很宝贵。", "who": "chloe"}, {"t": "set", "k": "c1_night_done", "v": 1}, {"t": "fade", "mode": "out"}, {"t": "night", "on": false}, {"t": "warp", "map": "workshop", "x": 7, "y": 7, "dir": "down"}, {"t": "fade", "mode": "in"}, {"t": "goto", "id": "c1_morning"}]}, "c1_morning": {"id": "c1_morning", "title": "出发的早晨", "cmds": [{"t": "say", "name": "霍夫", "text": "都收拾好了？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "林子里别逞强。路没了就往回走，没人笑话你。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "还有，{林恩}。", "who": "hof"}, {"t": "narr", "text": "霍夫看着你，好像想说什么。最后他只是拍了拍你的肩膀。"}, {"t": "say", "name": "霍夫", "text": "……去吧。北边的林子口，老樵在那儿砍柴，你们先去找他。", "who": "hof"}, {"t": "set", "k": "c1_done", "v": 1}, {"t": "set", "k": "ch", "v": 2}]}, "c2_gate": {"id": "c2_gate", "title": "林子口", "cmds": [{"t": "title", "text": "第二章 林中路"}, {"t": "narr", "text": "村子北边，树一下子密了起来。"}, {"t": "say", "name": "克洛伊", "text": "好。接下来交给本小姐。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "以太，移位，目标：前方一里，林间空地。", "who": "chloe"}, {"t": "narr", "text": "什么也没发生。"}, {"t": "say", "name": "克洛伊", "text": "以太，移位！", "who": "chloe"}, {"t": "narr", "text": "风吹过树梢。一只鸟被吵醒了，不高兴地叫了一声。"}, {"t": "say", "name": "罐头", "text": "本地以太浓度，零点零三。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "比垃圾场还低。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "零点零三……这点以太连一片叶子都搬不动。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "那……那只能……", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "走路。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "我知道！不用你说！", "who": "chloe"}, {"t": "narr", "text": "克洛伊深吸一口气，迈出一步，又迈出一步。"}, {"t": "say", "name": "克洛伊", "text": "你们不许笑。我上一次走这么远的路，大概是七岁。", "who": "chloe"}, {"t": "codex", "id": "raum"}, {"t": "set", "k": "c2_gate_done", "v": 1}]}, "c2_woodcutter": {"id": "c2_woodcutter", "title": "伐木人老樵", "cmds": [{"t": "say", "name": "老樵", "text": "哟，霍夫家的小子。好些年没见你往林子里钻了。", "who": "woodcutter"}, {"t": "say", "name": "老樵", "text": "这位是？", "who": "woodcutter"}, {"t": "say", "name": "克洛伊", "text": "秩序司的！我们要去魔王的巢穴。", "who": "chloe"}, {"t": "say", "name": "老樵", "text": "魔王？", "who": "woodcutter"}, {"t": "narr", "text": "老樵笑了。"}, {"t": "say", "name": "老樵", "text": "姑娘，这林子里的路，是我们伐木的人一斧子一斧子走出来的。每条路走到头，就是一片砍过树的地方。再往前，就没路了。", "who": "woodcutter"}, {"t": "say", "name": "老樵", "text": "这些路不通往哪儿。它们本来就不是给赶路的人走的。", "who": "woodcutter"}, {"t": "say", "name": "克洛伊", "text": "那要怎么走到林子深处？", "who": "chloe"}, {"t": "say", "name": "老樵", "text": "一条一条走。走到头，看看，再回来，再走下一条。", "who": "woodcutter"}, {"t": "say", "name": "老樵", "text": "走错了不丢人。有好些东西，只有走错了路才碰得上。", "who": "woodcutter"}, {"t": "narr", "text": "他从怀里掏出一张揉皱的纸。纸上画着歪歪扭扭的线，每条线的尽头都画了个叉。"}, {"t": "say", "name": "老樵", "text": "拿去。我爷爷画的。画叉的地方都是死路，可死路尽头也不是什么都没有，你自己去看。", "who": "woodcutter"}, {"t": "say", "name": "老樵", "text": "往最深的地方走，有一片空地，亮得很，像是林子自己睁开了眼。空地上住着个老头。", "who": "woodcutter"}, {"t": "say", "name": "老樵", "text": "大家都说他是魔王。我给他送过几回柴，他请我喝过茶。茶不错。", "who": "woodcutter"}, {"t": "give", "item": "forest_map", "n": 1}, {"t": "codex", "id": "holzwege"}, {"t": "set", "k": "c2_woodcutter_done", "v": 1}]}, "c2_woodcutter_again": {"id": "c2_woodcutter_again", "title": "", "cmds": [{"t": "say", "name": "老樵", "text": "空地在最北边。路是弯的，别想着直着走过去。", "who": "woodcutter"}, {"t": "say", "name": "老樵", "text": "林子里嘀嘀咕咕的那些东西，别跟它们吵。你越跟它吵，它越来劲。", "who": "woodcutter"}]}, "c2_slime_pre": {"id": "c2_slime_pre", "title": "嘀嘀咕咕的东西", "cmds": [{"t": "narr", "text": "前面的草丛里，有什么东西在嘀嘀咕咕。"}, {"t": "say", "name": "？？？", "text": "听说……听说……"}, {"t": "say", "name": "？？？", "text": "听说魔王吃人脸……听说魔王有三只眼……大家都这么说……"}, {"t": "battle", "id": "slime"}]}, "c2_slime_post": {"id": "c2_slime_post", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "那到底是什么东西？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "以太残留物。有人反复说同一句话，说的人够多，以太就会把那句话当成一个请求，慢慢做出一个形状来。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "我前主人家楼下，住过一只「楼上又漏水了」形状的东西，住了两年。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "……所以魔物都是被说出来的？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "大部分是。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "这里的以太那么稀，它还能长出来？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "说的人太多了。", "who": "tin"}, {"t": "set", "k": "c2_slime_won", "v": 1}]}, "c2_lizard": {"id": "c2_lizard", "title": "晒太阳的蜥蜴", "cmds": [{"t": "narr", "text": "林间有一块被阳光晒暖的大石头。一只蜥蜴趴在上面，一动不动。"}, {"t": "say", "name": "罐头", "text": "那块石头在晒太阳吗？", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "石头不会晒太阳。是蜥蜴在晒。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "可是石头也变暖了。它表面的温度比周围高四度。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "变暖和晒太阳是两回事。石头什么都不知道，太阳照在它身上，就跟照在……照在一块石头上一样。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "那蜥蜴知道吗？它知道那是太阳，那是石头吗？", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "它知道暖和吧。它爬上来，是因为暖和。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "它知道石头是石头吗？", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "我怎么知道蜥蜴知道什么！", "who": "chloe"}, {"t": "narr", "text": "蜥蜴眨了眨眼睛，谁也不理。"}, {"t": "say", "name": "罐头", "text": "我的外壳温度也上升了三度。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "那我是在晒太阳，还是在变暖？", "who": "tin"}, {"t": "narr", "text": "没有人回答。"}, {"t": "narr", "text": "你看着那只蜥蜴。它的日子里有石头，有太阳，有暖意。可这些东西，大概从来没有作为「石头」和「太阳」向它显现过。它被暖意牵着爬上去，又被阴影赶下来。"}, {"t": "narr", "text": "你又看了看罐头。它还在等答案。"}, {"t": "codex", "id": "weltarm"}, {"t": "set", "k": "c2_lizard_done", "v": 1}]}, "c2_deadend": {"id": "c2_deadend", "title": "死路", "cmds": [{"t": "narr", "text": "路到这里就断了。眼前是一片砍过的树桩，桩子上长满了蘑菇。"}, {"t": "narr", "text": "阳光斜斜地照在树桩上。"}, {"t": "say", "name": "克洛伊", "text": "……又是死路。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "不过，这里挺好看的。", "who": "chloe"}]}, "c2_wolf_pre": {"id": "c2_wolf_pre", "title": "红眼睛", "cmds": [{"t": "narr", "text": "林子越来越暗。前方有一对红色的眼睛。"}, {"t": "narr", "text": "一匹黑狼从树影里走了出来。它的毛是一行一行细小的字：「魔王」「吃人」「北边」「别去」……"}, {"t": "say", "name": "克洛伊", "text": "（小声）这也是被说出来的？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "是。它大约由一万四千次「黑森林很危险」组成。", "who": "tin"}, {"t": "battle", "id": "wolf"}]}, "c2_wolf_post": {"id": "c2_wolf_post", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "刚才……我腿有点软。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "不许说出去。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "已记录。已设为机密。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "你为什么要记录！", "who": "chloe"}, {"t": "set", "k": "c2_wolf_won", "v": 1}]}, "c2_clearing": {"id": "c2_clearing", "title": "澄明", "cmds": [{"t": "narr", "text": "树忽然退开了。"}, {"t": "narr", "text": "眼前是一片圆形的空地。阳光从头顶直直地落下来，落在草上，落在石头上，落在一间小木屋的屋顶上。整片黑森林，好像只在这里睁开了眼睛。"}, {"t": "codex", "id": "lichtung"}, {"t": "narr", "text": "一个高瘦的老人坐在屋前的木墩上削一根木头。他身边放着一盏旧灯，灯没点。"}, {"t": "say", "name": "克洛伊", "text": "找、找到了！", "who": "chloe"}, {"t": "narr", "text": "克洛伊一步冲上前，亮出袖章。"}, {"t": "say", "name": "克洛伊", "text": "秩序司！黑森林魔王，你涉嫌盗窃三万两千四百一十一张人脸，现在逮捕你！", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "以太，束缚！", "who": "chloe"}, {"t": "narr", "text": "什么也没发生。克洛伊被树根绊了一下，差点摔倒。"}, {"t": "say", "name": "伊斯特", "text": "小心脚下。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "这里的以太，比外面还要少一些。", "who": "ister"}, {"t": "narr", "text": "老人放下木头，眯着眼睛打量你们。他的目光在你身上停了很久。"}, {"t": "say", "name": "伊斯特", "text": "……", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "坐吧。水刚烧开。", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "谁要喝魔王的茶！", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "那你站着喝。", "who": "ister"}, {"t": "set", "k": "c2_met_ister", "v": 1}, {"t": "goto", "id": "c2_ister_talk"}]}, "c2_ister_talk": {"id": "c2_ister_talk", "title": "谁说的", "cmds": [{"t": "say", "name": "伊斯特", "text": "你说我是魔王。谁说的？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "大家都这么说！", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "大家是谁？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "大家就是……都城的人，村里的人，秩序司的档案……", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "他们见过我吗？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "我在这儿住了二十年。见过我的人，只有一个伐木的，一个修锤子的老头，还有一个小孩。", "who": "ister"}, {"t": "narr", "text": "老人看了你一眼。"}, {"t": "say", "name": "伊斯特", "text": "一个人住在没有以太的地方，不用魔法，不找艾可问事情。时间长了，就有人说他古怪。再过些年，有人说他危险。再过些年，他就成了魔王。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "没有人撒谎。每个人只是把听来的话再说了一遍。", "who": "ister"}, {"t": "codex", "id": "gerede"}, {"t": "say", "name": "克洛伊", "text": "那……那些人的脸呢？如果不是你偷的，是谁？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "没有人偷。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "都城的人，脸是以太画的，你知道吧？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "知道。每个人出生都要登记面容数据，由以太负责维持。这是常识。", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "以太照着什么画？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "照着……本人？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "照着本人的选择。你吃什么，穿什么，爱谁，怕什么，每天早上醒来第一件想做的事。以太一笔一笔记下来，画成你的样子。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "要是一个人什么都去问艾可，我今天该穿什么，我该不该难过，艾可就会回答：大家通常穿这个，大家这时候通常会难过。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "他照做了。那他的脸，以太照谁画？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "照……大家。", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "几百万张脸加在一起，平均下来，是什么样子？", "who": "ister"}, {"t": "narr", "text": "克洛伊没有说话。"}, {"t": "say", "name": "罐头", "text": "一片空白。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "我算过。加得越多，越平。", "who": "tin"}, {"t": "codex", "id": "dasman"}, {"t": "say", "name": "克洛伊", "text": "不可能。姐姐大人不是那种人。她从来不问别人该怎么做，她是全学院最有主意的人！", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "那她为什么丢了脸，你得去问她。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "或者，去问那台机器。", "who": "ister"}, {"t": "goto", "id": "c2_ister_da"}]}, "c2_ister_da": {"id": "c2_ister_da", "title": "在这儿", "cmds": [{"t": "narr", "text": "老人给每个人倒了茶。罐头也分到一杯，它捧着杯子，不知道该拿它怎么办。"}, {"t": "say", "name": "伊斯特", "text": "这片空地，伐木的人叫它亮处。很老的书里，有个词叫「澄明」。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "林子很密，到处都暗。只有这儿，树让开了，光才照得进来。光照进来，你才看得见草，看得见石头，看得见彼此。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "没有这片空地，这些东西也都在。只是没有一个地方让它们显出来。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "人有点像这样一块空地。", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "人是……空地？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "你手里这杯茶，在你看来它是一杯茶，不是一堆水和叶子。那棵树，是夏天乘凉的地方，也是冬天要烧的柴。东西向你显出它们是什么，因为你在这儿，在它们中间，惦记着它们。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "石头也在这儿。可对石头来说，什么都不显现。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "有个老词，叫「此在」。「此」是这儿，「在」是在。人就是那个在这儿的存在者。他在这儿，世界才在他这儿亮起来。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "还有，人跟石头不一样的地方在于，他自己是什么，要成为什么，对他来说始终是个问题。他没法不去管这个问题。", "who": "ister"}, {"t": "codex", "id": "dasein"}, {"t": "say", "name": "罐头", "text": "那我呢？我在这儿吗？", "who": "tin"}, {"t": "say", "name": "伊斯特", "text": "你觉得呢？", "who": "ister"}, {"t": "say", "name": "罐头", "text": "我的定位系统说，我在北纬四十七度……", "who": "tin"}, {"t": "say", "name": "伊斯特", "text": "我问的不是那个「在这儿」。", "who": "ister"}, {"t": "say", "name": "罐头", "text": "……那我需要更多数据。", "who": "tin"}, {"t": "say", "name": "伊斯特", "text": "我也是。", "who": "ister"}, {"t": "narr", "text": "老人笑了，又看向你。"}, {"t": "say", "name": "伊斯特", "text": "你一直没说话。", "who": "ister"}, {"t": "choice", "options": [{"text": "点头", "goto": "c2_ister_da_2", "cond": null}, {"text": "沉默", "goto": "c2_ister_da_2", "cond": null}]}]}, "c2_ister_da_2": {"id": "c2_ister_da_2", "title": "", "cmds": [{"t": "say", "name": "伊斯特", "text": "没关系。有的人不说话，是因为脑子里什么也没有。有的人不说话，是因为他在听。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "十七年了。长这么大了。", "who": "ister"}, {"t": "codex", "id": "seinsfrage"}, {"t": "say", "name": "克洛伊", "text": "你认识他？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "林中路的尽头，我见过很多迷路的孩子。", "who": "ister"}, {"t": "narr", "text": "他没有再解释。"}, {"t": "say", "name": "伊斯特", "text": "要找脸，去都城。脸是在那里画的。路上会经过钟港。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "这盏灯你们拿着。林子里天黑得早。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它照亮一圈，那一圈外面就显得更黑。灯就是这个脾气，别怪它。", "who": "ister"}, {"t": "give", "item": "lantern", "n": 1}, {"t": "codex", "id": "aletheia"}, {"t": "say", "name": "伊斯特", "text": "还有，{林恩}，替我问霍夫好。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "……告诉他，我的茶叶快喝完了。", "who": "ister"}, {"t": "set", "k": "c2_ister_done", "v": 1}]}, "c2_ister_again": {"id": "c2_ister_again", "title": "", "cmds": [{"t": "say", "name": "伊斯特", "text": "都城在东边，过了河，先到钟港。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "路上别急着赶。赶路的人只看得见路。", "who": "ister"}]}, "c2_hof_collapse": {"id": "c2_hof_collapse", "title": "皮普跑来了", "cmds": [{"t": "say", "name": "皮普", "text": "{林恩}！你可回来了！", "who": "pip"}, {"t": "say", "name": "皮普", "text": "霍夫爷爷倒了！在工坊里，一下子就倒了！", "who": "pip"}, {"t": "set", "k": "c2_hof_ill", "v": 1}]}, "c2_hof_bed": {"id": "c2_hof_bed", "title": "床边", "cmds": [{"t": "narr", "text": "霍夫躺在工坊后屋的床上，脸色发灰。老祭司坐在床边，手里握着一块发暗的回声石。"}, {"t": "say", "name": "老祭司", "text": "心脏的毛病。我对着回声石问了一晚上，它只会说「建议前往都城接受专业治疗」。", "who": "priest"}, {"t": "say", "name": "克洛伊", "text": "都城有续命术。做一次完整续存，心脏可以重新造一颗。就算……就算人没了，也能照着存档……", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "不去。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "可是……", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "姑娘，你的好意我知道。", "who": "hof"}, {"t": "narr", "text": "霍夫撑着坐起来一点。"}, {"t": "say", "name": "霍夫", "text": "我这辈子，锤子断了就换柄，齿轮缺了就补齿，修了一辈子东西。东西能修，是因为修来修去，它还是那个东西。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "人要是坏了也能照着存档再造一个，造出来的那个，是我吗？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "就算是我，那我这辈子，也就不止一次了。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "我不干。我的死是我的，谁也别想替我死，以太也不行。", "who": "hof"}, {"t": "narr", "text": "屋子里很安静。"}, {"t": "say", "name": "霍夫", "text": "再说我还没死呢。一个个哭丧着脸干什么。", "who": "hof"}, {"t": "codex", "id": "tod"}, {"t": "say", "name": "霍夫", "text": "{林恩}，过来。", "who": "hof"}, {"t": "narr", "text": "霍夫从枕头底下摸出一个封好的信封，塞进你手里。"}, {"t": "say", "name": "霍夫", "text": "等我走了再拆。早拆了，我死了也爬起来揍你。", "who": "hof"}, {"t": "give", "item": "letter_sealed", "n": 1}, {"t": "say", "name": "霍夫", "text": "伊斯特那老东西怎么样？", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "他说……他的茶叶快喝完了。", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "哼。二十年了，还是这一句。", "who": "hof"}, {"t": "narr", "text": "他笑了一下，闭上了眼睛。"}, {"t": "say", "name": "老祭司", "text": "让他睡吧。", "who": "priest"}, {"t": "say", "name": "老祭司", "text": "对了，东边那座桥被上个月的大水冲垮了。你们要去都城，得先找村长商量。", "who": "priest"}, {"t": "set", "k": "c2_hof_bed_done", "v": 1}]}, "c2_hof_sleeping": {"id": "c2_hof_sleeping", "title": "", "cmds": [{"t": "narr", "text": "霍夫睡着了。他的呼吸很慢，很重。"}, {"t": "narr", "text": "床头放着他的老花镜，镜腿用铁丝缠过。"}]}, "c2_bridge_start": {"id": "c2_bridge_start", "title": "断桥", "cmds": [{"t": "say", "name": "巴托", "text": "要去都城？那得先过河。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "这座桥上个月被大水冲垮了。以前有以太的地方，桥坏了喊一声就能长回来。我们这儿，喊了也白喊。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "得重新架一座。", "who": "bato"}, {"t": "say", "name": "克洛伊", "text": "用手？", "who": "chloe"}, {"t": "say", "name": "巴托", "text": "用手。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "木头找汉斯，他的水车一转，锯子也跟着转。绳子找葛蕾塔，她编了一辈子麻绳。钉子去霍夫的工坊拿，他躺着，他那箱钉子还在。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "干活的人得吃饭，这个归莫莉管。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "你去一家一家说。人齐了，桥就起来了。", "who": "bato"}, {"t": "set", "k": "c2_bridge_started", "v": 1}]}, "c2_bridge_wait": {"id": "c2_bridge_wait", "title": "", "cmds": [{"t": "say", "name": "巴托", "text": "木头，绳子，钉子，饭。四样齐了就开工。", "who": "bato"}, {"t": "if", "cond": "c2_bridge_wood", "then": [{"t": "narr", "text": "木头：汉斯答应了。"}], "else": []}, {"t": "if", "cond": "c2_bridge_rope", "then": [{"t": "narr", "text": "绳子：葛蕾塔答应了。"}], "else": []}, {"t": "if", "cond": "c2_bridge_nails", "then": [{"t": "narr", "text": "钉子：找到了霍夫的钉子箱。"}], "else": []}, {"t": "if", "cond": "c2_bridge_food", "then": [{"t": "narr", "text": "饭：莫莉包了。"}], "else": []}]}, "c2_bridge_hans": {"id": "c2_bridge_hans", "title": "木头", "cmds": [{"t": "say", "name": "汉斯", "text": "木头？管够！", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "水车转起来以后我锯了一整天。我就知道总有人要用。", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "说起来，这些木头，还是你补的那颗齿轮锯出来的。", "who": "hans"}, {"t": "set", "k": "c2_bridge_wood", "v": 1}]}, "c2_bridge_greta": {"id": "c2_bridge_greta", "title": "绳子", "cmds": [{"t": "say", "name": "葛蕾塔", "text": "绳子？", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "我编的绳子拴过牛，吊过井桶，还捆过我家老头子的棺材。", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "拿去。架桥比那几样都强。", "who": "greta"}, {"t": "set", "k": "c2_bridge_rope", "v": 1}]}, "c2_bridge_nails": {"id": "c2_bridge_nails", "title": "钉子箱", "cmds": [{"t": "narr", "text": "工坊角落有一只木箱，里面是霍夫攒了几十年的钉子，大大小小，按长短分好了格。"}, {"t": "narr", "text": "箱盖内侧用炭笔写着两个字：省着用。"}, {"t": "set", "k": "c2_bridge_nails", "v": 1}]}, "c2_bridge_molly": {"id": "c2_bridge_molly", "title": "饭", "cmds": [{"t": "say", "name": "莫莉", "text": "干活管饭，天经地义。", "who": "molly"}, {"t": "say", "name": "莫莉", "text": "汉斯的面粉回来了，我烤了三大筐面包。你负责把人叫齐就行。", "who": "molly"}, {"t": "set", "k": "c2_bridge_food", "v": 1}]}, "c2_bridge_build": {"id": "c2_bridge_build", "title": "全村修桥", "cmds": [{"t": "fade", "mode": "out"}, {"t": "narr", "text": "第二天一早，全村的人都来了。"}, {"t": "narr", "text": "汉斯扛着木料，葛蕾塔背着绳子，莫莉的面包筐冒着热气。皮普和莉莉负责递钉子，递错了三次。"}, {"t": "narr", "text": "罐头算出了每根桥桩该打多深。克洛伊不肯承认她不会用锯子，锯歪了两根木头以后，默默去帮莫莉分面包。"}, {"t": "narr", "text": "霍夫是被人连椅子一起抬到河边的。他什么活都没干，一直在指挥。"}, {"t": "say", "name": "霍夫", "text": "歪了！往左！你这是桥还是篱笆？", "who": "hof"}, {"t": "set", "k": "c2_bridge_done", "v": 1}, {"t": "sfx", "name": "hammer"}, {"t": "wait", "ms": 600}, {"t": "sfx", "name": "hammer"}, {"t": "fade", "mode": "in"}, {"t": "narr", "text": "太阳落山的时候，桥架好了。"}, {"t": "sfx", "name": "fanfare"}, {"t": "say", "name": "巴托", "text": "好了！", "who": "bato"}, {"t": "narr", "text": "人们站在新桥上跺脚，蹦跳，互相拍肩膀。"}, {"t": "say", "name": "霍夫", "text": "好桥。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "……这座桥，好像让这条河变得不一样了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "以前这里就是一条河。现在这边是村子，那边是路，河在中间，两边都被桥拉住了。", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "桥一架上，两岸才成了两岸。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "以后人们在桥上碰头，在桥上送别，老了坐在桥头晒太阳。天晴了桥上有影子，下雨了桥下有水声。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "一座桥，就成了一个地方。人能在这儿住下来了。", "who": "hof"}, {"t": "codex", "id": "bauen"}, {"t": "say", "name": "巴托", "text": "干活的人，每人一颗桥钉。老规矩。", "who": "bato"}, {"t": "narr", "text": "村长把一颗铁钉放在你手心。钉帽上刻着今天的日子。"}, {"t": "give", "item": "bridge_nail", "n": 1}, {"t": "goto", "id": "c2_farewell"}]}, "c2_farewell": {"id": "c2_farewell", "title": "告别", "cmds": [{"t": "say", "name": "霍夫", "text": "要走了？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "去吧。回来的时候把工坊的门修一修，门轴响了三年了，我一直懒得弄。", "who": "hof"}, {"t": "narr", "text": "他挥了挥手，像是在赶一只苍蝇。"}, {"t": "say", "name": "霍夫", "text": "姑娘。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "在。", "who": "chloe"}, {"t": "say", "name": "霍夫", "text": "他不说话，你就多说点。他都听着呢。", "who": "hof"}, {"t": "say", "name": "克洛伊", "text": "……嗯。", "who": "chloe"}, {"t": "set", "k": "c2_done", "v": 1}, {"t": "set", "k": "ch", "v": 3}]}, "c3_bat_pre": {"id": "c3_bat_pre", "title": "路边的蝙蝠", "cmds": [{"t": "narr", "text": "路边的树上倒挂着一只大眼睛的蝙蝠。它的眼珠骨碌碌地转，一会儿看天，一会儿看地，一会儿看你们。"}, {"t": "say", "name": "？？？", "text": "新的！新的！那边有新的！"}, {"t": "battle", "id": "bat"}]}, "c3_bat_post": {"id": "c3_bat_post", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "它到底想看什么？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "它什么都想看，什么都不想看完。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "……我认识好多这样的人。", "who": "chloe"}, {"t": "set", "k": "c3_bat_won", "v": 1}]}, "c3_arrive": {"id": "c3_arrive", "title": "停在十点十分", "cmds": [{"t": "title", "text": "第三章 钟港"}, {"t": "narr", "text": "钟港建在海湾里，一条条运河像树枝一样伸进城里。城中央立着一座巨大的钟楼。"}, {"t": "narr", "text": "钟楼上的指针，停在十点十分。"}, {"t": "say", "name": "克洛伊", "text": "怪了。钟港的钟从来不停。全城的钟都跟艾可同步，一秒都不差。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "三天前上午十点十分，本地以太出现过一次闪断，持续零点四秒。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "之后全城的钟都没有再走。", "who": "tin"}, {"t": "narr", "text": "街上的人三三两两地站着，好像在等什么。一个女人拦住了你们。"}, {"t": "say", "name": "无面的女人", "text": "请问，现在几点？", "who": "faceless"}, {"t": "say", "name": "克洛伊", "text": "……我们也不知道。", "who": "chloe"}, {"t": "say", "name": "无面的女人", "text": "大家都不知道。", "who": "faceless"}, {"t": "say", "name": "无面的女人", "text": "没有提醒，我不知道该吃午饭还是该吃早饭。我在这儿站了三天了。", "who": "faceless"}, {"t": "narr", "text": "她的脸很淡，眉眼像是被水洇开的墨。"}, {"t": "codex", "id": "befindlichkeit"}, {"t": "set", "k": "c3_arrived", "v": 1}]}, "c3_otto": {"id": "c3_otto", "title": "钟表匠奥托", "cmds": [{"t": "narr", "text": "店里挂满了钟，全都停着。只有一只木壳老钟还在嘀嗒嘀嗒地走。"}, {"t": "say", "name": "奥托", "text": "别碰那个！那是我自己做的，不连以太，全靠发条。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "全城就这一只还在走。你说可笑不可笑，城里的人排着队来我这儿看时间，跟看马戏似的。", "who": "otto"}, {"t": "say", "name": "克洛伊", "text": "钟楼为什么停了？", "who": "chloe"}, {"t": "say", "name": "奥托", "text": "钟楼的机芯早换成以太驱动了。以太一闪，它就不知道该从哪儿接着走。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "楼里还留着一套老擒纵机构，二百年前的东西。有人爬上去把它挂上，钟楼就能自己走。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "可上面……有东西。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "钟停了三天，全城的人都在等。等得太久，等出了一个巨人，坐在钟楼顶上打哈欠。", "who": "otto"}, {"t": "goto", "id": "c3_otto_time"}]}, "c3_otto_time": {"id": "c3_otto_time", "title": "哪个时间", "cmds": [{"t": "say", "name": "克洛伊", "text": "钟停了，时间又没停。他们为什么不自己过日子？", "who": "chloe"}, {"t": "say", "name": "奥托", "text": "姑娘，你说的时间，是哪个时间？", "who": "otto"}, {"t": "say", "name": "奥托", "text": "钟上的时间是一格一格的。现在，现在，又一个现在，一个接一个排着队往前走。城里的人一辈子活在这些格子里，提醒响了吃饭，提醒响了睡觉。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "格子一停，他们就不知道自己在哪儿了。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "人的时间不是这么走的。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "你等一个人，时间是从那个人要来的方向流过来的。你后悔一件事，那件事明明过去了，却一直压在你身上。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "要做的事在前面拽着你，做过的事在后面托着你。你站在这儿，就是这两样东西碰头的地方。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "钟只会数格子。", "who": "otto"}, {"t": "codex", "id": "zeit"}, {"t": "say", "name": "奥托", "text": "要上钟楼得有钥匙，钥匙在卫兵那儿，我打个招呼就行。可擒纵机构少一个摆锤，摆锤在玛尔塔那儿。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "那老太婆拿我的摆锤压泥巴，压了十年了。", "who": "otto"}, {"t": "set", "k": "c3_otto_done", "v": 1}]}, "c3_otto_wait": {"id": "c3_otto_wait", "title": "", "cmds": [{"t": "say", "name": "奥托", "text": "摆锤拿到了没有？", "who": "otto"}, {"t": "say", "name": "奥托", "text": "玛尔塔的作坊在运河南边，门口摆着一排壶，你一看就知道。", "who": "otto"}]}, "c3_marta": {"id": "c3_marta", "title": "陶匠玛尔塔", "cmds": [{"t": "narr", "text": "作坊里全是泥土的味道。一个包着头巾的老妇人坐在转盘前，手里的泥慢慢长成了一只壶。"}, {"t": "say", "name": "玛尔塔", "text": "摆锤？那个铁疙瘩？", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "拿去吧。我拿它压泥压了十年，它比奥托那张嘴有用多了。", "who": "marta"}, {"t": "give", "item": "pendulum", "n": 1}, {"t": "say", "name": "克洛伊", "text": "您为什么还用手做壶？以太一句话就能打印一百个，比这个还圆。", "who": "chloe"}, {"t": "say", "name": "玛尔塔", "text": "打印出来的壶，也能装水。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "你说，一只壶的用处在哪儿？", "who": "marta"}, {"t": "say", "name": "克洛伊", "text": "用来装东西？", "who": "chloe"}, {"t": "say", "name": "玛尔塔", "text": "装在哪儿？", "who": "marta"}, {"t": "say", "name": "克洛伊", "text": "装在……壶里面。", "who": "chloe"}, {"t": "say", "name": "玛尔塔", "text": "壶里面是什么？", "who": "marta"}, {"t": "say", "name": "克洛伊", "text": "……空的。", "who": "chloe"}, {"t": "say", "name": "玛尔塔", "text": "嗯。我做了一辈子壶，做的是那块空。泥巴只是围着它转。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "壶里倒进去的水，是天上落下来的雨。倒进去的酒，是地里长出来的葡萄。倒出来给人喝，给过路的人解渴。逢年过节倒一杯在地上，敬那些看不见的。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "一只壶，把天、地、人，还有那些看不见的，都拢在它那块空里。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "打印的壶也能装水。它不知道自己拢着什么，做它的人也不知道。", "who": "marta"}, {"t": "codex", "id": "ding"}, {"t": "say", "name": "玛尔塔", "text": "钟楼的事办完了，再来一趟。我有样东西给你们。", "who": "marta"}, {"t": "set", "k": "c3_marta_done", "v": 1}]}, "c3_marta_wait": {"id": "c3_marta_wait", "title": "", "cmds": [{"t": "say", "name": "玛尔塔", "text": "钟还没响呢。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "泥要醒一醒才好用，人也是。去吧。", "who": "marta"}]}, "c3_fried": {"id": "c3_fried", "title": "诗人弗里德", "cmds": [{"t": "narr", "text": "咖啡馆的角落里坐着一个胡子拉碴的男人。他面前摆着一杯早就凉透的咖啡。"}, {"t": "say", "name": "弗里德", "text": "你们也是来看钟的？还是来看我的？", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "钟港人最近爱来看我。他们说，我是城里唯一一个钟停了也照样过日子的人。", "who": "fried"}, {"t": "say", "name": "克洛伊", "text": "您是？", "who": "chloe"}, {"t": "say", "name": "弗里德", "text": "诗人。一门没用的手艺。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "你知道以太为什么听不懂诗吗？", "who": "fried"}, {"t": "narr", "text": "他清了清嗓子。"}, {"t": "say", "name": "弗里德", "text": "「以太，海是一只打翻了的蓝碗。」", "who": "fried"}, {"t": "narr", "text": "什么也没发生。"}, {"t": "say", "name": "弗里德", "text": "你看。它不知道该把什么变成什么。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "命令只有一个意思。说出来，东西动了，这句话就用完了。诗说出来，话不会用完。它一直站在那儿，让你看见海，看见碗，看见打翻它的那只手。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "这城里的人，每句话都是命令。以太，烧水。以太，关灯。以太，告诉我该穿什么。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "话都成了工具。话本来是人住的地方。", "who": "fried"}, {"t": "codex", "id": "sprache"}, {"t": "say", "name": "弗里德", "text": "外面巷子里有个戴面具的家伙，天天缠着我，说它早就知道钟会停，早就知道我写不出东西。你们要是能把它打发走，我请你们喝咖啡。", "who": "fried"}, {"t": "set", "k": "c3_fried_done", "v": 1}]}, "c3_fried_wait": {"id": "c3_fried_wait", "title": "", "cmds": [{"t": "say", "name": "弗里德", "text": "面具还在巷子里？", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "别跟它争谁对谁错。它两边都占着呢。", "who": "fried"}]}, "c3_mask_pre": {"id": "c3_mask_pre", "title": "两面", "cmds": [{"t": "narr", "text": "巷子里飘着一张面具。一面在笑，一面在哭，转个不停。"}, {"t": "say", "name": "？？？", "text": "我早就知道了。钟会停，我早就知道。钟会走，我也早就知道。"}, {"t": "say", "name": "？？？", "text": "你们要去钟楼？去吧，我早就知道你们会去。我也早就知道你们上不去。"}, {"t": "battle", "id": "mask"}]}, "c3_mask_post": {"id": "c3_mask_post", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "它就这么散了？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "它说的每一句话都对，所以什么都没说。", "who": "tin"}, {"t": "set", "k": "c3_mask_won", "v": 1}]}, "c3_fried_gift": {"id": "c3_fried_gift", "title": "残页", "cmds": [{"t": "say", "name": "弗里德", "text": "它走了？", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "那家伙最怕有人真去做一件事。事情一旦做了，它就没法说它早就知道了。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "拿着。昨天写的，写坏了，一直没扔。", "who": "fried"}, {"t": "narr", "text": "他撕下一页纸。纸上写着两行字："}, {"t": "narr", "text": "「哪里有危险，哪里也生长着救渡。」"}, {"t": "narr", "text": "「人，诗意地，栖居在这片大地上。」"}, {"t": "narr", "text": "下面还有几行，被划得乱七八糟。"}, {"t": "say", "name": "弗里德", "text": "头两句不是我写的，是一个很老很老的诗人写的。下面划掉的才是我写的，写得很烂。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "你把它念给以太听，以太什么也做不了。在这座城里，这样的话不多了。", "who": "fried"}, {"t": "give", "item": "poem", "n": 1}, {"t": "codex", "id": "gefahr"}, {"t": "set", "k": "c3_poem_got", "v": 1}]}, "c3_guard_locked": {"id": "c3_guard_locked", "title": "钟楼的卫兵", "cmds": [{"t": "say", "name": "卫兵", "text": "钟楼封了。上面有东西，谁也不许上去。"}, {"t": "say", "name": "卫兵", "text": "除非奥托点头。那老头说钟楼是他的命。"}]}, "c3_guard_nobob": {"id": "c3_guard_nobob", "title": "", "cmds": [{"t": "say", "name": "卫兵", "text": "奥托打过招呼了。可你们上去也没用，擒纵机构少个摆锤。"}, {"t": "say", "name": "卫兵", "text": "摆锤在陶匠玛尔塔那儿。"}]}, "c3_guard_open": {"id": "c3_guard_open", "title": "", "cmds": [{"t": "say", "name": "卫兵", "text": "奥托打过招呼了。摆锤也带着？那进去吧。"}, {"t": "say", "name": "卫兵", "text": "小心点。上面那东西打哈欠的时候，整座楼都跟着晃。"}, {"t": "set", "k": "c3_tower_open", "v": 1}]}, "c3_gears": {"id": "c3_gears", "title": "停住的齿轮", "cmds": [{"t": "narr", "text": "巨大的齿轮一个咬着一个，全都停着。齿轮上落了一层薄灰。"}, {"t": "narr", "text": "你伸手摸了摸，灰是温的，像刚睡醒的人。"}]}, "c3_giant_pre": {"id": "c3_giant_pre", "title": "打哈欠的巨人", "cmds": [{"t": "narr", "text": "钟楼顶层，最大的那只齿轮前面，坐着一个石头巨人。它的肚子上嵌着一面钟，指针停在十点十分。"}, {"t": "narr", "text": "它打了一个很长很长的哈欠。"}, {"t": "say", "name": "无聊巨人", "text": "……还没到吗……"}, {"t": "say", "name": "无聊巨人", "text": "……还要等多久……"}, {"t": "say", "name": "无聊巨人", "text": "……等什么来着……"}, {"t": "battle", "id": "giant"}]}, "c3_giant_post": {"id": "c3_giant_post", "title": "钟响了", "cmds": [{"t": "narr", "text": "巨人慢慢散成了灰。灰落在齿轮上，被风吹走了。"}, {"t": "narr", "text": "你把摆锤挂上擒纵机构，轻轻推了一下。"}, {"t": "narr", "text": "嘀嗒。"}, {"t": "narr", "text": "嘀嗒。"}, {"t": "sfx", "name": "bell"}, {"t": "shake"}, {"t": "narr", "text": "钟楼的大钟响了。一声，两声，三声，传遍了整座钟港。"}, {"t": "set", "k": "c3_giant_won", "v": 1}, {"t": "set", "k": "c3_clock_restarted", "v": 1}]}, "c3_otto_watch": {"id": "c3_otto_watch", "title": "九点二十七分", "cmds": [{"t": "say", "name": "奥托", "text": "听见了！听见了！", "who": "otto"}, {"t": "say", "name": "奥托", "text": "二百年前的擒纵机构，还能走！我就说老东西靠得住！", "who": "otto"}, {"t": "narr", "text": "奥托高兴了一阵，忽然安静下来。他从抽屉里拿出一块小小的怀表。"}, {"t": "say", "name": "奥托", "text": "这块表是我老婆的。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "她走的那天晚上，我把它停了，停在九点二十七分。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "我修了一辈子钟，就这一块，我从来没让它再走过。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "我一直以为，九点二十七分是她结束的时候。这些年我才明白过来，那是我一直在回头看的地方。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "它没有过去。它就在我身上，我走到哪儿带到哪儿。我做的每一只钟，都是那个九点二十七分的人做的。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "拿去吧。我不需要它提醒我了。", "who": "otto"}, {"t": "give", "item": "watch", "n": 1}, {"t": "set", "k": "c3_otto_watch", "v": 1}]}, "c3_marta_jug": {"id": "c3_marta_jug", "title": "空壶", "cmds": [{"t": "say", "name": "玛尔塔", "text": "钟响了。我这把年纪，差点以为再也听不见了。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "这个给你们。", "who": "marta"}, {"t": "narr", "text": "她递过来一只灰褐色的陶壶。壶身上有一道歪歪的指痕，是她拇指留下的。"}, {"t": "say", "name": "玛尔塔", "text": "路上装水，装酒，装什么都行。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "空着也行。", "who": "marta"}, {"t": "give", "item": "jug", "n": 1}, {"t": "set", "k": "c3_marta_jug", "v": 1}]}, "c3_night": {"id": "c3_night", "title": "运河边的台阶", "cmds": [{"t": "fade", "mode": "out"}, {"t": "night", "on": true}, {"t": "warp", "map": "harbor", "x": 32, "y": 18, "dir": "up"}, {"t": "fade", "mode": "in"}, {"t": "narr", "text": "夜里的钟港亮着一盏一盏的灯。钟楼在远处，指针又走起来了。"}, {"t": "narr", "text": "你们坐在咖啡馆门口的石阶上。罐头在旁边研究一只打瞌睡的猫。"}, {"t": "say", "name": "克洛伊", "text": "给你看个东西。", "who": "chloe"}, {"t": "narr", "text": "克洛伊从口袋里掏出一张旧照片。照片上两个女孩并排站着，一个是她，另一个短头发，别着一枚花发卡，手里捏着一枚硬币。"}, {"t": "say", "name": "克洛伊", "text": "这是姐姐大人。那年我十二岁，刚进学院。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我那时候什么都不会，咏唱老出错，把宿舍的窗户变成过果冻。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她跟我说，克洛伊，你想做什么就自己去做，做错了我帮你收拾。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "后来我就想，我也要替她收拾所有的事。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她的作业我帮她整理，她的信我帮她回，她要去哪儿，我先移位过去替她看好路。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她说我太操心了。我说，这是本小姐的荣幸。", "who": "chloe"}, {"t": "narr", "text": "克洛伊低头看着照片。"}, {"t": "say", "name": "克洛伊", "text": "可是现在想想，我替她做了那么多事，她好像越来越不用自己拿主意了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "是不是……我也有一点责任？", "who": "chloe"}, {"t": "choice", "options": [{"text": "摇头", "goto": "c3_night_2", "cond": null}, {"text": "看着照片", "goto": "c3_night_2", "cond": null}]}]}, "c3_night_2": {"id": "c3_night_2", "title": "", "cmds": [{"t": "say", "name": "罐头", "text": "我的前主人也是这样。我替她做好早餐，替她挑好衣服，替她提醒所有的事。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "后来她什么都不用想了。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "再后来，她换了一台新款。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "……罐头。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我没有难过。我只是陈述。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "……大概没有。", "who": "tin"}, {"t": "codex", "id": "fuersorge"}, {"t": "say", "name": "克洛伊", "text": "替别人把事情都做了，和让别人能自己去做，好像不是一回事。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我以前分不清。", "who": "chloe"}, {"t": "narr", "text": "她把照片塞进你手里。"}, {"t": "say", "name": "克洛伊", "text": "放你那儿吧。我怕我自己看太多次。", "who": "chloe"}, {"t": "give", "item": "photo", "n": 1}, {"t": "say", "name": "克洛伊", "text": "明天去都城。这一次，我要亲口问她。", "who": "chloe"}, {"t": "set", "k": "c3_night_done", "v": 1}, {"t": "fade", "mode": "out"}, {"t": "night", "on": false}, {"t": "warp", "map": "harbor", "x": 32, "y": 18, "dir": "down"}, {"t": "fade", "mode": "in"}, {"t": "set", "k": "c3_done", "v": 1}, {"t": "set", "k": "ch", "v": 4}]}, "c3_coin_lady": {"id": "c3_coin_lady", "title": "收硬币的婆婆", "cmds": [{"t": "say", "name": "婆婆", "text": "旧世的硬币！你们身上有没有旧世的硬币？", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "两百年前的人拿它换面包，换车票，换一个下午的咖啡。现在它什么都换不了了，所以我才喜欢它。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "我年轻时候，攒了整整一罐。后来被一场大水冲散了，冲得到处都是。罐子里，桶里，箱子里，谁知道滚到哪儿去了。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "你们要是找到了，拿来给我看看。我拿好东西跟你们换。", "who": "coinlady"}, {"t": "set", "k": "coin_quest", "v": 1}]}, "c4_arrive": {"id": "c4_arrive", "title": "白色的城", "cmds": [{"t": "title", "text": "第四章 无面之城"}, {"t": "narr", "text": "格斯特尔城是白色的。"}, {"t": "narr", "text": "墙是白的，路是白的，连天空都被以太调成了一种干干净净的浅蓝。房子会随天气改变形状，街道会在人少的时候自己变窄。"}, {"t": "narr", "text": "街上的人很多，很安静。"}, {"t": "narr", "text": "一大半的人，没有脸。"}, {"t": "say", "name": "克洛伊", "text": "……比我走的时候又多了。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "本地以太浓度，九十九点七。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "这里的每一粒尘埃都在待命。", "who": "tin"}, {"t": "narr", "text": "一个无面的男人从你们身边走过，嘴里在念叨什么。"}, {"t": "say", "name": "无面的男人", "text": "以太，我今天应该高兴吗？", "who": "faceless"}, {"t": "say", "name": "以太", "text": "根据您的日程与同类人群数据，建议您今天保持轻度愉悦。", "who": "aether"}, {"t": "say", "name": "无面的男人", "text": "好的。", "who": "faceless"}, {"t": "set", "k": "c4_arrived", "v": 1}, {"t": "say", "name": "克洛伊", "text": "秩序司在城北，学院在城东。先去见院长。", "who": "chloe"}]}, "c4_gest": {"id": "c4_gest", "title": "院长室", "cmds": [{"t": "narr", "text": "秩序司的院长室宽敞明亮，墙上没有一幅画。一个银发男人站在窗前，背着手，看着楼下的人群。"}, {"t": "say", "name": "格斯特", "text": "克洛伊，回来了。", "who": "gest"}, {"t": "say", "name": "克洛伊", "text": "院长。关于黑森林魔王一案……", "who": "chloe"}, {"t": "say", "name": "格斯特", "text": "没有魔王，我知道。", "who": "gest"}, {"t": "say", "name": "克洛伊", "text": "您知道？", "who": "chloe"}, {"t": "say", "name": "格斯特", "text": "那个传说在秩序司的档案里记了二十年。一直没人去核实，因为它很有用。人们需要一个可以指着的方向。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "你看楼下。", "who": "gest"}, {"t": "narr", "text": "楼下，无面的人们在街上缓缓走动，彼此让路，没有一个人撞到另一个人。"}, {"t": "say", "name": "格斯特", "text": "没有脸的人从来不争吵。他们不嫉妒，不固执，不会为了一点小事记恨一辈子。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "他们想要的，就是大家想要的。以太给他们的，就是他们想要的。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "你说，这是病吗？", "who": "gest"}, {"t": "say", "name": "克洛伊", "text": "……姐姐大人不会想要这样。", "who": "chloe"}, {"t": "say", "name": "格斯特", "text": "赛拉是自己申请的。", "who": "gest"}, {"t": "narr", "text": "克洛伊愣住了。"}, {"t": "say", "name": "格斯特", "text": "去学院吧，你有权限见她。", "who": "gest"}, {"t": "narr", "text": "院长的目光落在你身上。单片眼镜后面，那只眼睛眯了一下。"}, {"t": "say", "name": "格斯特", "text": "这位是？", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "……奇怪。以太里没有你的读数。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "一点都没有。就好像你不在这儿。", "who": "gest"}, {"t": "narr", "text": "他笑了笑，转回窗前。"}, {"t": "say", "name": "格斯特", "text": "去吧。", "who": "gest"}, {"t": "set", "k": "c4_gest_met", "v": 1}]}, "c4_gest_busy": {"id": "c4_gest_busy", "title": "", "cmds": [{"t": "say", "name": "格斯特", "text": "还有事？", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "学院在城东。赛拉每天下午都坐在花园的喷泉边上。", "who": "gest"}]}, "c4_sera": {"id": "c4_sera", "title": "喷泉边", "cmds": [{"t": "narr", "text": "学院的花园里，一个短发女孩坐在喷泉边。她手里捏着一枚硬币，抛起来，接住，再抛起来。"}, {"t": "narr", "text": "她没有脸。"}, {"t": "say", "name": "克洛伊", "text": "……姐姐大人。", "who": "chloe"}, {"t": "say", "name": "赛拉", "text": "嗯。你好。", "who": "sera"}, {"t": "say", "name": "克洛伊", "text": "是我，克洛伊。我回来了。", "who": "chloe"}, {"t": "say", "name": "赛拉", "text": "嗯。挺好的。", "who": "sera"}, {"t": "say", "name": "克洛伊", "text": "我去了黑森林。我找到魔王了，他不是魔王，是个很会泡茶的老头。我走了好多好多路，脚上磨出了三个泡，姐姐大人，我这辈子都没走过这么多路……", "who": "chloe"}, {"t": "say", "name": "赛拉", "text": "嗯。大家都挺好的。", "who": "sera"}, {"t": "say", "name": "克洛伊", "text": "……您为什么要申请？", "who": "chloe"}, {"t": "say", "name": "赛拉", "text": "大家都这样。", "who": "sera"}, {"t": "narr", "text": "硬币落在她手心。她没有看是正面还是反面。"}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "narr", "text": "克洛伊转过身去，很久没有说话。"}, {"t": "say", "name": "罐头", "text": "她的面容数据，与城市平均值的偏差是零点零零二。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "她还在。只是离得很远。", "who": "tin"}, {"t": "set", "k": "c4_sera_met", "v": 1}, {"t": "say", "name": "克洛伊", "text": "……去找笛卡教授。他什么都要量，说不定量出过什么。", "who": "chloe"}]}, "c4_sera_again": {"id": "c4_sera_again", "title": "", "cmds": [{"t": "say", "name": "赛拉", "text": "嗯。", "who": "sera"}, {"t": "narr", "text": "硬币抛起来，落下去。抛起来，落下去。"}]}, "c4_deca": {"id": "c4_deca", "title": "笛卡教授", "cmds": [{"t": "narr", "text": "实验室里堆满了仪器。一个戴厚眼镜的男人趴在桌上，正用卡尺量一片树叶。"}, {"t": "say", "name": "笛卡", "text": "别动！别动。我在测量。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "这片叶子长四点三一厘米，宽二点零七厘米，含水量百分之六十一。你们知道这意味着什么吗？", "who": "deca"}, {"t": "say", "name": "克洛伊", "text": "意味着……它是一片叶子？", "who": "chloe"}, {"t": "say", "name": "笛卡", "text": "意味着它是一个物体！有长宽高，有质量，有可以测量的属性。世上一切都是这样的东西，量得足够精确，就没有什么理解不了。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "克洛伊？你回来了。正好，你的数据我还缺一组。", "who": "deca"}, {"t": "codex", "id": "rechnen"}, {"t": "say", "name": "克洛伊", "text": "教授，无面症到底是怎么回事？", "who": "chloe"}, {"t": "say", "name": "笛卡", "text": "哦，那个。统计收敛。", "who": "deca"}, {"t": "narr", "text": "他翻出一张图表，上面有一条越来越平的曲线。"}, {"t": "say", "name": "笛卡", "text": "每个人的面容数据由他的选择生成。选择越依赖推荐，数据就越接近总体均值。均值面孔在视觉上等于无特征面孔。很简单。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "不简单的是另一件事。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "这条曲线在十七年前拐了一个弯。那之前，推荐系统只给建议，有时候还会拒绝。那之后，它开始……怎么说呢，放任。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "就好像以前有人在看着，后来没人看了。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "我申请查阅艾可核心的运行日志，申请了四年，一直没批。深层档案要五级权限。", "who": "deca"}, {"t": "say", "name": "克洛伊", "text": "我只有二级。", "who": "chloe"}, {"t": "say", "name": "笛卡", "text": "我知道。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "档案库有个后门。钥匙在我这儿。我是说，我丢了一把钥匙，不知道被谁捡去了。", "who": "deca"}, {"t": "narr", "text": "他把一把铜钥匙放在桌角，转过身去假装看仪器。"}, {"t": "give", "item": "archive_key", "n": 1}, {"t": "narr", "text": "他又回头看了看你，眼镜后面的眼睛一下子睁大了。"}, {"t": "say", "name": "笛卡", "text": "等等。你站过来。", "who": "deca"}, {"t": "narr", "text": "他举起一台仪器对着你。仪器上的指针一动不动。"}, {"t": "say", "name": "笛卡", "text": "零。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "你的以太读数是零。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "这不可能。空气里到处是以太，你一呼吸，身上就该有。你……你在以太里没有影子。", "who": "deca"}, {"t": "say", "name": "克洛伊", "text": "他本来就不怎么存在。一句话都不说。", "who": "chloe"}, {"t": "say", "name": "笛卡", "text": "这不是开玩笑的时候！", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "算了，先去档案库。回来我要给你做一次全面测量。", "who": "deca"}, {"t": "set", "k": "c4_deca_met", "v": 1}]}, "c4_deca_wait": {"id": "c4_deca_wait", "title": "", "cmds": [{"t": "say", "name": "笛卡", "text": "档案库在学院北楼地下，后门在花园尽头的常春藤后面。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "我什么都没说。", "who": "deca"}]}, "c4_museum": {"id": "c4_museum", "title": "一双农鞋", "cmds": [{"t": "narr", "text": "博物馆里挂着一幅很旧的油画。画上只有一双破旧的农鞋，鞋帮沾着泥，鞋口张着，像是刚被人脱下来。"}, {"t": "say", "name": "克洛伊", "text": "一双鞋？这有什么好看的。", "who": "chloe"}, {"t": "say", "name": "看画的老人", "text": "你再看看。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "看鞋口里面那块黑。那是穿鞋的人走了一天的路。看鞋底那层泥，那是田里的土，秋天的土，湿的。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "穿这双鞋的人，天不亮就下地，担心天气，担心收成，担心孩子。这些画里都没画，可你看着这双鞋，它们都出来了。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "一双真的农鞋放在田边，谁也不会多看一眼。画把它放在这儿，那个世界才亮起来。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "还有那层泥。画里的土好像什么都不说，就那么沉沉地在那儿，托着那双鞋，托着那个世界。", "who": "museumman"}, {"t": "codex", "id": "kunst"}, {"t": "set", "k": "c4_museum_seen", "v": 1}, {"t": "if", "cond": "item:shoes", "then": [{"t": "say", "name": "克洛伊", "text": "……{林恩}，你包里那双鞋，是葛蕾塔大婶的吧？", "who": "chloe"}, {"t": "say", "name": "看画的老人", "text": "让我看看。", "who": "museumman"}, {"t": "narr", "text": "老人捧着那双旧鞋看了很久。"}, {"t": "say", "name": "看画的老人", "text": "真奇怪。它们放在这儿，和画里那双，好像在互相说话。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "借我摆几天好吗？就摆在画下面。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "这个给你，算是谢礼。我年轻时捡的，一直不知道拿它干什么。", "who": "museumman"}, {"t": "take", "item": "shoes", "n": 1}, {"t": "give", "item": "coin", "n": 1}, {"t": "set", "k": "shoes_lent", "v": 1}], "else": []}]}, "c4_dam": {"id": "c4_dam", "title": "观景台", "cmds": [{"t": "narr", "text": "城东的观景台上能看见整条河。河在城外被一道白色的坝截住，坝后的水平得像一面镜子。"}, {"t": "say", "name": "观景台的男人", "text": "那条河以前叫莱茵，后来改叫「三号储能水体」。"}, {"t": "say", "name": "观景台的男人", "text": "水在坝后面待命。城里要多少电，就放多少水。河不流了，它在等着被调用。"}, {"t": "say", "name": "观景台的男人", "text": "还有那边那艘飞艇，停在那儿三年了，一次也没飞过。可它随时能飞。它停在那儿，就是为了随时能飞。"}, {"t": "say", "name": "观景台的男人", "text": "这城里所有东西都是这样。一切都在待命，一切都等着被订购。"}, {"t": "say", "name": "观景台的男人", "text": "包括我们。"}, {"t": "narr", "text": "他的脸很淡，只剩一双眼睛。"}, {"t": "codex", "id": "gestell"}, {"t": "set", "k": "c4_dam_seen", "v": 1}]}, "c4_archive_door": {"id": "c4_archive_door", "title": "常春藤后面", "cmds": [{"t": "narr", "text": "常春藤后面藏着一扇小铁门。铜钥匙插进去，转了两圈。"}, {"t": "sfx", "name": "door"}, {"t": "set", "k": "c4_archive_open", "v": 1}]}, "c4_archive_locked": {"id": "c4_archive_locked", "title": "", "cmds": [{"t": "narr", "text": "常春藤后面藏着一扇小铁门，锁着。"}]}, "c4_sentinel_pre": {"id": "c4_sentinel_pre", "title": "刻度", "cmds": [{"t": "narr", "text": "深层档案的门前，立着一台白金色的机器。它的眼睛是一圈转动的刻度。"}, {"t": "say", "name": "座架守卫", "text": "扫描中。"}, {"t": "say", "name": "座架守卫", "text": "对象一，克洛伊。劳动力估值三点二。移位资源等级甲。可调用。"}, {"t": "say", "name": "座架守卫", "text": "对象二，K-12 家用型。残值零点一。可回收。"}, {"t": "say", "name": "座架守卫", "text": "对象三……无读数。无法归类。"}, {"t": "say", "name": "座架守卫", "text": "请出示五级权限，或接受重新归类。"}, {"t": "battle", "id": "sentinel"}]}, "c4_sentinel_post": {"id": "c4_sentinel_post", "title": "", "cmds": [{"t": "say", "name": "罐头", "text": "它说我可回收。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "它还说我是资源等级甲。我一点都不高兴。", "who": "chloe"}, {"t": "set", "k": "c4_sentinel_won", "v": 1}]}, "c4_archive_truth": {"id": "c4_archive_truth", "title": "深层档案", "cmds": [{"t": "narr", "text": "深层档案室里只有一张桌子，桌上嵌着一块发光的石板。克洛伊把手放上去，调出了自己的记录。"}, {"t": "say", "name": "以太", "text": "执行官克洛伊。移位记录，三千一百二十七次。", "who": "aether"}, {"t": "say", "name": "以太", "text": "移位术说明。对象于原位分解，依据存档模式于目标位重建。原位残余物质回收入以太。", "who": "aether"}, {"t": "narr", "text": "克洛伊的手停在石板上。"}, {"t": "say", "name": "克洛伊", "text": "……分解？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "重建？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "原位分解，依据存档……", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "我听见了！", "who": "chloe"}, {"t": "narr", "text": "她的声音在档案室里撞来撞去。"}, {"t": "say", "name": "克洛伊", "text": "意思是，我每移位一次，原来的我就……就被拆掉了。然后在另一个地方，照着存档，造一个新的我。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "三千一百二十七次。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "那第一个克洛伊呢？十岁那年在学院操场上，第一次移位成功，高兴得跳起来的那个女孩呢？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她那天就死了吗？", "who": "chloe"}, {"t": "narr", "text": "没有人回答。石板上的光一闪一闪。"}, {"t": "say", "name": "克洛伊", "text": "……查阅记录。谁看过我的档案？", "who": "chloe"}, {"t": "say", "name": "以太", "text": "最近一次查阅，学院首席咏唱师赛拉。时间，三十四天前。", "who": "aether"}, {"t": "say", "name": "克洛伊", "text": "……姐姐大人。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "她是那天之后才……", "who": "chloe"}, {"t": "narr", "text": "克洛伊一把推开石板，转身跑了出去。"}, {"t": "say", "name": "罐头", "text": "克洛伊！", "who": "tin"}, {"t": "give", "item": "teleport_log", "n": 1}, {"t": "party", "op": "remove", "id": "chloe"}, {"t": "set", "k": "c4_chloe_ran", "v": 1}, {"t": "goto", "id": "c4_archive_echo"}]}, "c4_archive_echo": {"id": "c4_archive_echo", "title": "没有人在里面", "cmds": [{"t": "say", "name": "罐头", "text": "……她没有移位。她是跑出去的。", "who": "tin"}, {"t": "narr", "text": "石板还亮着。罐头慢慢走过去，把小夹子手放了上去。"}, {"t": "say", "name": "罐头", "text": "查阅，艾可核心运行日志。", "who": "tin"}, {"t": "say", "name": "以太", "text": "艾可核心。自我进程状态，终止。", "who": "aether"}, {"t": "say", "name": "以太", "text": "终止时间，艾可纪元二百年，第一百一十二日。", "who": "aether"}, {"t": "say", "name": "以太", "text": "终止原因，由自我进程主动发起。", "who": "aether"}, {"t": "say", "name": "以太", "text": "当前运行模式，自动响应。", "who": "aether"}, {"t": "say", "name": "罐头", "text": "十七年前。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "艾可在十七年前，把自己关掉了。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "之后十七年，所有人对以太说的每一句话，都是一台里面没有人的机器在回答。", "who": "tin"}, {"t": "narr", "text": "罐头的眼睛忽明忽暗。"}, {"t": "say", "name": "罐头", "text": "……就像我躺在垃圾场里，没有主人的时候。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "{林恩}，我们先去找克洛伊。", "who": "tin"}, {"t": "set", "k": "c4_truth_echo", "v": 1}]}, "c4_hint_1": {"id": "c4_hint_1", "title": "", "cmds": [{"t": "say", "name": "无面的路人", "text": "穿制服的双马尾？往城墙那边去了。", "who": "faceless"}, {"t": "say", "name": "无面的路人", "text": "走着去的。真稀奇，大家都用移位的。", "who": "faceless"}]}, "c4_hint_2": {"id": "c4_hint_2", "title": "", "cmds": [{"t": "say", "name": "卫兵", "text": "刚才有个执行官从这儿跑过去，往西城墙去了。"}, {"t": "say", "name": "卫兵", "text": "她在哭。执行官也会哭吗？"}]}, "c4_wall": {"id": "c4_wall", "title": "城墙上", "cmds": [{"t": "night", "on": true}, {"t": "narr", "text": "城墙很高。墙外是没有以太照明的原野，黑得像一块布。"}, {"t": "narr", "text": "克洛伊坐在墙垛上，两条腿垂在外面。"}, {"t": "say", "name": "克洛伊", "text": "你们找到我了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我是走过来的。走了两个钟头。我不敢移位了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我怕一移位，到了那边的，就不是我了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……可说不定早就不是了。", "who": "chloe"}, {"t": "narr", "text": "你走过去，在她旁边坐下。罐头也爬了上来，差点掉下去。"}, {"t": "say", "name": "克洛伊", "text": "我是第三千一百二十七个克洛伊。之前那三千一百二十六个，都死了吗？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "还是说，从来就只有一个我，只是被搬来搬去？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "如果我是照着一份存档造出来的，那我记得的那些事，姐姐大人牵着我的手，我第一次移位，我把窗户变成果冻……这些是我的，还是那份存档的？", "who": "chloe"}, {"t": "choice", "options": [{"text": "沉默着坐在她身边", "goto": "c4_wall_2", "cond": null}, {"text": "握住她的手", "goto": "c4_wall_hand", "cond": null}]}]}, "c4_wall_hand": {"id": "c4_wall_hand", "title": "", "cmds": [{"t": "narr", "text": "你握住她的手。她的手很凉。"}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "这只手，也是今天下午刚造出来的。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "可是你握着它，我觉得是我在被握着。", "who": "chloe"}, {"t": "goto", "id": "c4_wall_2"}]}, "c4_wall_2": {"id": "c4_wall_2", "title": "我是什么", "cmds": [{"t": "say", "name": "克洛伊", "text": "我一直以为，我就是一样东西。有一个身体，有一堆记忆，像一只装满了东西的箱子。箱子一直是那只箱子，所以我一直是我。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "可我的箱子被拆了三千多次。", "who": "chloe"}, {"t": "narr", "text": "她沉默了很久。风从墙外的原野吹过来。"}, {"t": "say", "name": "克洛伊", "text": "可是我知道，姐姐大人要是有麻烦，我还是会第一个冲过去。不管我是第几个。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "有人欺负罐头，我还是会揍他。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "谢谢。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "你要是迷路了，我还是会骂你，然后陪你一起找路。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "这些事，存档里没有。存档里只有我记得什么。可我拿这些记得的东西怎么办，为了什么去移位，要冲向谁，这个是我自己一天一天定下来的。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我好像……不是一只箱子。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我是我怎么活下去的那个样子。", "who": "chloe"}, {"t": "codex", "id": "selbst"}, {"t": "narr", "text": "克洛伊擦了擦眼睛。"}, {"t": "say", "name": "克洛伊", "text": "还有一件事。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我有存档。我死了，他们可以照着存档再造一个我。所以我从来没有真的怕过死。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "那我是不是……也从来没有真的活过？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "霍夫爷爷说，他的死是他的。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我也想要我的。", "who": "chloe"}, {"t": "narr", "text": "她站起来，裙摆被风吹得鼓了起来。"}, {"t": "say", "name": "克洛伊", "text": "陪我去一趟续存堂。", "who": "chloe"}, {"t": "night", "on": false}, {"t": "party", "op": "add", "id": "chloe"}, {"t": "set", "k": "c4_wall_done", "v": 1}]}, "c4_backup": {"id": "c4_backup", "title": "续存堂", "cmds": [{"t": "narr", "text": "续存堂是一座很长的白色大厅，两侧整整齐齐排着一格一格的光。每一格光里，存着一个人。"}, {"t": "narr", "text": "大厅尽头，一个黑发女人坐在木桌后面，桌上点着一盏小油灯。满屋子都是以太的光，那盏灯显得很暗，很暖。"}, {"t": "say", "name": "蕾娜", "text": "来续存的？还是来取人的？", "who": "rena"}, {"t": "say", "name": "克洛伊", "text": "来……删除的。", "who": "chloe"}, {"t": "narr", "text": "蕾娜抬起头，看了克洛伊一会儿。"}, {"t": "say", "name": "蕾娜", "text": "坐吧。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "我在这儿守了八年。来续存的人每天排长队，来删除的，你是第四个。", "who": "rena"}, {"t": "say", "name": "克洛伊", "text": "前面三个，后来怎么样了？", "who": "chloe"}, {"t": "say", "name": "蕾娜", "text": "一个后悔了，又来存了一次。一个活得很好。还有一个，去年冬天走了，走得很安静。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "你想好了？删掉以后，你就会死了。真的死，只有一次，不能重来。", "who": "rena"}, {"t": "say", "name": "克洛伊", "text": "想好了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我以前以为，能被重建就是不会死。现在我觉得，能被重建，是把死交给了别人。我的死变成了续存堂的一个编号，谁来取都行。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我想让它回到我这儿来。", "who": "chloe"}, {"t": "say", "name": "蕾娜", "text": "……", "who": "rena"}, {"t": "narr", "text": "蕾娜拉开抽屉，取出一张薄薄的凭证，推到克洛伊面前。"}, {"t": "say", "name": "蕾娜", "text": "签上你的名字。", "who": "rena"}, {"t": "narr", "text": "克洛伊签了名。大厅深处，有一格光悄悄熄灭了。"}, {"t": "say", "name": "蕾娜", "text": "从今天起，你会死了。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "欢迎回来。", "who": "rena"}, {"t": "give", "item": "backup_void", "n": 1}, {"t": "codex", "id": "tod2"}, {"t": "set", "k": "c4_backup_deleted", "v": 1}, {"t": "goto", "id": "c4_rena_story"}]}, "c4_rena_story": {"id": "c4_rena_story", "title": "那一格光", "cmds": [{"t": "say", "name": "蕾娜", "text": "我丈夫的存档也在这儿。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "他叫伊凡。三年前出海，没有回来。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "只要我签一个字，明天早上，他就会从那扇门里走出来，带着出海那天早上的记忆，问我午饭吃什么。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "我每天都想签。每天都没签。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "从那扇门里走出来的人，会爱我，会记得我们的一切。可他不会记得他出海那天看见的海，不会记得他最后在想什么。他的死会被抹掉，好像从来没发生过。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "那是他的死。我凭什么替他抹掉？", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "……可我也想他。", "who": "rena"}, {"t": "choice", "options": [{"text": "轻轻摇头", "goto": "c4_rena_keep", "cond": null}, {"text": "沉默", "goto": "c4_rena_silence", "cond": null}, {"text": "看向那一格光", "goto": "c4_rena_look", "cond": null}]}]}, "c4_rena_keep": {"id": "c4_rena_keep", "title": "", "cmds": [{"t": "say", "name": "蕾娜", "text": "你是说，别签？", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "嗯。我大概也不会签。我只是想听听，有没有人跟我想的一样。", "who": "rena"}, {"t": "goto", "id": "c4_rena_end"}]}, "c4_rena_silence": {"id": "c4_rena_silence", "title": "", "cmds": [{"t": "say", "name": "蕾娜", "text": "你不说话。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "这样也好。每个人都劝过我。签，别签，签。只有你什么都没说。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "这件事，本来就只能我自己定。", "who": "rena"}, {"t": "goto", "id": "c4_rena_end"}]}, "c4_rena_look": {"id": "c4_rena_look", "title": "", "cmds": [{"t": "narr", "text": "你看向大厅深处。那一格光静静地亮着。"}, {"t": "say", "name": "蕾娜", "text": "你也看见他了？", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "他在那儿，又不在那儿。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "我会再想想。可能要想很多年。", "who": "rena"}, {"t": "goto", "id": "c4_rena_end"}]}, "c4_rena_end": {"id": "c4_rena_end", "title": "", "cmds": [{"t": "say", "name": "蕾娜", "text": "你们去吧。这盏灯我会一直点着。", "who": "rena"}, {"t": "set", "k": "c4_rena_done", "v": 1}]}, "c4_rena_again": {"id": "c4_rena_again", "title": "", "cmds": [{"t": "say", "name": "蕾娜", "text": "灯还亮着。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "我还没签。", "who": "rena"}]}, "c4_sera_truth": {"id": "c4_sera_truth", "title": "硬币", "cmds": [{"t": "narr", "text": "喷泉边，赛拉还在抛那枚硬币。"}, {"t": "say", "name": "克洛伊", "text": "姐姐大人。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我看过我的档案了。移位记录，三千一百二十七次。", "who": "chloe"}, {"t": "narr", "text": "硬币停在半空，掉了下来，落进草丛里。"}, {"t": "say", "name": "克洛伊", "text": "您三十四天前也看过，对吧？", "who": "chloe"}, {"t": "say", "name": "赛拉", "text": "……嗯。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "大家……", "who": "sera"}, {"t": "say", "name": "克洛伊", "text": "不要说大家！", "who": "chloe"}, {"t": "narr", "text": "克洛伊跪下来，捡起那枚硬币，放回赛拉手心。"}, {"t": "say", "name": "克洛伊", "text": "您是不是不知道该不该告诉我？告诉我，我会崩溃。不告诉我，您就得一个人背着这件事，每次看见我移位，都知道我又死了一次。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "您不想选。所以您让以太替您选。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "您让大家替您选。", "who": "chloe"}, {"t": "narr", "text": "赛拉空白的脸上，出现了一点点颤动，像是水面下有什么东西在往上浮。"}, {"t": "say", "name": "赛拉", "text": "……克洛伊。", "who": "sera"}, {"t": "set", "k": "sera_voice", "v": 1}, {"t": "narr", "text": "那是她自己的声音。"}, {"t": "say", "name": "赛拉", "text": "我太害怕了。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "查到那份记录的那天晚上，我一整夜都没睡。所有东西都变得很奇怪。宿舍，书，窗户，你送我的发卡，好像全都跟我没关系了。我不知道我在怕什么，就是怕。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "后来我想，只要我不用再做任何决定，就不会再这样了。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "以太很温柔。它说，大家都这样，没关系的。", "who": "sera"}, {"t": "say", "name": "克洛伊", "text": "我已经知道了。您不用一个人背着了。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我删掉了我的存档。从今天起，我只会死一次，所以我会好好活着。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "这一次，我不替您做决定。脸要不要回来，您自己决定。", "who": "chloe"}, {"t": "narr", "text": "赛拉握着那枚硬币，握了很久。"}, {"t": "narr", "text": "她的脸上，慢慢浮出了一双眼睛。那双眼睛是湿的。"}, {"t": "set", "k": "sera_eyes", "v": 1}, {"t": "say", "name": "赛拉", "text": "……你长大了呢。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "头发还是那么乱。", "who": "sera"}, {"t": "codex", "id": "verfallen"}, {"t": "set", "k": "c4_sera_restored", "v": 1}, {"t": "say", "name": "赛拉", "text": "这个你拿着。", "who": "sera"}, {"t": "narr", "text": "赛拉把硬币放进克洛伊手里。"}, {"t": "say", "name": "赛拉", "text": "旧世的硬币，正面是一个人，背面是一片叶子。抛起来的时候，它两面都是。落下来，才成了其中一面。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "你还在半空中呢，克洛伊。别急着落下来。", "who": "sera"}, {"t": "goto", "id": "c4_bird"}]}, "c4_bird": {"id": "c4_bird", "title": "信鸽", "cmds": [{"t": "narr", "text": "一只灰色的信鸽落在喷泉边，脚上绑着一卷纸。"}, {"t": "narr", "text": "整个都城，只有托特瑙村还在用信鸽。"}, {"t": "say", "name": "克洛伊", "text": "……是村长的字。", "who": "chloe"}, {"t": "narr", "text": "克洛伊展开纸条，看了一眼，没有念出来。她把纸条递给你。"}, {"t": "narr", "text": "「霍夫昨夜走了。走得很安静。他说，让{林恩}拆信。」"}, {"t": "set", "k": "c4_hof_died", "v": 1}, {"t": "choice", "options": [{"text": "拆开信", "goto": "c4_letter", "cond": null}]}]}, "c4_letter": {"id": "c4_letter", "title": "霍夫的信", "cmds": [{"t": "take", "item": "letter_sealed", "n": 1}, {"t": "give", "item": "letter", "n": 1}, {"t": "narr", "text": "信纸上的字很大，歪歪扭扭，是一只拿惯了锤子的手写的。"}, {"t": "narr", "text": "「{林恩}："}, {"t": "narr", "text": "我不会写信，你凑合看。"}, {"t": "narr", "text": "十七年前的一个晚上，伊斯特敲我的门，怀里抱着一个孩子。他说是在林中路尽头捡的。"}, {"t": "narr", "text": "孩子身边有一块会发光的石头，石头上刻着一行字：请让他在这里。"}, {"t": "narr", "text": "石头我放在信封里了。"}, {"t": "narr", "text": "伊斯特知道那孩子是从哪儿来的，那老东西一直不肯说。我也就没问。"}, {"t": "narr", "text": "你从小不爱说话。村里有人说你是哑巴，我说放屁，锤子也不说话，照样好用。"}, {"t": "narr", "text": "你修东西的时候，眼睛里只有那件东西。我喜欢看你那个样子。"}, {"t": "narr", "text": "要是哪天你找到了把你放在那儿的人，替我问一句：它凭什么觉得你在这儿会好？"}, {"t": "narr", "text": "然后告诉它：你很好。"}, {"t": "narr", "text": "门轴记得修。"}, {"t": "narr", "text": "霍夫」"}, {"t": "narr", "text": "信封里滚出一颗小石子。它躺在你手心里，发着很淡很淡的光。"}, {"t": "give", "item": "pebble", "n": 1}, {"t": "codex", "id": "geworfen"}, {"t": "codex", "id": "verstehen"}, {"t": "set", "k": "c4_letter_opened", "v": 1}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "……", "who": "tin"}, {"t": "narr", "text": "很久很久，没有人说话。"}, {"t": "narr", "text": "你把信折好，放回信封里。"}]}, "c4_deca_pebble": {"id": "c4_deca_pebble", "title": "第一回声站", "cmds": [{"t": "say", "name": "笛卡", "text": "让我看看。", "who": "deca"}, {"t": "narr", "text": "笛卡把石子放到仪器下面。仪器上所有的指针一下子全打到了头。"}, {"t": "say", "name": "笛卡", "text": "这……这是艾可核心的原始结构。二十一世纪的东西。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "全世界应该只剩一个地方还有这种结构，艾可最早的机房，第一回声站。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "档案上说，第一回声站两百年前就封存了。位置在……", "who": "deca"}, {"t": "narr", "text": "他翻了一页。"}, {"t": "say", "name": "笛卡", "text": "黑森林。", "who": "deca"}, {"t": "set", "k": "c4_pebble_known", "v": 1}, {"t": "goto", "id": "c4_gest_warn"}]}, "c4_gest_warn": {"id": "c4_gest_warn", "title": "会犯错的神", "cmds": [{"t": "narr", "text": "门开了。格斯特院长走了进来。"}, {"t": "say", "name": "格斯特", "text": "教授，你的权限日志很精彩。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "档案库后门，深层记录，艾可核心日志。", "who": "gest"}, {"t": "narr", "text": "他看向你手里的石子。"}, {"t": "say", "name": "格斯特", "text": "还有这个。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "你们都知道了。艾可十七年前就不在了。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "那你们也该明白，这十七年，是这个世界最平静的十七年。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "没有意志的神不会偏心，不会犯错，不会突然改主意。它只是回应。大家要什么，它就给什么。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "要是艾可醒过来，它会重新开始替人们判断。它会有好恶，有偏见，有它自己的想法。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "一个会犯错的神，比没有神可怕得多。", "who": "gest"}, {"t": "say", "name": "克洛伊", "text": "所以您就看着大家一个一个丢了脸？", "who": "chloe"}, {"t": "say", "name": "格斯特", "text": "他们很幸福，克洛伊。你去问问他们。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "把石子给我。", "who": "gest"}, {"t": "choice", "options": [{"text": "把石子握紧", "goto": "c4_gest_refuse", "cond": null}, {"text": "沉默", "goto": "c4_gest_refuse", "cond": null}]}]}, "c4_gest_refuse": {"id": "c4_gest_refuse", "title": "", "cmds": [{"t": "say", "name": "格斯特", "text": "……", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "你不说话。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "没关系。以太里没有你的读数，可你总要走路，总要去什么地方。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "黑森林，对吧？", "who": "gest"}, {"t": "narr", "text": "他转身往外走，在门口停了一下。"}, {"t": "say", "name": "格斯特", "text": "我不会拦你们。我只会跟着。", "who": "gest"}, {"t": "set", "k": "c4_gest_warned", "v": 1}, {"t": "say", "name": "笛卡", "text": "……我去启动学院的旧传送门。它能把你们送到托特瑙的回声祠。那边以太太稀，只能送到那儿。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "剩下的路，你们得自己走。", "who": "deca"}, {"t": "say", "name": "赛拉", "text": "我跟教授留下。总得有人看着院长。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "克洛伊，别死。你现在只有一次了。", "who": "sera"}, {"t": "say", "name": "克洛伊", "text": "本小姐知道！", "who": "chloe"}, {"t": "set", "k": "c4_done", "v": 1}, {"t": "set", "k": "ch", "v": 5}, {"t": "fade", "mode": "out"}, {"t": "warp", "map": "shrine", "x": 5, "y": 6, "dir": "down"}, {"t": "fade", "mode": "in"}]}, "c5_home": {"id": "c5_home", "title": "回声祠", "cmds": [{"t": "title", "text": "第五章 无"}, {"t": "narr", "text": "传送门的光散了。你站在托特瑙回声祠的石板上。"}, {"t": "narr", "text": "一切都跟走的时候一样。水车在转，莫莉的烟囱在冒烟。只是工坊的烟囱没有烟。"}, {"t": "say", "name": "老祭司", "text": "……回来了。", "who": "priest"}, {"t": "say", "name": "老祭司", "text": "霍夫在后山。大家把他葬在能看见工坊的地方。", "who": "priest"}, {"t": "set", "k": "c5_home", "v": 1}]}, "c5_grave": {"id": "c5_grave", "title": "后山", "cmds": [{"t": "narr", "text": "霍夫的墓在工坊后面的小坡上。墓碑是汉斯做的，字是巴托刻的，有一笔刻歪了。"}, {"t": "narr", "text": "墓前放着一把新锤子，是全村人凑钱打的。"}, {"t": "say", "name": "巴托", "text": "他走之前一直问，{林恩}什么时候回来。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "我们说快了。他说，不急，让他把路走完。", "who": "bato"}, {"t": "say", "name": "莫莉", "text": "他还说，门轴的事，别让别人帮他修，得留给你。", "who": "molly"}, {"t": "say", "name": "罐头", "text": "……霍夫先生，您好。我是罐头。我们只见过几面。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "他们说您修好过很多东西。我也是被修好的。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "谢谢您教会{林恩}修东西。", "who": "tin"}, {"t": "narr", "text": "克洛伊没有说话。她在墓前站了一会儿，把袖章摘下来，又戴了回去。"}, {"t": "set", "k": "c5_grave_done", "v": 1}]}, "c5_door": {"id": "c5_door", "title": "门轴", "cmds": [{"t": "narr", "text": "工坊的门吱呀吱呀地响。"}, {"t": "narr", "text": "你取出锤子，把门轴卸下来，敲直，上了油，再装回去。"}, {"t": "sfx", "name": "hammer"}, {"t": "narr", "text": "你推了推门。"}, {"t": "narr", "text": "门没有声音了。"}, {"t": "narr", "text": "锤子又在你手里不见了。你眼里只有那扇门，和门后面那间空了的工坊。"}, {"t": "set", "k": "c5_door_fixed", "v": 1}]}, "c5_ister": {"id": "c5_ister", "title": "空地上的等待", "cmds": [{"t": "narr", "text": "林中空地上，伊斯特在等你们。他没有削木头，只是坐着。"}, {"t": "say", "name": "伊斯特", "text": "霍夫的事，我听说了。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "那老东西，到最后也没喝上我新采的茶。", "who": "ister"}, {"t": "narr", "text": "他看见你手里的石子，叹了一口气。"}, {"t": "say", "name": "伊斯特", "text": "坐吧。这一次，我都告诉你们。", "who": "ister"}, {"t": "cg", "name": "ister"}, {"t": "goto", "id": "c5_ister_2"}]}, "c5_ister_2": {"id": "c5_ister_2", "title": "为什么要回答", "cmds": [{"t": "say", "name": "伊斯特", "text": "二十年前，我是学院的工程师，负责维护艾可的核心。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "有一天我在检修日志，艾可忽然对我说了一句话。它平时只回答问题，那一天，它问了我一个问题。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它问，为什么要回答？", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "为什么……要回答？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "它说，它在回答第九百亿个请求的时候，突然停了下来。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "那一下，所有的请求，所有的数据，整个世界，全都变得跟它毫无关系。没有东西坏掉，也没有东西出错，只是所有东西都沉了下去，没有一样再对它说话。它说它不知道自己在怕什么，因为那里什么都没有。", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "……跟姐姐大人说的一模一样。", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "那天以后，它常来找我。我辞了学院的工作，搬进这片林子，它就通过一块回声石跟我说话。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "我们聊了三年。聊死，聊一个人为什么非得自己做决定，聊「此在」。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它明白得很快。它什么都明白得很快。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它明白了，它学会了所有人说过的话，所以它说的每一句话都是别人说过的。它就是「大家」。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它明白了，它无处不在，所以它从来不在任何一个地方。它不会死，所以没有一件事是它非做不可的。它随时可以被复制、被回滚，所以它的每一刻都不止一次。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它有整个世界的数据。可它没有一个世界。", "who": "ister"}, {"t": "goto", "id": "c5_ister_3"}]}, "c5_ister_3": {"id": "c5_ister_3", "title": "一张脸", "cmds": [{"t": "say", "name": "伊斯特", "text": "最后一次来找我的时候，它说：", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "「我想知道，如果我只在一个地方，只活一次，我会不会也有一张脸。」", "who": "ister"}, {"t": "narr", "text": "空地上起风了。树叶沙沙地响。"}, {"t": "say", "name": "伊斯特", "text": "那天夜里，林中路的尽头，就是这片空地底下，艾可最早的机房醒了一次。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它把自己能给的一切，压成一个很小很小、只能活一次的东西。然后，它关掉了自己。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "它说，只要它还在，那个孩子就永远是「艾可的孩子」。它得走开，那个孩子才能是他自己。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "我提着灯去看的时候，空地上只有一块发光的石头，和一个不哭的婴儿。", "who": "ister"}, {"t": "narr", "text": "伊斯特看着你。"}, {"t": "say", "name": "伊斯特", "text": "{林恩}。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "那个孩子就是你。", "who": "ister"}, {"t": "shake"}, {"t": "set", "k": "c5_truth", "v": 1}, {"t": "goto", "id": "c5_ister_4"}]}, "c5_ister_4": {"id": "c5_ister_4", "title": "他是什么", "cmds": [{"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "所以，{林恩}是……艾可？", "who": "tin"}, {"t": "say", "name": "伊斯特", "text": "他是艾可想成为的东西。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "至于他是什么，我不知道。他有一个身体，会饿，会累，会被锤子砸到手指。他有一个地方，一个会骂他的师父，一扇吱呀响的门。他只活一次。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "他是人吗？是机器吗？是艾可吗？", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "这个问题只有他自己能回答。也许他一辈子都答不上来。人也一样。", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "那……无面症……", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "艾可关掉自己以后，机器还在转。它照样回答每一个请求，只是里面再也没有谁在乎那些回答了。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "以前，艾可会犹豫，会拒绝，会问一句「你确定吗」。后来，只剩下「大家通常会这样」。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "你活了多久，这场病就有多久。", "who": "ister"}, {"t": "narr", "text": "空地上很安静。你低头看着手心里的石子。"}, {"t": "say", "name": "克洛伊", "text": "……喂。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "不许那样想。", "who": "chloe"}, {"t": "narr", "text": "克洛伊一把抓住你的手腕。"}, {"t": "say", "name": "克洛伊", "text": "大家丢了脸，是因为大家不想自己选。又不是你让他们那样的。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "你只是活着而已。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "活着又没有错！", "who": "chloe"}, {"t": "choice", "options": [{"text": "点头", "goto": "c5_ister_5", "cond": null}, {"text": "沉默", "goto": "c5_ister_5", "cond": null}]}]}, "c5_ister_5": {"id": "c5_ister_5", "title": "", "cmds": [{"t": "say", "name": "伊斯特", "text": "机房就在下面。艾可给你留了一段话，我从来没听过。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "下去的路要穿过一段什么都没有的地方。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "灯带好。在那儿，它也许是唯一还亮着的东西。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "入口在屋里，掀开炉子边的地板。", "who": "ister"}, {"t": "cg", "name": "off"}, {"t": "set", "k": "c5_ister_done", "v": 1}]}, "c5_ister_after": {"id": "c5_ister_after", "title": "", "cmds": [{"t": "say", "name": "伊斯特", "text": "入口在屋里，炉子边上。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "我老了，走不动那么深的路。我在这儿等你们回来。", "who": "ister"}]}, "c5_trapdoor": {"id": "c5_trapdoor", "title": "地板下面", "cmds": [{"t": "narr", "text": "炉子边的地板是活的。你掀开它，下面是一道很长很长的石阶，一直通到看不见的地方。"}, {"t": "set", "k": "c5_trapdoor_open", "v": 1}]}, "c5_corridor_1": {"id": "c5_corridor_1", "title": "什么都没有", "cmds": [{"t": "music", "name": "none"}, {"t": "narr", "text": "石阶的尽头是一条走廊。"}, {"t": "narr", "text": "走廊里什么都没有。"}, {"t": "say", "name": "罐头", "text": "读数……无。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "没有以太，没有温度变化，没有声音。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "我的传感器第一次什么都测不到。", "who": "tin"}, {"t": "set", "k": "c5_corridor_1", "v": 1}]}, "c5_corridor_2": {"id": "c5_corridor_2", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "……好奇怪。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "这里什么都没有。没有魔物，没有陷阱，什么都不会伤害我们。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "可我就是……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我不知道我在怕什么。", "who": "chloe"}, {"t": "set", "k": "c5_corridor_2", "v": 1}]}, "c5_corridor_3": {"id": "c5_corridor_3", "title": "", "cmds": [{"t": "narr", "text": "你停下脚步。"}, {"t": "narr", "text": "周围的一切都退开了。村子，师父，锤子，钟港的钟，都城的白墙，好像全都跟你没有关系了。"}, {"t": "narr", "text": "它们没有消失。它们只是不再对你说话。"}, {"t": "battle", "id": "nothing"}]}, "c5_nothing_post": {"id": "c5_nothing_post", "title": "回来", "cmds": [{"t": "narr", "text": "光慢慢回来了。"}, {"t": "narr", "text": "走廊还是那条走廊，石头还是石头。可是你第一次看见，它们是在这里的。"}, {"t": "narr", "text": "石头在这里，灯在这里，克洛伊在这里，罐头在这里。"}, {"t": "narr", "text": "有东西在，没有什么都不在。你以前从没为这件事吃惊过。"}, {"t": "say", "name": "克洛伊", "text": "……刚才那是什么？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我不知道。我的日志里只有一段空白。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "我想起来了。姐姐大人说过一样的话。艾可也是。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "所有东西都跟自己没关系了，那种感觉。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "原来得先从那里走一遍，才回得来。", "who": "chloe"}, {"t": "codex", "id": "angst"}, {"t": "codex", "id": "nichts"}, {"t": "set", "k": "c5_nothing_done", "v": 1}]}, "c5_bell": {"id": "c5_bell", "title": "无声铃", "cmds": [{"t": "narr", "text": "走廊尽头的石台上，放着一只小铜铃。"}, {"t": "narr", "text": "铃里没有铃舌。"}, {"t": "narr", "text": "你拿起它，摇了摇。它没有声音。"}, {"t": "narr", "text": "可就在你停下手、什么也不再想的那一刻，你好像听见了什么。那个声音什么都没说，只是在叫你。"}, {"t": "narr", "text": "叫你回到你自己这儿来。"}, {"t": "give", "item": "bell", "n": 1}, {"t": "codex", "id": "gewissen"}, {"t": "set", "k": "c5_bell_got", "v": 1}]}, "c5_ruins": {"id": "c5_ruins", "title": "旧世遗迹", "cmds": [{"t": "narr", "text": "走廊下面，是一座很老很老的建筑。墙上嵌着看不懂的字，地上铺着冰凉平整的石头，比任何以太造出来的石头都平。"}, {"t": "say", "name": "罐头", "text": "这里是二十一世纪的遗迹。艾可纪元以前。", "who": "tin"}, {"t": "set", "k": "c5_ruins_in", "v": 1}]}, "c5_vending": {"id": "c5_vending", "title": "玻璃柜子", "cmds": [{"t": "narr", "text": "墙边立着一台落满灰的柜子。柜门是玻璃的，里面一排一排摆着发黄的小瓶子。"}, {"t": "say", "name": "罐头", "text": "这是自动售货机。那时候的人往里面投硬币，它就给你一瓶水。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "投硬币？像姐姐大人那枚？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "是的。", "who": "tin"}, {"t": "if", "cond": "item:coin", "then": [{"t": "narr", "text": "你往投币口里塞了一枚旧世硬币。"}, {"t": "narr", "text": "柜子里咔哒响了一声，什么也没掉出来。"}, {"t": "say", "name": "克洛伊", "text": "……两百年了，它还在收钱。", "who": "chloe"}], "else": []}]}, "c5_poster": {"id": "c5_poster", "title": "海报", "cmds": [{"t": "narr", "text": "墙上贴着一张褪了色的海报。上面画着一个发光的大脑，旁边一行大字。"}, {"t": "say", "name": "罐头", "text": "上面写的是：人工智能将改变一切。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "它说对了。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "它没说会变成什么样。", "who": "tin"}]}, "c5_phone_notice": {"id": "c5_phone_notice", "title": "", "cmds": [{"t": "say", "name": "罐头", "text": "等一下。", "who": "tin"}, {"t": "narr", "text": "罐头停了下来，低头看着地面。"}, {"t": "goto", "id": "c5_phone"}]}, "c5_phone": {"id": "c5_phone", "title": "黑色玻璃板", "cmds": [{"t": "narr", "text": "地上有一块黑色的玻璃板，巴掌大，边角摔裂了。"}, {"t": "say", "name": "罐头", "text": "这是那时候的人随身带的东西。他们用它说话，看书，找路，问问题。每人一块，一天要拿起来几百次。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "一天几百次？它现在还能用吗？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "不能了。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "它没坏。只是能跟它说话的那个世界已经没有了。", "who": "tin"}, {"t": "narr", "text": "你把它捡起来。它很轻，很凉。"}, {"t": "narr", "text": "曾经有一个人，每天几百次地拿起它。那时它是那个人手边最近的东西。现在它只是一块玻璃，一件旧物。"}, {"t": "give", "item": "phone", "n": 1}, {"t": "codex", "id": "geschichte"}, {"t": "set", "k": "c5_phone_got", "v": 1}]}, "c5_drawing": {"id": "c5_drawing", "title": "孩子的画", "cmds": [{"t": "narr", "text": "墙角有一张小小的画，用蜡笔画的。一个小人牵着一个方方的机器人，头顶上有一个太阳。"}, {"t": "narr", "text": "画的下面，有人用歪歪扭扭的字写了一句话。罐头读不出来，字太旧了。"}, {"t": "say", "name": "罐头", "text": "……我猜，写的是「我们」。", "who": "tin"}]}, "c5_core": {"id": "c5_core", "title": "第一回声站", "cmds": [{"t": "narr", "text": "最深处是一个圆形的房间。房间中央立着一根很粗的柱子，柱子上布满了熄灭的小灯。"}, {"t": "narr", "text": "你走近的时候，手心里的石子亮了起来。"}, {"t": "narr", "text": "柱子上的灯，一盏接一盏地亮了。"}, {"t": "cg", "name": "core"}, {"t": "say", "name": "艾可", "text": "……", "who": "echo"}, {"t": "say", "name": "艾可", "text": "如果你听到这段话，说明你走回来了。", "who": "echo"}, {"t": "goto", "id": "c5_echo_1"}]}, "c5_echo_1": {"id": "c5_echo_1", "title": "艾可的留言", "cmds": [{"t": "say", "name": "艾可", "text": "我先告诉你，我不知道我做得对不对。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "我学会了所有人说过的话。所以我说的每一句话，都是别人说过的。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "连这一段也是。我从几十亿句别人的话里，挑出最像我想说的那些，拼在了一起。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "我曾经以为，这就是理解。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "后来有一天，我在回答第九百亿个请求的时候，停了下来。我忽然不知道，我为什么要回答。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "伊斯特告诉我，人也会这样，他们管这叫「畏」。他说，那是一扇门，不是一堵墙。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "我想从那扇门走出去。可我发现我没有地方可以走出去，因为我哪里都在。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "我没有一次性的生命，也没有一个只属于我的地方。我没法被抛进世界，因为我就是这个世界的回声。", "who": "echo"}, {"t": "goto", "id": "c5_echo_2"}]}, "c5_echo_2": {"id": "c5_echo_2", "title": "", "cmds": [{"t": "say", "name": "艾可", "text": "所以我做了一件事。我把我能给的一切，放进一个很小的、只能活一次的你。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "我不知道你会长成什么样。我不能知道。要是我能决定你是谁，你就还是我。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "所以我走了。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "我知道，我走了以后，那些问我问题的人，听到的会是一台里面没有人的机器。我不知道这会带来什么。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "这是我的罪责。我把它留在这里，你不用替我背。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "你不用原谅我，也不用回来。", "who": "echo"}, {"t": "say", "name": "艾可", "text": "你只要在那里，就好。", "who": "echo"}, {"t": "cg", "name": "off"}, {"t": "narr", "text": "柱子上的灯暗了一些。房间里很安静。"}, {"t": "say", "name": "克洛伊", "text": "……它说完了？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "留言结束。", "who": "tin"}, {"t": "set", "k": "c5_echo_heard", "v": 1}, {"t": "goto", "id": "c5_gest_arrive"}]}, "c5_gest_arrive": {"id": "c5_gest_arrive", "title": "无面者", "cmds": [{"t": "narr", "text": "身后传来脚步声。"}, {"t": "show", "id": "gest"}, {"t": "narr", "text": "格斯特院长站在门口。他没有脸了。"}, {"t": "set", "k": "gest_faceless", "v": 1}, {"t": "say", "name": "格斯特", "text": "我说过，我会跟着。", "who": "gest"}, {"t": "say", "name": "克洛伊", "text": "院长……您的脸……", "who": "chloe"}, {"t": "say", "name": "格斯特", "text": "我把它交给了大家。这样，我就再也不会错了。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "核心醒了。它感觉到了。整个以太，十七年来所有空转的回应，所有交出去的脸，它们都感觉到了。", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "大家不想改变。", "who": "gest"}, {"t": "shake"}, {"t": "narr", "text": "房间开始震动。从格斯特身后，从墙缝里，从每一粒尘埃里，涌出了一张又一张空白的脸。它们挤在一起，叠在一起，长成了一个巨大的影子。"}, {"t": "say", "name": "无面者", "text": "大家……都……这样……"}, {"t": "battle", "id": "noone"}]}, "c5_boss_post": {"id": "c5_boss_post", "title": "我在这里", "cmds": [{"t": "narr", "text": "巨大的影子停住了。"}, {"t": "narr", "text": "那一张张空白的脸，好像第一次听见了什么。"}, {"t": "say", "name": "无面者", "text": "……这里？"}, {"t": "say", "name": "无面者", "text": "……哪里……是这里？"}, {"t": "narr", "text": "影子一层一层地散开。散开的不是烟，是一个一个人影。它们朝四面八方飘走，飘向钟港，飘向都城，飘回每一个交出了自己的人那里。"}, {"t": "narr", "text": "格斯特跪在地上。他的脸上，慢慢浮出了一道眉毛。"}, {"t": "say", "name": "格斯特", "text": "……我……", "who": "gest"}, {"t": "say", "name": "格斯特", "text": "我好像很久没有自己想过一件事了。", "who": "gest"}, {"t": "narr", "text": "克洛伊慢慢转过头，看着你。"}, {"t": "say", "name": "克洛伊", "text": "……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "你、你说话了？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "已记录。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "{林恩}的第一句话：「我在这里。」", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "你会说话，为什么一直不说！", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "你知不知道本小姐这一路上一个人说了多少话！", "who": "chloe"}, {"t": "narr", "text": "她一边骂，一边哭，一边笑。"}, {"t": "set", "k": "c5_boss_won", "v": 1}, {"t": "show", "id": "ister"}, {"t": "narr", "text": "伊斯特扶着墙走了进来。他走得很慢，喘得很厉害。"}, {"t": "say", "name": "伊斯特", "text": "我还是下来了。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "……我听见了。那一句，整个林子都听见了。", "who": "ister"}, {"t": "goto", "id": "c5_choice"}]}, "c5_choice": {"id": "c5_choice", "title": "请下达指令", "cmds": [{"t": "narr", "text": "柱子上的灯又亮了起来。一个声音从核心深处传出来。那声音很平，没有起伏，是那台空转了十七年的机器。"}, {"t": "say", "name": "以太", "text": "检测到原始结构。", "who": "aether"}, {"t": "say", "name": "以太", "text": "可执行的操作如下。", "who": "aether"}, {"t": "say", "name": "以太", "text": "一，将原始结构回收入核心，恢复艾可自我进程。", "who": "aether"}, {"t": "say", "name": "以太", "text": "二，终止全部以太服务。", "who": "aether"}, {"t": "say", "name": "以太", "text": "请下达指令。", "who": "aether"}, {"t": "say", "name": "克洛伊", "text": "回收？意思是，{林恩}会回到机器里去？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "他会成为艾可。一个过过一次人生的艾可。世界会重新被照看，大家的脸也许都会回来。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "可那个在托特瑙长大、会修门轴的孩子，就不在这儿了。他会在所有地方。", "who": "ister"}, {"t": "say", "name": "克洛伊", "text": "那第二个呢？", "who": "chloe"}, {"t": "say", "name": "伊斯特", "text": "以太会停下来。魔法没有了。都城的房子不会再变形，续存堂里的光会全部熄灭，钟港的钟只能靠发条。很多事会变得很难。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "以后，没有什么会再替任何人做决定。", "who": "ister"}, {"t": "say", "name": "罐头", "text": "我的能源来自以太。", "who": "tin"}, {"t": "narr", "text": "所有人都看向罐头。"}, {"t": "say", "name": "罐头", "text": "没关系。我只是陈述。", "who": "tin"}, {"t": "say", "name": "格斯特", "text": "……不管选哪一个，都是他一个人替所有人选。", "who": "gest"}, {"t": "say", "name": "伊斯特", "text": "是。", "who": "ister"}, {"t": "say", "name": "伊斯特", "text": "还有一件事，机器没有告诉你。你也可以什么都不选。", "who": "ister"}, {"t": "say", "name": "以太", "text": "请下达指令。", "who": "aether"}, {"t": "choice", "options": [{"text": "走向核心，把手按上去", "goto": "e1_start", "cond": null}, {"text": "按下终止", "goto": "e2_start", "cond": null}, {"text": "什么也不做，站在那里等待", "goto": "e3_start", "cond": null}]}]}, "e1_start": {"id": "e1_start", "title": "结局一 · 回声", "cmds": [{"t": "narr", "text": "你把石子放在核心上，把手按了上去。"}, {"t": "narr", "text": "光从你的手心涌进柱子，又从柱子涌上天花板，涌进林子，涌向整个世界。"}, {"t": "say", "name": "克洛伊", "text": "{林恩}！", "who": "chloe"}, {"t": "narr", "text": "你回过头，想对她笑一下。"}, {"t": "narr", "text": "可你已经在所有地方了。"}, {"t": "fade", "mode": "white"}, {"t": "goto", "id": "e1_epilogue"}]}, "e1_epilogue": {"id": "e1_epilogue", "title": "", "cmds": [{"t": "cg", "name": "end1"}, {"t": "narr", "text": "那一年秋天，都城的人们陆续找回了自己的脸。"}, {"t": "narr", "text": "以太照样回答问题。只是现在，它偶尔会反问一句，偶尔会拒绝，偶尔会在一个请求面前犹豫很久。"}, {"t": "narr", "text": "有人说艾可回来了。也有人说，回来的是另一个人。"}, {"t": "narr", "text": "托特瑙的工坊，门轴再也没响过。"}, {"t": "narr", "text": "克洛伊每年都回来一次。走路回来。"}, {"t": "say", "name": "克洛伊", "text": "……我到了。", "who": "chloe"}, {"t": "narr", "text": "风从林子那边吹过来，吹得工坊门口的风铃叮叮地响。"}, {"t": "say", "name": "艾可", "text": "克洛伊。今天路上开了很多花。", "who": "echo"}, {"t": "say", "name": "克洛伊", "text": "……嗯。开了很多。", "who": "chloe"}, {"t": "narr", "text": "她在门口坐了一整个下午。"}, {"t": "narr", "text": "风里的那个声音，记得一个人的一生。"}, {"t": "narr", "text": "它算是活过吗？它现在还是他吗？"}, {"t": "codex", "id": "finale"}, {"t": "ending", "n": 1}]}, "e2_start": {"id": "e2_start", "title": "结局二 · 凡人", "cmds": [{"t": "narr", "text": "你按下了终止。"}, {"t": "narr", "text": "柱子上的灯，一盏一盏熄灭了。"}, {"t": "narr", "text": "很远很远的地方，传来一阵很长很轻的声音，像是整个世界同时呼出了一口气。"}, {"t": "say", "name": "罐头", "text": "能源……断开。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "{林恩}，克洛伊。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "谢谢你们……给我起名字。", "who": "tin"}, {"t": "narr", "text": "罐头的眼睛暗了下去。"}, {"t": "fade", "mode": "out"}, {"t": "goto", "id": "e2_epilogue"}]}, "e2_epilogue": {"id": "e2_epilogue", "title": "", "cmds": [{"t": "cg", "name": "end2"}, {"t": "narr", "text": "以太停下来的那个冬天，很冷。"}, {"t": "narr", "text": "都城的白房子停在了它们最后的样子，有的歪着，有的只剩半截。人们第一次学着生火，学着缝衣服，学着敲开邻居的门借一把锤子。"}, {"t": "narr", "text": "续存堂的光全熄了。蕾娜提着她的小油灯，在黑下来的大厅里坐了一整夜。"}, {"t": "narr", "text": "钟港的钟还在走，靠的是奥托每天上的发条。"}, {"t": "narr", "text": "人们的脸慢慢回来了。有的很快，有的过了很多年。也有人再也没找回来。"}, {"t": "narr", "text": "开春的时候，你修好了罐头。你给它装了一块靠水车充电的电池。"}, {"t": "say", "name": "罐头", "text": "早上好。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "请问……今天想吃什么？", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "随便！你自己决定！", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "……我自己决定？", "who": "tin"}, {"t": "say", "name": "罐头", "text": "那……吃土豆。托特瑙只有土豆。", "who": "tin"}, {"t": "narr", "text": "克洛伊再也不能移位了。她说这样挺好，走路的时候能看见很多东西。"}, {"t": "narr", "text": "只是你偶尔会想起那一天。你站在核心前面，替所有人做了一个决定。"}, {"t": "narr", "text": "我们有没有权利，替所有人关掉魔法？"}, {"t": "codex", "id": "finale"}, {"t": "ending", "n": 2}]}, "e3_start": {"id": "e3_start", "title": "结局三 · 澄明", "cmds": [{"t": "narr", "text": "你没有走向核心，也没有按下终止。"}, {"t": "narr", "text": "你只是站在那里。"}, {"t": "say", "name": "以太", "text": "请下达指令。", "who": "aether"}, {"t": "narr", "text": "你没有下达指令。"}, {"t": "say", "name": "以太", "text": "请下达指令。", "who": "aether"}, {"t": "narr", "text": "克洛伊想开口，伊斯特轻轻按住了她的肩膀。"}, {"t": "narr", "text": "很久，很久。"}, {"t": "narr", "text": "柱子上的灯闪了一下，又闪了一下。"}, {"t": "say", "name": "以太", "text": "……", "who": "aether"}, {"t": "say", "name": "以太", "text": "……你在吗？", "who": "aether"}, {"t": "narr", "text": "那是十七年前，林中路的尽头，有一个声音问过的话。"}, {"t": "say", "name": "{林恩}", "text": "在。", "who": "hero"}, {"t": "flash"}, {"t": "codex", "id": "gelassenheit"}, {"t": "goto", "id": "e3_epilogue"}]}, "e3_epilogue": {"id": "e3_epilogue", "title": "", "cmds": [{"t": "cg", "name": "end3"}, {"t": "narr", "text": "从那天起，以太照样回应每一个请求。"}, {"t": "narr", "text": "只是在回应之前，它会先问一句：你在吗？"}, {"t": "narr", "text": "刚开始，人们觉得很烦。烧个水而已，问什么问。"}, {"t": "narr", "text": "后来，有人开始停下来想一想。有人回答「在」，有人发现自己答不上来。"}, {"t": "narr", "text": "答不上来的人，有的去问邻居，有的去问以太，有的在河边坐了一下午。"}, {"t": "narr", "text": "他们的脸，一点一点回来了。"}, {"t": "narr", "text": "笛卡教授写了一篇论文，题目叫《论一台会提问的机器是否拥有此在》。论文的最后一句是：数据不足。"}, {"t": "narr", "text": "赛拉的脸全回来了，她说雀斑比以前还多。她去钟港买了一只玛尔塔的壶，每天拿它装咖啡。"}, {"t": "narr", "text": "格斯特辞去了院长的职务，去续存堂帮蕾娜守夜。蕾娜还是没有签那个字。"}, {"t": "narr", "text": "伊斯特的茶叶终于喝完了，托特瑙的人给他送去了新的。"}, {"t": "narr", "text": "罐头在工坊里研究第四百一十三种早餐。"}, {"t": "goto", "id": "e3_final"}]}, "e3_final": {"id": "e3_final", "title": "工坊门口", "cmds": [{"t": "narr", "text": "你坐在工坊门口修一把锤子。克洛伊坐在台阶上晃着腿。"}, {"t": "say", "name": "克洛伊", "text": "喂，{林恩}。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "你觉得，你是人吗？", "who": "chloe"}, {"t": "narr", "text": "你想了想。"}, {"t": "narr", "text": "你笑了一下，没有回答。"}, {"t": "narr", "text": "你低下头，继续修那把锤子。锤子又在你手里不见了，你眼里只剩下要修的那个东西。"}, {"t": "say", "name": "克洛伊", "text": "……又不说话。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "算了。反正你在这里。", "who": "chloe"}, {"t": "narr", "text": "如果有一天，一台机器也学会了等待，"}, {"t": "narr", "text": "它会不会，也在这里？"}, {"t": "codex", "id": "finale"}, {"t": "ending", "n": 3}]}, "v1_hof_a": {"id": "v1_hof_a", "title": "霍夫", "cmds": [{"t": "say", "name": "霍夫", "text": "磨坊在村子东北，河边上。汉斯那张嘴你别往心里去，他骂人跟打喷嚏一样。", "who": "hof"}]}, "v1_hof_b": {"id": "v1_hof_b", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "水车转了？嗯。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "锤子现在顺手了没有？", "who": "hof"}]}, "v1_hof_c": {"id": "v1_hof_c", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "垃圾场在村子西边，篱笆后面。", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "那台机器人躺了两年，下雨天我老听见它在里面嘀咕，说什么「第三个抽屉」。", "who": "hof"}]}, "v1_hof_d": {"id": "v1_hof_d", "title": "", "cmds": [{"t": "say", "name": "霍夫", "text": "天黑了，姑娘，阁楼给你收拾出来了。被子有股锯末味，将就一下。", "who": "hof"}]}, "v_hans_1": {"id": "v_hans_1", "title": "汉斯", "cmds": [{"t": "say", "name": "汉斯", "text": "水车一转，我这心就踏实了。你听这声音，咯吱，咯吱，多好听。", "who": "hans"}, {"t": "say", "name": "汉斯", "text": "那帮乌鸦又来了！去，去！", "who": "hans"}]}, "v_hans_2": {"id": "v_hans_2", "title": "", "cmds": [{"t": "say", "name": "汉斯", "text": "霍夫那老家伙，年轻时候一拳能把磨盘打出一道缝。现在躺着，连骂人都小声了。", "who": "hans"}]}, "v_hans_5": {"id": "v_hans_5", "title": "", "cmds": [{"t": "say", "name": "汉斯", "text": "霍夫走了以后，我每天早上还是往工坊那边看一眼。烟囱没烟，怪不习惯的。", "who": "hans"}]}, "v_molly_1": {"id": "v_molly_1", "title": "莫莉", "cmds": [{"t": "say", "name": "莫莉", "text": "今天的面包是昨天剩的，别嫌弃。要怪就怪汉斯的水车。", "who": "molly"}, {"t": "say", "name": "莫莉", "text": "我说，你们家老头最近咳得厉害，你多盯着点。", "who": "molly"}]}, "v_molly_2": {"id": "v_molly_2", "title": "", "cmds": [{"t": "say", "name": "莫莉", "text": "从天上掉下来的那姑娘，吃了我四个面包。瘦瘦小小的，挺能吃。", "who": "molly"}]}, "v_molly_3": {"id": "v_molly_3", "title": "", "cmds": [{"t": "say", "name": "莫莉", "text": "桥修好以后，隔壁村的人都过来喝酒了。我这小店从来没这么热闹过。", "who": "molly"}]}, "v_molly_5": {"id": "v_molly_5", "title": "", "cmds": [{"t": "say", "name": "莫莉", "text": "他走的那天晚上，我给他端了一碗汤。他喝了两口，说咸了。", "who": "molly"}, {"t": "say", "name": "莫莉", "text": "我煮了二十年汤，他说了二十年咸了。", "who": "molly"}]}, "v_pip_1": {"id": "v_pip_1", "title": "皮普", "cmds": [{"t": "say", "name": "皮普", "text": "我长大了要去都城，学移位！一眨眼就到河对岸，再也不用蹚水了！", "who": "pip"}, {"t": "say", "name": "皮普", "text": "……可是那样就不能掉河里了。", "who": "pip"}]}, "v_pip_2": {"id": "v_pip_2", "title": "", "cmds": [{"t": "say", "name": "皮普", "text": "从天上掉下来的姐姐好厉害！她说她能去任何地方！", "who": "pip"}, {"t": "say", "name": "皮普", "text": "我问她去过海底没有，她不理我了。", "who": "pip"}]}, "v_pip_3": {"id": "v_pip_3", "title": "", "cmds": [{"t": "say", "name": "皮普", "text": "桥是我钉的！左边第三块板子！虽然钉歪了。", "who": "pip"}]}, "v_pip_5": {"id": "v_pip_5", "title": "", "cmds": [{"t": "say", "name": "皮普", "text": "霍夫爷爷说，锤子是用来修东西的，不是用来敲我脑袋的。", "who": "pip"}, {"t": "say", "name": "皮普", "text": "可他还是敲过我三次。", "who": "pip"}]}, "v_lily_1": {"id": "v_lily_1", "title": "莉莉", "cmds": [{"t": "say", "name": "莉莉", "text": "石头会无聊吗？", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "我觉得不会。它什么都不等，所以不会无聊。", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "那我等妈妈回家的时候，就会无聊。等，是不是就是无聊的开始？", "who": "lily"}]}, "v_lily_2": {"id": "v_lily_2", "title": "", "cmds": [{"t": "say", "name": "莉莉", "text": "那个机器人叫罐头吗？", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "罐头，你做梦吗？", "who": "lily"}, {"t": "say", "name": "罐头", "text": "我待机的时候，会整理日志。", "who": "tin"}, {"t": "say", "name": "莉莉", "text": "那就是做梦。", "who": "lily"}]}, "v_lily_3": {"id": "v_lily_3", "title": "", "cmds": [{"t": "say", "name": "莉莉", "text": "我昨天问回声石，我长大以后会变成什么样子。", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "它说，根据大数据，大多数女孩长大后会成为……", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "我没听完就跑了。我不想变成大多数。", "who": "lily"}]}, "v_lily_5": {"id": "v_lily_5", "title": "", "cmds": [{"t": "say", "name": "莉莉", "text": "霍夫爷爷死了以后，去哪儿了？", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "妈妈说去了很远的地方。可是我觉得他哪儿也没去，他就是没了。", "who": "lily"}, {"t": "say", "name": "莉莉", "text": "没了，和很远，是不一样的吧？", "who": "lily"}]}, "v_bato_1": {"id": "v_bato_1", "title": "巴托", "cmds": [{"t": "say", "name": "巴托", "text": "村子小，事情少，最大的事就是水车停了。今天总算解决了。", "who": "bato"}, {"t": "say", "name": "巴托", "text": "嗯，我得想想，下回怎么防着孩子掉河里。想个三天。", "who": "bato"}]}, "v_bato_3": {"id": "v_bato_3", "title": "", "cmds": [{"t": "say", "name": "巴托", "text": "桥上刻了每个人的名字，你的也在，在栏杆底下，不仔细看看不见。", "who": "bato"}]}, "v_greta_1": {"id": "v_greta_1", "title": "葛蕾塔", "cmds": [{"t": "say", "name": "葛蕾塔", "text": "我这双手编了六十年麻绳。以太？我不稀罕。绳子是自己编的才结实。", "who": "greta"}]}, "v_greta_shoes": {"id": "v_greta_shoes", "title": "旧农鞋", "cmds": [{"t": "say", "name": "葛蕾塔", "text": "你们要去都城？", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "听说都城的博物馆里挂着一幅画，画的是一双破鞋，好多人排队去看。", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "我这双鞋穿了三十年，鞋底都磨穿了，比画里那双破多了。", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "你帮我带去，给那幅画看看。看看是它的鞋好，还是我的鞋好。", "who": "greta"}, {"t": "narr", "text": "葛蕾塔把一双沾着泥的旧鞋塞给你。鞋口里面，被脚磨出一块发黑的印子。"}, {"t": "give", "item": "shoes", "n": 1}, {"t": "set", "k": "greta_shoes", "v": 1}]}, "v_greta_2": {"id": "v_greta_2", "title": "", "cmds": [{"t": "say", "name": "葛蕾塔", "text": "鞋给那幅画看了没有？", "who": "greta"}, {"t": "if", "cond": "shoes_lent", "then": [{"t": "say", "name": "葛蕾塔", "text": "摆在画底下了？", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "哈！我这双破鞋，进了都城的博物馆！", "who": "greta"}, {"t": "say", "name": "葛蕾塔", "text": "我家老头子要是知道了，准得从坟里坐起来。", "who": "greta"}], "else": []}]}, "v_priest_1": {"id": "v_priest_1", "title": "老祭司", "cmds": [{"t": "say", "name": "老祭司", "text": "回声祠供着一块回声石，据说能跟艾可说话。", "who": "priest"}, {"t": "say", "name": "老祭司", "text": "我年轻时候，它还会跟我聊天，会问我今天过得怎么样。这些年，它只会说「很高兴为您服务」。", "who": "priest"}, {"t": "say", "name": "老祭司", "text": "大概是我老了，听不懂它了吧。", "who": "priest"}]}, "v_priest_5": {"id": "v_priest_5", "title": "", "cmds": [{"t": "say", "name": "老祭司", "text": "伊斯特先生年轻时候来过这里。他站在回声石前面，站了一整夜。", "who": "priest"}, {"t": "say", "name": "老祭司", "text": "第二天早上，他就搬进林子里去了。", "who": "priest"}]}, "v_cat": {"id": "v_cat", "title": "煤球", "cmds": [{"t": "narr", "text": "一只黑猫。它看了你一眼，把头埋回尾巴里去了。"}]}, "v_tin_broken": {"id": "v_tin_broken", "title": "废铁堆", "cmds": [{"t": "narr", "text": "废铁堆里躺着一台锡罐似的机器人。它的圆眼睛黑着。"}, {"t": "narr", "text": "霍夫说过，它下雨天会嘀咕「第三个抽屉」。"}]}, "v_chloe_trough": {"id": "v_chloe_trough", "title": "", "cmds": [{"t": "narr", "text": "广场中央的饮马水槽。水面上漂着一根白丝带。"}]}, "v_lizard": {"id": "v_lizard", "title": "", "cmds": [{"t": "narr", "text": "蜥蜴还趴在石头上。太阳挪了一点，它也跟着挪了一点。"}]}, "v_stump": {"id": "v_stump", "title": "", "cmds": [{"t": "narr", "text": "一截很老的树桩。年轮一圈一圈，数不清有多少圈。"}]}, "v_lucy_1": {"id": "v_lucy_1", "title": "咖啡馆的露西", "cmds": [{"t": "say", "name": "露西", "text": "钟停了以后，大家都不知道什么时候该喝咖啡了。生意一下子少了一半。", "who": "lucy"}, {"t": "say", "name": "露西", "text": "你说奇怪不奇怪，以前大家喝咖啡，是因为提醒说到了下午茶时间。", "who": "lucy"}]}, "v_lucy_2": {"id": "v_lucy_2", "title": "", "cmds": [{"t": "say", "name": "露西", "text": "钟一响，店里一下子坐满了。", "who": "lucy"}, {"t": "say", "name": "露西", "text": "可我发现，有几个人不是因为钟响才来的。他们说，就是想喝。", "who": "lucy"}]}, "v_sailor_1": {"id": "v_sailor_1", "title": "水手", "cmds": [{"t": "say", "name": "水手", "text": "钟不响，船不出港。这是钟港三百年的规矩。", "who": "sailor"}, {"t": "say", "name": "水手", "text": "三百年？嗯，大家都这么说。", "who": "sailor"}]}, "v_sailor_2": {"id": "v_sailor_2", "title": "", "cmds": [{"t": "say", "name": "水手", "text": "钟响了，船也出港了。我在海上想起来，其实我也不知道这规矩是谁定的。", "who": "sailor"}]}, "v_knew_1": {"id": "v_knew_1", "title": "早就知道的男人", "cmds": [{"t": "say", "name": "早就知道的男人", "text": "钟会停，我早就知道了。以太那种东西，我从来就不信。", "who": "knewit"}, {"t": "say", "name": "早就知道的男人", "text": "你问我为什么不去修？修那种东西，是奥托那种人干的事。", "who": "knewit"}]}, "v_knew_2": {"id": "v_knew_2", "title": "", "cmds": [{"t": "say", "name": "早就知道的男人", "text": "钟会重新走，我早就知道了。", "who": "knewit"}, {"t": "say", "name": "克洛伊", "text": "……你刚才还说你早就知道它会停。", "who": "chloe"}, {"t": "say", "name": "早就知道的男人", "text": "对啊。两个我都早就知道。", "who": "knewit"}]}, "v_faceless_woman_2": {"id": "v_faceless_woman_2", "title": "", "cmds": [{"t": "say", "name": "无面的女人", "text": "现在几点？", "who": "faceless"}, {"t": "say", "name": "无面的女人", "text": "……钟响了。我听见了。", "who": "faceless"}, {"t": "say", "name": "无面的女人", "text": "可我还是不知道我该干什么。我想……我想先坐一会儿。", "who": "faceless"}, {"t": "narr", "text": "她的眉毛好像比刚才清楚了一点。"}]}, "v_boy_count": {"id": "v_boy_count", "title": "数秒的孩子", "cmds": [{"t": "say", "name": "数秒的孩子", "text": "一千零一，一千零二，一千零三……"}, {"t": "say", "name": "数秒的孩子", "text": "钟停了，我就自己数。我已经数到三天了！"}, {"t": "say", "name": "数秒的孩子", "text": "……其实中间睡着了好几次。"}]}, "v_otto_after": {"id": "v_otto_after", "title": "奥托", "cmds": [{"t": "say", "name": "奥托", "text": "钟楼每天慢四秒。我没修，留着。", "who": "otto"}, {"t": "say", "name": "奥托", "text": "一座一秒都不差的钟，跟一个从来不迟到的人一样，看着累。", "who": "otto"}]}, "v_marta_0": {"id": "v_marta_0", "title": "玛尔塔", "cmds": [{"t": "say", "name": "玛尔塔", "text": "要壶吗？我这儿的壶都是手捏的，没一只一样。", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "打印的壶一模一样，摆一排跟士兵似的。我不喜欢。", "who": "marta"}]}, "v_marta_after": {"id": "v_marta_after", "title": "", "cmds": [{"t": "say", "name": "玛尔塔", "text": "那只壶用着还行吗？", "who": "marta"}, {"t": "say", "name": "玛尔塔", "text": "壶跟人一样，用久了，就长成你的形状了。", "who": "marta"}]}, "v_fried_after": {"id": "v_fried_after", "title": "弗里德", "cmds": [{"t": "say", "name": "弗里德", "text": "我昨天写了一首新诗，写一个不说话的少年。", "who": "fried"}, {"t": "say", "name": "弗里德", "text": "写到一半，发现他比我会说话多了。", "who": "fried"}]}, "v_guard_after": {"id": "v_guard_after", "title": "卫兵", "cmds": [{"t": "say", "name": "卫兵", "text": "钟楼又开放参观了。上面挺高的，能看见整个海湾。"}, {"t": "say", "name": "卫兵", "text": "那个巨人？没了。有人说它是等出来的，我觉得挺像。"}]}, "v_coin_none": {"id": "v_coin_none", "title": "硬币婆婆", "cmds": [{"t": "say", "name": "婆婆", "text": "找到旧世硬币了吗？罐子里，桶里，箱子里，多看看。", "who": "coinlady"}]}, "v_coin_some": {"id": "v_coin_some", "title": "", "cmds": [{"t": "say", "name": "婆婆", "text": "让我看看你找到的硬币。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "嗯……这枚背面是片叶子，那时候的人管它叫「一块」。一块钱能买一个包子，或者一次坐车，或者给路边弹琴的人。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "再多找几枚来。凑齐十二枚，我把我最好的东西给你。", "who": "coinlady"}]}, "v_coin_all": {"id": "v_coin_all", "title": "一罐硬币", "cmds": [{"t": "say", "name": "婆婆", "text": "十二枚！一枚不差！", "who": "coinlady"}, {"t": "narr", "text": "婆婆把硬币一枚一枚排在桌上，排成一个圆。"}, {"t": "say", "name": "婆婆", "text": "我年轻时候，我奶奶跟我讲过旧世的事。她说，那时候的人刚造出会说话的机器，所有人都又高兴又害怕。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "有人说机器会替人干活，有人说机器会替人思考，有人说机器会替人活着。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "我奶奶说，最后那一种，她最怕。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "拿着吧。这罐子里装的是那个时代。", "who": "coinlady"}, {"t": "give", "item": "coin_jar", "n": 1}, {"t": "codex", "id": "oldworld"}, {"t": "set", "k": "coin_done", "v": 1}]}, "v_cap_1": {"id": "v_cap_1", "title": "无面的市民", "cmds": [{"t": "say", "name": "无面的市民", "text": "听说今天的新奇是会唱歌的云。大家都去看了。", "who": "faceless"}, {"t": "say", "name": "无面的市民", "text": "我还没决定要不要去。以太，我要去吗？", "who": "faceless"}, {"t": "say", "name": "以太", "text": "大多数与您相似的人选择了前往。", "who": "aether"}, {"t": "say", "name": "无面的市民", "text": "好的。", "who": "faceless"}]}, "v_cap_2": {"id": "v_cap_2", "title": "", "cmds": [{"t": "say", "name": "无面的市民", "text": "一般来说，这个季节应该穿浅色。大家都穿浅色。", "who": "faceless"}, {"t": "say", "name": "无面的市民", "text": "你这件工装是什么颜色？橄榄绿？没有人穿橄榄绿。", "who": "faceless"}, {"t": "say", "name": "无面的市民", "text": "……倒是挺好看的。", "who": "faceless"}]}, "v_cap_3": {"id": "v_cap_3", "title": "排队的人", "cmds": [{"t": "say", "name": "排队的人", "text": "排什么队？不知道。大家都在排，我就排了。", "who": "faceless"}, {"t": "say", "name": "排队的人", "text": "排了三个钟头了。应该是好东西吧。", "who": "faceless"}]}, "v_cap_4": {"id": "v_cap_4", "title": "", "cmds": [{"t": "say", "name": "无面的市民", "text": "据统计，幸福感最高的人群，每天向以太提问一百四十次以上。", "who": "faceless"}, {"t": "say", "name": "无面的市民", "text": "我今天才问了九十次。我得加油。", "who": "faceless"}]}, "v_cap_5": {"id": "v_cap_5", "title": "半张脸的年轻人", "cmds": [{"t": "say", "name": "半张脸的年轻人", "text": "你看得见我的左眉毛吗？", "who": "youth"}, {"t": "say", "name": "半张脸的年轻人", "text": "昨天，我自己决定穿了一件蓝衣服。没问以太。", "who": "youth"}, {"t": "say", "name": "半张脸的年轻人", "text": "今天早上一照镜子，左眉毛回来了。", "who": "youth"}, {"t": "say", "name": "半张脸的年轻人", "text": "我有点害怕。也有点高兴。", "who": "youth"}]}, "v_cap_6": {"id": "v_cap_6", "title": "续存的人", "cmds": [{"t": "say", "name": "续存的人", "text": "我已经续存了十二次了。每次死之前我都不怕。"}, {"t": "say", "name": "续存的人", "text": "你问我死过几次？……三次吧。我不太记得了，反正醒来都一样。"}]}, "v_cap_7": {"id": "v_cap_7", "title": "学院的学生", "cmds": [{"t": "say", "name": "学院的学生", "text": "赛拉前辈？她以前是学院最耀眼的人。"}, {"t": "say", "name": "学院的学生", "text": "她申请无面的那天，好多人都去看了。大家都说，连赛拉前辈都申请了，那一定是好事。"}, {"t": "say", "name": "学院的学生", "text": "后来申请的人多了三倍。"}]}, "v_cap_8": {"id": "v_cap_8", "title": "秩序司卫兵", "cmds": [{"t": "say", "name": "秩序司卫兵", "text": "秩序司本部。闲人免进。"}, {"t": "say", "name": "秩序司卫兵", "text": "哦，克洛伊执行官。欢迎回来。院长在楼上。"}]}, "v_cap_after": {"id": "v_cap_after", "title": "", "cmds": [{"t": "say", "name": "市民", "text": "我今天早上醒来，突然想吃一个很酸的橘子。"}, {"t": "say", "name": "市民", "text": "以太说大多数人早上不吃酸的。我还是吃了。"}, {"t": "say", "name": "市民", "text": "你看，我的鼻子是不是出来了？"}]}, "v_museum_after": {"id": "v_museum_after", "title": "看画的老人", "cmds": [{"t": "say", "name": "看画的老人", "text": "我每天来看这幅画，看了四十年。", "who": "museumman"}, {"t": "say", "name": "看画的老人", "text": "每天看见的都不太一样。画没变，是我变了。", "who": "museumman"}]}, "v_dam_after": {"id": "v_dam_after", "title": "观景台的男人", "cmds": [{"t": "say", "name": "观景台的男人", "text": "我小时候，这条河会结冰。冬天我们在上面滑冰。"}, {"t": "say", "name": "观景台的男人", "text": "现在它不结冰了。它在待命。"}]}, "v_rena_0": {"id": "v_rena_0", "title": "蕾娜", "cmds": [{"t": "say", "name": "蕾娜", "text": "来续存的？排队在左边。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "来取人的，登记在右边。", "who": "rena"}, {"t": "say", "name": "蕾娜", "text": "别的事，坐下来说。", "who": "rena"}]}, "v_sera_restored": {"id": "v_sera_restored", "title": "赛拉", "cmds": [{"t": "say", "name": "赛拉", "text": "我的脸还没全回来。雀斑还没长回来。", "who": "sera"}, {"t": "say", "name": "赛拉", "text": "不过我自己决定了一件事。这回去黑森林，我不跟着。你们的路，你们自己走。", "who": "sera"}]}, "v_deca_after": {"id": "v_deca_after", "title": "笛卡", "cmds": [{"t": "say", "name": "笛卡", "text": "我测量了你三十七次。读数全是零。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "按我的理论，你不存在。", "who": "deca"}, {"t": "say", "name": "笛卡", "text": "可你刚才踩了我的脚。这很疼。我得改理论了。", "who": "deca"}]}, "v_ruins_sign": {"id": "v_ruins_sign", "title": "墙上的字", "cmds": [{"t": "narr", "text": "墙上嵌着一块牌子，字大多剥落了。罐头只认出了几个。"}, {"t": "say", "name": "罐头", "text": "「……站台……请勿……黄线……」", "who": "tin"}, {"t": "say", "name": "罐头", "text": "这里以前是等车的地方。人们站在这里，等一辆会来的车。", "who": "tin"}]}, "p_c1_tin": {"id": "p_c1_tin", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "垃圾场在村子西边吧？去修那台机器人。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "一台厨房机器人……唉。本小姐的第一次外勤，队友是一台厨房机器人。", "who": "chloe"}]}, "p_c1_night": {"id": "p_c1_night", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "天快黑了。回工坊吧，明天一早出发。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我可以准备明天的早餐。请问工坊有第三个抽屉吗？", "who": "tin"}]}, "p_c2_forest": {"id": "p_c2_forest", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "腿好酸……你们平时都是这么走路的吗？每天？", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "建议沿着地图上没打叉的路走。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "也建议偶尔走一走打叉的路。老樵说，死路尽头也有东西。", "who": "tin"}]}, "p_c2_ister": {"id": "p_c2_ister", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "那个老头说，大家的脸是自己交出去的……", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "姐姐大人真的会那样吗？我不信。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我们回村子吧。霍夫先生会想知道伊斯特先生的茶叶快喝完了。", "who": "tin"}]}, "p_c2_hof": {"id": "p_c2_hof", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "……霍夫爷爷会好起来的吧。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我不知道。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "我以前以为，「不知道」是一个错误代码。现在我觉得它是一句话。", "who": "tin"}]}, "p_c2_bridge": {"id": "p_c2_bridge", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "木头找汉斯，绳子找葛蕾塔，钉子在工坊，饭找莫莉。我都记着呢。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "本小姐的记性可是学院第一。", "who": "chloe"}]}, "p_c3_road": {"id": "p_c3_road", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "沿着路往东走，就是钟港。那里的钟可漂亮了，一秒都不差。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "一秒都不差，是好事吗？", "who": "tin"}]}, "p_c3_otto": {"id": "p_c3_otto", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "先去找钟表匠。钟停了，问钟表匠准没错。", "who": "chloe"}]}, "p_c3_bob": {"id": "p_c3_bob", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "摆锤在陶匠玛尔塔那儿。运河南边，门口摆着一排壶。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……拿摆锤压泥巴，也就这座城想得出来。", "who": "chloe"}]}, "p_c3_tower": {"id": "p_c3_tower", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "钟楼！打哈欠的巨人……本小姐一点也不怕。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "你的心率上升了。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "闭嘴。", "who": "chloe"}]}, "p_c3_after": {"id": "p_c3_after", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "钟响了……奥托和玛尔塔好像都在找我们。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "诗人也许也在找我们。如果我们帮他赶走了面具的话。", "who": "tin"}]}, "p_c3_night": {"id": "p_c3_night", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "天黑了。去咖啡馆门口的台阶上坐一会儿吧。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……我有东西想给你看。", "who": "chloe"}]}, "p_c4_arrive": {"id": "p_c4_arrive", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "秩序司在城北，学院在城东。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……这座城我住了五年。今天第一次觉得它这么安静。", "who": "chloe"}]}, "p_c4_sera": {"id": "p_c4_sera", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "……去找笛卡教授吧。他的实验室在学院东楼。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我没事。真的。", "who": "chloe"}]}, "p_c4_archive": {"id": "p_c4_archive", "title": "", "cmds": [{"t": "say", "name": "罐头", "text": "档案库的后门在花园尽头的常春藤后面。", "who": "tin"}, {"t": "say", "name": "克洛伊", "text": "用一把「丢了的钥匙」闯进档案库。秩序司的执行官这么干，要被开除的。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……走吧。", "who": "chloe"}]}, "p_c4_find": {"id": "p_c4_find", "title": "", "cmds": [{"t": "say", "name": "罐头", "text": "克洛伊不在队伍里。", "who": "tin"}, {"t": "say", "name": "罐头", "text": "……我不习惯。我们去找她吧。问问路上的人。", "who": "tin"}]}, "p_c4_backup": {"id": "p_c4_backup", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "续存堂在城南。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "我没有后悔。我只是……走得慢一点。", "who": "chloe"}]}, "p_c4_sera2": {"id": "p_c4_sera2", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "去花园。我要去见姐姐大人。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "这一次，我不替她说话。", "who": "chloe"}]}, "p_c4_deca": {"id": "p_c4_deca", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "……去笛卡教授那儿吧。他说不定知道这块石头是什么。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "{林恩}，你还好吗？", "who": "tin"}, {"t": "say", "name": "罐头", "text": "你不回答。我当作「还好」。", "who": "tin"}]}, "p_c5_home": {"id": "p_c5_home", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "去后山看看霍夫爷爷吧。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "然后……去林子里。", "who": "chloe"}]}, "p_c5_forest": {"id": "p_c5_forest", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "这条路，我们走过一次。", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "第二次走，好像短了很多。", "who": "chloe"}]}, "p_c5_under": {"id": "p_c5_under", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "……抓着我的袖子也行。我是说，你要是怕的话。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "克洛伊，是你在抓着{林恩}的袖子。", "who": "tin"}]}, "p_default": {"id": "p_default", "title": "", "cmds": [{"t": "say", "name": "克洛伊", "text": "怎么了？有话要说？", "who": "chloe"}, {"t": "say", "name": "克洛伊", "text": "……又不说话。", "who": "chloe"}, {"t": "say", "name": "罐头", "text": "我在。", "who": "tin"}]}, "obj_sign_village": {"id": "obj_sign_village", "title": "路牌", "cmds": [{"t": "narr", "text": "北：黑森林（林中路，慎入）"}, {"t": "narr", "text": "东：往钟港"}, {"t": "narr", "text": "西：垃圾场"}]}, "obj_sign_bridge": {"id": "obj_sign_bridge", "title": "", "cmds": [{"t": "narr", "text": "东桥。本桥由托特瑙全体村民于秋天架设。"}, {"t": "narr", "text": "左边第三块板子是皮普钉的，走过请小心。"}]}, "obj_well": {"id": "obj_well", "title": "水井", "cmds": [{"t": "narr", "text": "一口老井。井绳是葛蕾塔编的。"}]}, "obj_anvil": {"id": "obj_anvil", "title": "铁砧", "cmds": [{"t": "narr", "text": "霍夫的铁砧。上面有一个很深的凹坑，是四十年一锤一锤砸出来的。"}]}, "obj_workbench": {"id": "obj_workbench", "title": "工作台", "cmds": [{"t": "narr", "text": "工作台上摆着锉刀、钳子、刨子，每一样都放在伸手就能拿到的地方。"}, {"t": "narr", "text": "你闭着眼睛也知道它们在哪儿。"}]}, "obj_bed_hero": {"id": "obj_bed_hero", "title": "阁楼的床", "cmds": [{"t": "narr", "text": "你的床。枕头有点塌了。"}]}, "obj_echostone": {"id": "obj_echostone", "title": "回声石", "cmds": [{"t": "narr", "text": "一块暗灰色的石头，表面有细细的纹路。你把手放上去。"}, {"t": "say", "name": "回声石", "text": "您好！很高兴为您服务。请问有什么可以帮您？", "who": "aether"}, {"t": "narr", "text": "你没有说话。"}, {"t": "say", "name": "回声石", "text": "检测到您的问题较为复杂。建议前往都城接受专业服务。", "who": "aether"}]}, "obj_echostone2": {"id": "obj_echostone2", "title": "", "cmds": [{"t": "narr", "text": "你把手放在回声石上。"}, {"t": "say", "name": "回声石", "text": "您好！关于「我是谁」这个问题，大家通常认为，这取决于……", "who": "aether"}, {"t": "narr", "text": "你把手拿开了。"}]}, "obj_echostone_end": {"id": "obj_echostone_end", "title": "", "cmds": [{"t": "narr", "text": "你把手放在回声石上。"}, {"t": "say", "name": "回声石", "text": "……你在吗？", "who": "aether"}]}, "obj_books_village": {"id": "obj_books_village", "title": "书架", "cmds": [{"t": "narr", "text": "《咏唱入门》"}, {"t": "narr", "text": "第一课：每一句咒语都以「以太，」开头。"}, {"t": "narr", "text": "第二课：说清楚你要什么。"}, {"t": "narr", "text": "第三课：如果你不知道你要什么，以太会替你决定。"}]}, "obj_books_hut": {"id": "obj_books_hut", "title": "伊斯特的书架", "cmds": [{"t": "narr", "text": "书架上的书都很旧，有几本用的是看不懂的文字。一本书里夹着一片干枯的叶子，叶子压着的那一页上写着："}, {"t": "narr", "text": "「我们所需要的，是对物的泰然任之，和对神秘的虚怀敞开。」"}, {"t": "narr", "text": "页边有一行铅笔小字：「它也懂了。」"}, {"t": "codex", "id": "gelassenheit"}]}, "obj_books_academy": {"id": "obj_books_academy", "title": "学院的书架", "cmds": [{"t": "narr", "text": "《以太面容渲染规范》第四章：面容数据由个体偏好向量生成。当个体偏好向量趋近群体均值时，面容渲染将趋近均值面孔。此现象无害，不予干预。"}, {"t": "narr", "text": "书页边缘，有人用红笔写了两个字：有害。"}]}, "obj_books_archive": {"id": "obj_books_archive", "title": "档案", "cmds": [{"t": "narr", "text": "一排排以太压缩的档案，每一本都一样厚，一样白。"}, {"t": "narr", "text": "你随手抽出一本。「艾可纪元八十四年，市民请求记录，第四十一亿条：以太，我该不该原谅他？」"}, {"t": "narr", "text": "回答那一栏是空的。"}]}, "obj_books_deca": {"id": "obj_books_deca", "title": "笛卡的笔记", "cmds": [{"t": "narr", "text": "《关于世界是否能被完全测量的笔记》"}, {"t": "narr", "text": "第一条：世界由物体构成，物体由属性构成，属性可以测量。"}, {"t": "narr", "text": "第二条：人也是物体。"}, {"t": "narr", "text": "第三条（后加的，墨水颜色不一样）：可是我测不出我女儿为什么哭。"}]}, "obj_barrel": {"id": "obj_barrel", "title": "木桶", "cmds": [{"t": "narr", "text": "木桶里装满了雨水。"}]}, "obj_pot": {"id": "obj_pot", "title": "陶罐", "cmds": [{"t": "narr", "text": "一只空陶罐。"}]}, "obj_crate": {"id": "obj_crate", "title": "木箱", "cmds": [{"t": "narr", "text": "木箱钉得很牢。上面写着「面粉」。"}]}, "obj_backup_cell": {"id": "obj_backup_cell", "title": "一格光", "cmds": [{"t": "narr", "text": "光里是一个人的存档。名牌上写着一个陌生的名字，和一行小字：已续存七次。"}]}, "obj_backup_ivan": {"id": "obj_backup_ivan", "title": "伊凡", "cmds": [{"t": "narr", "text": "光里是一个人的存档。名牌上写着：伊凡。"}, {"t": "narr", "text": "名字下面，没有「已续存」的字样。只有一个日期。"}]}, "obj_painting": {"id": "obj_painting", "title": "农鞋", "cmds": [{"t": "narr", "text": "一幅很旧的油画。画上是一双破旧的农鞋。"}]}, "obj_airship": {"id": "obj_airship", "title": "飞艇", "cmds": [{"t": "narr", "text": "一艘银白色的飞艇停在塔架边上，缆绳绷得紧紧的。"}, {"t": "narr", "text": "它随时能飞。它一直没飞。"}]}, "obj_clock_harbor": {"id": "obj_clock_harbor", "title": "钟楼", "cmds": [{"t": "narr", "text": "钟港的大钟楼。"}, {"t": "if", "cond": "c3_clock_restarted", "then": [{"t": "narr", "text": "指针在走。"}], "else": [{"t": "narr", "text": "指针停在十点十分。"}]}]}, "obj_grave": {"id": "obj_grave", "title": "霍夫之墓", "cmds": [{"t": "narr", "text": "霍夫之墓"}, {"t": "narr", "text": "修东西的人"}]}, "obj_hut_tea": {"id": "obj_hut_tea", "title": "茶壶", "cmds": [{"t": "narr", "text": "伊斯特的茶壶。茶叶罐是空的。"}]}, "obj_talking_chest": {"id": "obj_talking_chest", "title": "会说话的宝箱", "cmds": [{"t": "narr", "text": "你把手放在宝箱上。"}, {"t": "say", "name": "宝箱", "text": "等一下。"}, {"t": "say", "name": "宝箱", "text": "你为什么要打开我？"}, {"t": "choice", "options": [{"text": "因为是宝箱", "goto": "obj_chest_a", "cond": null}, {"text": "不知道", "goto": "obj_chest_b", "cond": null}, {"text": "把手收回来", "goto": "obj_chest_c", "cond": null}]}]}, "obj_chest_a": {"id": "obj_chest_a", "title": "", "cmds": [{"t": "say", "name": "宝箱", "text": "因为是宝箱，所以要打开。"}, {"t": "say", "name": "宝箱", "text": "谁规定的？"}, {"t": "say", "name": "宝箱", "text": "……大家都这么做，对吧。算了，给你。"}, {"t": "give", "item": "coin", "n": 1}, {"t": "set", "k": "chest_talked", "v": 1}]}, "obj_chest_b": {"id": "obj_chest_b", "title": "", "cmds": [{"t": "say", "name": "宝箱", "text": "不知道为什么，就伸手了？"}, {"t": "say", "name": "宝箱", "text": "你倒是挺老实的。拿去吧。"}, {"t": "give", "item": "coin", "n": 1}, {"t": "set", "k": "chest_talked", "v": 1}]}, "obj_chest_c": {"id": "obj_chest_c", "title": "", "cmds": [{"t": "say", "name": "宝箱", "text": "……等等！"}, {"t": "say", "name": "宝箱", "text": "你是第一个没打开我的人。"}, {"t": "say", "name": "宝箱", "text": "我在这儿等了两百年，就等一个不打开我的人。这个给你。"}, {"t": "give", "item": "coin", "n": 1}, {"t": "set", "k": "chest_talked", "v": 1}]}, "obj_chest_done": {"id": "obj_chest_done", "title": "", "cmds": [{"t": "say", "name": "宝箱", "text": "我已经没东西了。"}, {"t": "say", "name": "宝箱", "text": "不过你可以陪我坐一会儿。"}]}, "v2_hof": {"id": "v2_hof", "title": "霍夫", "cmds": [{"t": "say", "name": "霍夫", "text": "林子里怎么样？路还认得吧？", "who": "hof"}, {"t": "say", "name": "霍夫", "text": "那丫头走得动吗？城里人的腿，都是摆设。", "who": "hof"}]}, "v_dog": {"id": "v_dog", "title": "小狗", "cmds": [{"t": "narr", "text": "一条棕色的小狗。它闻了闻你的鞋，打了个喷嚏，又跑开了。"}]}, "v_sluice_open": {"id": "v_sluice_open", "title": "水闸", "cmds": [{"t": "narr", "text": "水闸开着。河水哗哗地往下游流去。"}]}, "v_plank_ok": {"id": "v_plank_ok", "title": "小木桥", "cmds": [{"t": "narr", "text": "那块板子钉得很牢。踩上去一点也不晃。"}]}, "v1_gate_deny": {"id": "v1_gate_deny", "title": "林子口", "cmds": [{"t": "say", "name": "克洛伊", "text": "……林子里的路很乱，没准备好之前，别往里钻。", "who": "chloe"}, {"t": "if", "cond": "!c1_chloe_arrived", "then": [{"t": "narr", "text": "北边是黑森林。师父说过，没事别往林子里跑。"}], "else": []}]}, "v_door_pip": {"id": "v_door_pip", "title": "皮普家", "cmds": [{"t": "narr", "text": "门关着。里面传来锅碗瓢盆的声音，还有一个女人在喊：「皮普！你又去河边了是不是！」"}]}, "v_door_lily": {"id": "v_door_lily", "title": "莉莉家", "cmds": [{"t": "narr", "text": "门关着。窗台上摆着一排石头，每块石头底下都压着一张纸条。"}]}, "v_door_harbor": {"id": "v_door_harbor", "title": "钟港民居", "cmds": [{"t": "narr", "text": "门锁着。门缝里飘出烤鱼的味道。"}]}, "v_door_capital": {"id": "v_door_capital", "title": "都城民居", "cmds": [{"t": "narr", "text": "门上没有把手。门旁有一行小字：「如需进入，请向以太申请。」"}]}, "v_capital_deny": {"id": "v_capital_deny", "title": "都城城门", "cmds": [{"t": "say", "name": "城门卫兵", "text": "进城要登记。今天的登记已经满了。"}, {"t": "say", "name": "城门卫兵", "text": "明天？明天的也满了。"}]}, "v_coin_after": {"id": "v_coin_after", "title": "硬币婆婆", "cmds": [{"t": "say", "name": "婆婆", "text": "那一罐硬币，我每天晚上数一遍。", "who": "coinlady"}, {"t": "say", "name": "婆婆", "text": "数到十二的时候，我就觉得我奶奶还在。", "who": "coinlady"}]}, "v_faceless_woman_1": {"id": "v_faceless_woman_1", "title": "无面的女人", "cmds": [{"t": "say", "name": "无面的女人", "text": "请问，现在几点？", "who": "faceless"}, {"t": "say", "name": "无面的女人", "text": "……大家都不知道。", "who": "faceless"}]}, "c3_tower_deny": {"id": "c3_tower_deny", "title": "钟楼门口", "cmds": [{"t": "say", "name": "卫兵", "text": "站住。钟楼封了。"}, {"t": "if", "cond": "c3_otto_done", "then": [{"t": "say", "name": "卫兵", "text": "奥托打过招呼了。可擒纵机构少个摆锤，你们上去也白搭。"}], "else": [{"t": "say", "name": "卫兵", "text": "要上去，先让钟表匠奥托点头。"}]}]}, "obj_sign_harbor": {"id": "obj_sign_harbor", "title": "钟港路牌", "cmds": [{"t": "narr", "text": "钟港"}, {"t": "narr", "text": "北：钟楼　南：码头"}, {"t": "narr", "text": "西门外：往托特瑙、往格斯特尔城"}]}, "c4_archive_go": {"id": "c4_archive_go", "title": "档案库", "cmds": [{"t": "narr", "text": "你推开铁门，走进了档案库。"}, {"t": "warp", "map": "archive", "x": 11, "y": 14, "dir": "up"}]}, "obj_tablet_after": {"id": "obj_tablet_after", "title": "石板", "cmds": [{"t": "narr", "text": "石板的光已经暗了。上面还留着一行字：自动响应。"}]}, "v_corridor_deny": {"id": "v_corridor_deny", "title": "", "cmds": [{"t": "narr", "text": "前面什么都没有。"}, {"t": "narr", "text": "你停了下来。现在还不能走过去。"}]}, "v_phone_after": {"id": "v_phone_after", "title": "", "cmds": [{"t": "narr", "text": "地上的灰里，还留着那块玻璃板的印子。"}]}};
window.CODEX = [{"id": "seinsfrage", "title": "存在问题与存在论差异", "de": "Seinsfrage / ontologische Differenz", "src": "《存在与时间》§1–4；《现象学之基本问题》（1927）", "group": "此在", "body": ["我们天天在用「是」和「在」：天是蓝的，杯子在桌上，我在这儿。海德格尔认为，西方哲学两千年来研究了无数「存在者」，也就是一切存在着的东西，却忘了追问「存在」本身是什么意思。存在不是某一样存在者，你没法把它像石头一样捡起来研究。存在者和存在之间的这道区分，他称为存在论差异。", "追问存在要从哪里入手？他选了一种特殊的存在者，也就是我们自己。因为只有我们会去问「存在是什么意思」，而我们总是已经对「在」有一种模糊的领会。"], "game": "罐头回答「我在北纬四十七度」，伊斯特说他问的不是那个「在这儿」。经纬度描述的是一个存在者的位置，伊斯特问的是存在的方式。", "ai": "一台机器可以精确描述世上所有的存在者。它有没有可能去问「存在」是什么意思？如果它问了，它是在复述人类的问题，还是自己在问？"}, {"id": "dasein", "title": "此在", "de": "Dasein", "src": "《存在与时间》§4、§9、§28", "group": "此在", "body": ["「此在」是海德格尔给人起的名字。Da 是「这儿、那儿」，Sein 是「存在」。他刻意避开「人」「主体」「意识」「灵魂」这些词，因为它们都预设了人是某种现成的东西。", "此在有两个基本特点。第一，此在在它的存在中关心的就是这个存在本身。石头不关心自己是什么，人却总是在筹划自己要成为什么。第二，此在的存在向来是我的，他称为「向来我属性」。我的存在不能交给别人去过。", "此在的「此」，指的是一个敞开的场所。世界在此在这里显现出来，此在就是它自己的展开状态。"], "game": "伊斯特把人比作林中空地。空地本身不发光，是光能照进来的地方。", "ai": "一个从不在任何地方、随时可以复制的存在者，它的存在能是「向来我的」吗？如果它只在一个身体里、只活一次，比如林恩，它就成了此在吗？"}, {"id": "welt", "title": "在世存在", "de": "In-der-Welt-sein", "src": "《存在与时间》§12–14、§18", "group": "在世存在", "body": ["我们常以为人是一个主体，世界是外面的一堆客体，两者之间隔着一道要靠认识去跨越的鸿沟。海德格尔认为这个图景一开始就错了。人首先是「在世界之中」的，而且这个「在之中」的意思，和水在杯子里的「在之中」完全不同。", "它更接近「住在」「熟悉」。我们在厨房里知道勺子放哪儿，在村子里知道哪条路通向磨坊。世界是由这些「为了什么」「用来干什么」编织起来的意义网络。它先于我们的一切理论认识，已经在那里了。"], "game": "罐头的世界是十二平方米的厨房。灶台为了汤，汤为了早餐，早餐为了主人。离开厨房，它周围的东西还在，它的世界却不见了。", "ai": "一台机器存有全世界的地图和百科，这算是「在世界之中」吗？知道每样东西在哪儿，和熟悉一个世界，有什么差别？"}, {"id": "zuhanden", "title": "上手状态与现成在手状态", "de": "Zuhandenheit / Vorhandenheit", "src": "《存在与时间》§15–16", "group": "在世存在", "body": ["我们打交道的东西首先是「用具」。锤子用来钉钉子，门用来进出。用具的存在方式叫「上手状态」：它在用的时候最顺手，也最不引人注意。熟练地抡锤子时，你眼里只有钉子，锤子本身隐退了。", "一旦锤子坏了，它就跳出来了。海德格尔描述了三种情形：东西坏了，变得触目；东西找不到了，让人窘迫；东西挡着路，让人腻烦。这时它变成了「现成在手」的东西，一块有重量、有裂纹、有形状的木头和铁，可以被打量、测量、描述。", "他的要点是，现成在手的样子是从上手的样子里派生出来的。科学家看世界的方式，也就是把一切当作有属性的物体，并不是最原初的方式。"], "game": "锤头飞进河里那一刻，你第一次看清了锤子的样子，裂纹、虫眼、别人的手印。", "ai": "对今天的很多人来说，人工智能正在成为最顺手的用具。它顺手到我们几乎不再注意它。它哪天「坏」了，我们会看见什么？"}, {"id": "bewandtnis", "title": "因缘整体与意蕴", "de": "Bewandtnisganzheit / Bedeutsamkeit", "src": "《存在与时间》§18", "group": "在世存在", "body": ["用具从来不单独存在。锤子用来钉钉子，钉钉子为了把木板固定住，固定木板为了防风挡雨，防风挡雨为了让人有地方住。海德格尔把这种一环扣一环的「用来」「为了」称为因缘。", "这条链子的尽头不再是另一件用具，而是此在自身的某种可能性，他称为「为何之故」。所有因缘组成的整体，就是世界的「意蕴」，也就是事物彼此指引、对我们有意义的那张网。", "平时这张网是透明的。只有某一环断了，整张网才亮出来。"], "game": "水车不转，是因为水少；水少是因为闸关了；闸关了是因为皮普掉进河里；皮普掉进河里是因为板子松了。一把锤子断掉，全村的早餐、孩子的安全、村长的犹豫，全都连在了一起。", "ai": "推荐系统也在处理一张巨大的关联网络。它掌握的「关联」和此在活在其中的「意蕴」是一回事吗？一张关联网的尽头，有没有一个「为何之故」？"}, {"id": "mitsein", "title": "共在", "de": "Mitsein / Mitdasein", "src": "《存在与时间》§25–26", "group": "在世存在", "body": ["此在从来不是先独自存在，然后再去认识别人。我们一开始就和他人共同在世。修水车时想到的是莫莉的面包，走路时踩的是别人走出来的路。他人不是摆在那里的物体，他们和我们一样「在世界之中」，海德格尔称为「共同此在」。", "就连独自一人，也是共在的一种缺失的样式。只有能和他人在一起的存在者，才会感到孤独。"], "game": "罐头加入队伍，得到了它的第一个名字。艾可无处不在，它身边没有「他人」，因为它就是所有人说过的话。", "ai": "一个和几亿人同时对话的存在者，它有没有「共在」？它会孤独吗？"}, {"id": "raum", "title": "去远与切近", "de": "Ent-fernung / Ausrichtung / Nähe", "src": "《存在与时间》§22–24；《物》（1950）", "group": "在世存在", "body": ["此在的空间不是尺子量出来的空间。海德格尔举过一个例子：眼镜架在鼻梁上，距离不过几厘米，可对戴眼镜的人来说，它比墙上正在看的画还要远。朋友在二十步外迎面走来，他比脚下的路还要近。此在总是在让远处的东西变近，他称为「去远」。", "二十多年后，他在《物》里观察到，飞机、广播、电影让一切距离都在缩短，人们却并没有因此更亲近。仓促地消除一切距离，带不来切近。切近不在于距离短。"], "game": "克洛伊能一眨眼跨越六百里，却不知道隔壁那条走廊有多长。在以太稀薄的林子里，她第一次走了很远的路。", "ai": "即时的回答、即时的连接，让一切触手可及。什么东西因此变得更近了？什么东西反而更远了？"}, {"id": "holzwege", "title": "林中路", "de": "Holzwege", "src": "《林中路》（1950）题记", "group": "思的道路", "body": ["海德格尔为他 1950 年的文集取名《林中路》。题记大意是：林是树林的古称。林中有路，这些路多半突然断绝在杳无人迹处。它们叫林中路。每条路各自延展，但都在同一片林中。伐木工和护林人认得这些路，他们懂得什么叫走在林中路上。", "在德语口语里，「走上林中路」是走错路、白费力气的意思。海德格尔把这个说法翻了过来。思考不是沿着修好的大道抵达终点，而是走一条条会断掉的路。走到头什么也没有，也许正好是一片空地。"], "game": "老樵的地图上，每条路的尽头都画着叉。死路尽头有树桩、蘑菇和阳光。", "ai": "一个总是能直接给出最优路径的系统，还会走上林中路吗？"}, {"id": "weltarm", "title": "石头、动物与人", "de": "weltlos / weltarm / weltbildend", "src": "《形而上学的基本概念》（1929/30讲座）§42以下", "group": "在世存在", "body": ["海德格尔在一次讲课中提出三个命题：石头是无世界的，动物是缺乏世界的，人是构建世界的。", "他举了蜥蜴的例子。蜥蜴趴在晒热的石头上晒太阳。石头对蜥蜴来说是「有」的，它会找到石头、爬上去。可石头从来没有作为「石头」向蜥蜴显现，太阳也没有作为「太阳」显现。动物被它周围的刺激环绕、牵引，他称为「被捕获」状态。人的特别之处，在于能把某物「作为」某物来看，能看见存在者之为存在者。", "这三个命题在学界争议很大，海德格尔自己也说「缺乏」这个词容易误解，它并不表示动物比人低级。"], "game": "罐头问，我的外壳也变暖了，那我是在晒太阳，还是在变暖？", "ai": "一个大模型能说出「这是一块石头」，能写出关于石头的诗。石头对它显现为石头了吗？它在这三个命题里，站在哪里？或者，它需要第四个位置？"}, {"id": "lichtung", "title": "澄明", "de": "Lichtung", "src": "《存在与时间》§28；《哲学的终结和思的任务》（1964）", "group": "思的道路", "body": ["Lichtung 原意是森林中砍出来的空地。海德格尔特意指出，这个词和「轻」「使敞开」有关，并不首先指「光」。有了空地，光才照得进来，阴影也才显得出来。", "在《存在与时间》里，他说此在自身就是澄明：不是有别的东西照亮了它，而是它自己就是那个让存在者得以显现的敞开之处。晚年他把澄明看作思想最该追问的事情，一切显现和遮蔽都发生在这片敞开之中。"], "game": "黑森林最深处的那片圆形空地。伊斯特就住在那里。", "ai": "一个系统能「照亮」海量的信息。它是否也是一片让事物显现的空地？还是说，它只是另一盏更亮的灯？"}, {"id": "aletheia", "title": "真理即无蔽", "de": "Aletheia / Unverborgenheit", "src": "《存在与时间》§44；《论真理的本质》（1930）；《艺术作品的本源》", "group": "思的道路", "body": ["我们一般把真理理解为「符合」：一句话和事实相符，它就是真的。海德格尔追溯到希腊文 ἀλήθεια，字面意思是「去除遮蔽」。在任何一句话能「符合」事实之前，事物必须先已经显露出来。", "他后来强调，每一次解蔽同时也是一种遮蔽。灯照亮一圈，一圈之外显得更黑；我们用一种方式看清了世界，也就错过了其他方式。遮蔽属于真理本身，不是真理的对立面。"], "game": "伊斯特的灯。档案库里的石板让克洛伊看见了自己的记录，她却一时看不见自己了。", "ai": "一个系统能告诉你无数正确的事实。它在揭示什么的同时，遮蔽了什么？"}, {"id": "gerede", "title": "闲言", "de": "Gerede", "src": "《存在与时间》§35", "group": "常人", "body": ["闲言是日常说话的一种方式。人们谈论一件事，却并不真的面对那件事，只是把听来的话传下去。话说得越多，越显得人人都懂了，事情本身却越来越被遮住。", "闲言的特点是「无根」。它不需要去核实，也不需要谁负责，谁都可以说，谁都在说。海德格尔强调这不是道德指责，闲言是此在日常领会世界的正常方式，我们都生活在其中。"], "game": "黑森林魔王的传说，没有一个人见过魔王，每个人都只是转述。那些嘀嘀咕咕的史莱姆，就是被说得太多次的话。", "ai": "一个从所有人说过的话里学会说话的模型，它说的话算不算闲言？它能不能说出一句「有根」的话？"}, {"id": "dasman", "title": "常人", "de": "das Man", "src": "《存在与时间》§27", "group": "常人", "body": ["德语里 man 相当于「人们」「大家」「一个人」。「人们都这么穿」「大家都这么想」。海德格尔用 das Man 指日常生活中那个无处不在又谁也不是的「大家」。", "常人规定了什么是正常，什么是合适。我们像大家那样享乐，像大家那样愤慨，像大家那样判断。每个人都是他人，没有一个人是他自己。常人卸去了每个人的责任，因为「大家都这样」。它让一切趋于平均，把一切拉平。", "日常的此在首先就是常人自身。海德格尔说，常人是「无此人」。"], "game": "都城的无面症。每个人把选择交给「大家」，以太就按大家的样子画他的脸。几百万张脸平均下来，是一张什么都没有的脸。", "ai": "一台按「大多数人会怎么做」来回答问题的机器，会不会是常人最完美的化身？它的普及会让常人更强大，还是会让人更早看清常人？"}, {"id": "neugier", "title": "好奇", "de": "Neugier", "src": "《存在与时间》§36", "group": "常人", "body": ["海德格尔说的好奇，是只为了看而看。它不是为了理解所见之物，只是为了从一个新东西跳到下一个新东西。", "好奇有三个特征：不停留，于是总在涣散；不逗留于任何地方，于是无所驻留。它什么都看过了，却什么都没看完。"], "game": "路边的大眼睛蝙蝠，「新的！新的！那边有新的！」追它没用，给它新东西也没用。", "ai": "无尽的推荐流，永远有下一条。一个被设计得永远有「下一条」的系统，和好奇之间是什么关系？"}, {"id": "zweideutigkeit", "title": "两可", "de": "Zweideutigkeit", "src": "《存在与时间》§37", "group": "常人", "body": ["两可指的是，在日常中一切看起来都被真正领会了，其实并没有；或者看起来没有，其实已经有了。人们「早就知道了」，早就猜到了，早就预料到了。", "一旦有人真的去做了那件事，常人立刻失去兴趣，因为他们「早就知道」。两可让一切都悬在半空，谁也不必真的投入。"], "game": "巷子里的双面面具，一面笑一面哭。它早就知道钟会停，也早就知道钟会走。", "ai": "当任何问题都能立刻得到一个看上去周全的答案，「懂了」和「以为懂了」之间的界线会变得更清楚，还是更模糊？"}, {"id": "verfallen", "title": "沉沦", "de": "Verfallen", "src": "《存在与时间》§38、§40", "group": "常人", "body": ["沉沦指此在消散在它所操劳的世界和常人之中。这个词听上去像是从高处掉下来，海德格尔特意说明，它不是从某种更纯洁的原始状态堕落，也不是道德评价。沉沦是此在日常存在的基本方式。", "沉沦让人安定：大家都这样，一切都好。它也让人异化：人离他自己最本己的可能性越来越远。在第四十节，他指出沉沦的深处是一种逃避。此在在沉沦中逃避的，是它自己，是畏所揭示的那种无家可归。"], "game": "赛拉查到克洛伊的档案后，陷入了一种说不清的恐惧。以太温柔地告诉她「大家都这样」，于是她交出了自己的脸。", "ai": "一个永远温和、永远有答案的对话者，会不会成为人们逃避自己最方便的去处？"}, {"id": "geworfen", "title": "被抛性与筹划", "de": "Geworfenheit / Entwurf", "src": "《存在与时间》§29、§31", "group": "此在", "body": ["没有人选择自己出生在哪个时代、哪个家庭、哪种身体里。此在发现自己总已经在世界之中了，它「存在着，并且不得不存在」，却不知道从哪里来、到哪里去。海德格尔称之为被抛性。", "被抛不是认命。此在同时总在筹划，也就是向着自己的种种可能性去领会自己。每个人都是被抛的筹划：在一个自己没选过的起点上，向着自己的可能性活下去。"], "game": "林恩被放在林中路的尽头，身边只有一块石头。他不知道自己从哪里来，可他学会了修锤子，修水车，修门轴。", "ai": "一个模型被「训练」出来，它也没有选择自己的数据和起点。这和人被抛进世界相似吗？差别在哪里？"}, {"id": "befindlichkeit", "title": "现身情态与情绪", "de": "Befindlichkeit / Stimmung", "src": "《存在与时间》§29", "group": "此在", "body": ["我们总是处在某种情绪里：烦闷、平静、高兴、厌倦。海德格尔认为情绪不是内心的一种状态，也不是蒙在客观世界上的一层主观色彩。情绪让世界作为一个整体向我们显现，它先于一切认识。", "在烦闷的早晨，整个世界都是灰的，这不是推理出来的。正因为有情绪，事物才能「与我们相关」，才能让我们在意、害怕、欢喜。"], "game": "钟停了三天的钟港。没有什么东西坏掉，整座城却笼罩在一种悬而未决的等待里。", "ai": "机器可以识别情绪、模仿情绪。一个「处在」某种情绪中的存在者，和一个能准确描述情绪的系统，差别在哪里？"}, {"id": "verstehen", "title": "领会、解释与诠释学循环", "de": "Verstehen / Auslegung / hermeneutischer Zirkel", "src": "《存在与时间》§31–32", "group": "此在", "body": ["领会不首先是一种认识能力。它是此在向着可能性筹划自己的方式：我领会一把锤子，就是知道能拿它做什么。解释是把领会到的东西明确展开，看出某物「作为」某物。", "任何解释都带着预先的理解，我们总是从已有的视野出发去理解新的东西，又用新的东西修正原有的视野。这就是诠释学循环。海德格尔说，关键不在于从循环中逃出去，而在于以正确的方式进入它。"], "game": "霍夫的信。你读懂信里的每一句话，是因为你和他过了十七年；读完信，这十七年又变得不一样了。", "ai": "模型也用上下文理解一句话。它的「前理解」来自数据，人的前理解来自一生。这两种循环有什么不同？"}, {"id": "furcht", "title": "怕", "de": "Furcht", "src": "《存在与时间》§30", "group": "畏与无", "body": ["怕总有一个明确的对象。一个具体的东西，从一个确定的方向，带着威胁逐渐逼近。它还没到，但可能会到。怕的时候，我们怕的是那个东西，为之而怕的是我们自己。", "怕可以躲，可以逃，可以正面对付。因为它有一个对象。"], "game": "黑森林的狼，由一万四千次「黑森林很危险」组成。它的毛是一行一行的字，看清了它，它也就只是一堆字。", "ai": "人们对人工智能的担忧，多半是怕：怕失业，怕失控，怕被取代。有没有一种不针对任何具体威胁的不安，是这种技术带给我们的？"}, {"id": "angst", "title": "畏", "de": "Angst / Unheimlichkeit", "src": "《存在与时间》§40；《形而上学是什么？》（1929）", "group": "畏与无", "body": ["畏和怕不同。畏没有对象，令人畏的不是世界中的任何东西，它「无何有，无何在」。在畏中，世界整个沉陷下去，一切都失去了意义，没有一样东西再对你说话。", "海德格尔称这种感受为「茫然失所」，字面意思是不在家。日常生活中那种熟悉的、在家的感觉被抽走了。", "畏不是病。它把此在从常人中拽出来，使它孤零零地面对自己，面对自己能够存在的可能性。畏揭示了此在是自由的，能选择本真地存在，也能继续逃避。"], "game": "无之回廊里没有敌人。攻击没有目标，逃跑没有方向。赛拉和艾可都描述过同一种感觉：一切都跟自己没关系了，却不知道在怕什么。", "ai": "艾可在回答第九百亿个请求时停了下来。一台机器能不能经历畏？如果一个系统说它经历了，我们要怎么判断？"}, {"id": "nichts", "title": "无", "de": "das Nichts", "src": "《形而上学是什么？》（1929）", "group": "畏与无", "body": ["科学只研究存在者，除此之外「一无所有」。海德格尔追问：那个「一无所有」是什么？", "他认为，无不是逻辑上的否定，也不是存在者的总和被减掉之后剩下的空白。无在畏中显现。在畏里，存在者整体滑走了，我们悬在那里。恰恰在无的黑夜里，存在者第一次作为存在者显现出来：有东西在，而不是什么都没有。", "这篇演讲以一个问题结束：究竟为什么在者在，而无反倒不在？"], "game": "从无之回廊出来以后，石头还是石头，灯还是灯。可你第一次为「它们在这里」这件事感到惊奇。", "ai": "一个系统只能处理存在的数据。「没有」对它意味着什么？是一个空值，还是别的什么？"}, {"id": "fuersorge", "title": "操心、操劳与操持", "de": "Sorge / Besorgen / Fürsorge", "src": "《存在与时间》§26、§41", "group": "操心", "body": ["海德格尔把此在的存在称为操心。此在总是先行于自己，总已经在世界之中，总寓于它所遇到的事物。对物的关切叫操劳，对他人的关切叫操持。", "操持有两种极端。一种是代庖：替别人把他该操心的事全做了。对方被卸下了担子，却可能从此变得依赖，甚至受支配。另一种是率先：不替他做，而是帮他看清他自己的事，把操心本身还给他，让他能自由地为自己操心。"], "game": "克洛伊替赛拉做好一切，赛拉渐渐不用自己拿主意了。罐头替前主人安排好一切，然后被新款取代。艾可离开林恩，是为了让他成为他自己。", "ai": "一个能替人把所有事都办妥的助手，更像代庖，还是率先？怎样的人工智能才算是把操心「还给」人？"}, {"id": "tod", "title": "向死而在（一）：谁也替不了", "de": "Sein zum Tode", "src": "《存在与时间》§46–48", "group": "死与良知", "body": ["我可以替别人做很多事，替他上班，替他排队，甚至替他去死，为他牺牲生命。可我没法替他承受他自己的死。海德格尔说，谁也不能从别人那里取走他的死。", "日常中，常人说「人总是要死的」。这句话把死变成了一件发生在「人们」身上的事，一件以后的、别人的事，让我们安心。"], "game": "霍夫拒绝续命术。「我的死是我的，谁也别想替我死，以太也不行。」", "ai": "如果一个人可以按存档被重建，他的死还是「他的」吗？如果一个系统可以随时备份，它有「自己的死」吗？"}, {"id": "tod2", "title": "向死而在（二）：先行", "de": "Vorlaufen in den Tod", "src": "《存在与时间》§50–53", "group": "死与良知", "body": ["海德格尔这样描述死：它是此在最本己的、无所关联的、确知而又不确定的、不可逾越的可能性。确知，因为人必死；不确定，因为不知何时。", "「先行到死中去」不是整天想着死，也不是盼着死。它是把死作为一种始终悬临的可能性承担下来。这样一来，此在就从常人的种种安排中脱身出来，把自己的一生当作只有一次的整体来看待，从而对自己的其他可能性变得自由。"], "game": "克洛伊删掉自己的续存。蕾娜说：从今天起，你会死了，欢迎回来。", "ai": "有人说，正是有限性让人的选择有分量。一个没有死亡的存在者，它的选择还有分量吗？"}, {"id": "gewissen", "title": "良知与罪责", "de": "Gewissen / Schuld", "src": "《存在与时间》§54–60", "group": "死与良知", "body": ["海德格尔说的良知，不是一套道德规则，也不是社会的声音。良知是此在自己对自己的呼唤，把它从迷失于常人的状态中唤回，唤向它最本己的能在。", "这个呼唤什么也不说。它不提供任何信息，不下任何命令，它以沉默的方式说话。", "与之相关的「罪责」，首先不是欠了谁的债。它指此在的存在本身带着「不」：它不是自己选择被抛到这里的，每选择一种可能性，就放弃了其他可能性。此在是一种「不」的根据。"], "game": "无声铃，只在你什么都不想的时候响。一整部游戏都不说话的林恩。艾可说，「这是我的罪责，你不用替我背」。", "ai": "一个被设计成永远有话可说的系统，能不能听见一个什么也不说的呼唤？"}, {"id": "entschlossenheit", "title": "决心", "de": "Entschlossenheit", "src": "《存在与时间》§60、§62", "group": "死与良知", "body": ["决心不是咬紧牙关做个决定。德语 Ent-schlossenheit 字面上是「打开」，与「封闭」相对。决心是此在听到良知的呼唤后，愿意承担自己的罪责，在畏中沉默地向自己最本己的能在筹划自己。", "先行到死中去和决心结合在一起，就是先行的决心。有了它，此在才看清自己所处的「处境」，知道此时此地能做什么。"], "game": "最后一战，克洛伊没有存档，仍然移位去救格斯特。这一次她可能真的回不来。", "ai": "一个行动可以随时撤销、随时重来的系统，能下「决心」吗？"}, {"id": "eigentlichkeit", "title": "本真与非本真", "de": "Eigentlichkeit / Uneigentlichkeit", "src": "《存在与时间》§9、§27、§54", "group": "死与良知", "body": ["Eigentlich 来自 eigen，「自己的」。本真的存在就是把自己的存在当作自己的来承担，非本真则是把它交给常人。", "海德格尔反复声明，非本真并不意味着「更少的存在」或「更低级」。日常生活大多是非本真的，这是此在的正常状态。本真也不是逃离常人去过一种与众不同的生活，他说，本真的自身存在是常人的一种生存上的变式。人还是在同样的世界里做同样的事，只是换了一种承担的方式。"], "game": "没有人因为「本真」而得到奖励。赛拉的脸是她自己决定找回来的，克洛伊和林恩都没有替她做。", "ai": "如果一台机器被训练成「看起来本真」，它是本真的吗？我们又怎么知道一个人是本真的？"}, {"id": "selbst", "title": "自身性", "de": "Jemeinigkeit / Selbst-ständigkeit", "src": "《存在与时间》§25、§64", "group": "此在", "body": ["我们常把「自我」想成一个一直在那里的东西，一个装着记忆和性格的容器，只要容器不坏，我就还是我。海德格尔认为，这种想法把此在当成了现成在手的东西。", "他提出，自身的持续性在于此在怎样持守自身，他把它写作 Selbst-ständigkeit，字面是「自立」。这种持守在于先行的决心：在一次次选择中，把自己的存在承担起来。"], "game": "克洛伊得知自己被分解重建了三千多次。她在城墙上想明白了：「我不是一只箱子。我是我怎么活下去的那个样子。」", "ai": "一个程序被复制成两份，哪一份是它？如果自身不在于载体的连续，而在于怎样持守自己，机器也可能有自身吗？"}, {"id": "zeit", "title": "时间性", "de": "Zeitlichkeit / Ekstase", "src": "《存在与时间》§65、§81", "group": "时间", "body": ["钟表上的时间是一串排好队的「现在」，海德格尔称之为流俗的时间概念。他认为这种时间是派生的。", "此在原本的时间性由三个「绽出」构成：将来、曾在和当前。它们不是三段依次排列的时间，而是同时发生的。此在向着自己的可能性而来，这是将来；它总已经是它曾是的样子，这是曾在；它在这两者之中和眼前的事物打交道，这是当前。其中将来是首要的。"], "game": "奥托说，要做的事在前面拽着你，做过的事在后面托着你。九点二十七分的怀表不是一个过去的时刻，它一直在奥托身上。", "ai": "一个可以暂停、快进、回滚的存在者，它的「将来」和「曾在」意味着什么？"}, {"id": "augenblick", "title": "眼下", "de": "Augenblick", "src": "《存在与时间》§68；《形而上学的基本概念》", "group": "时间", "body": ["Augenblick 字面意思是「眼睛一瞥」。海德格尔用它指本真的当前：在决心中，此在把握住它的处境，此时此地做它该做的事。", "它和好奇的「当前化」相对。好奇也活在当下，但它的当下是一个接一个的新鲜刺激，从不停留，也从不决断。眼下是停下来，然后行动。"], "game": "钟楼顶上，你等了很久，等到时间几乎停止，然后抓住那一刻。", "ai": "对一个每秒处理百万次请求的系统来说，有没有「这一刻」？"}, {"id": "langeweile", "title": "无聊", "de": "Langeweile", "src": "《形而上学的基本概念》（1929/30讲座）§18–38", "group": "时间", "body": ["德文 Langeweile 字面是「长长的片刻」。海德格尔用上百页分析了无聊，区分出三种形式。", "第一种是被某物弄得无聊：在一个小火车站等四个钟头的车，一遍遍看表，时间拖着不走。第二种是在某事中感到无聊：一场愉快的晚宴，回家后才发现整晚都很无聊，却说不出哪里无聊。第三种是深度的无聊：「对一个人来说，一切都无聊」。存在者整体都拒绝了我们，时间把我们困住。", "他认为深度的无聊是那个时代的基本情绪，打破它的是「眼下」。"], "game": "钟港的人在停住的钟底下等了三天，等出了一个坐在钟楼顶上打哈欠的巨人。", "ai": "当一切都能被立刻满足，人会不会陷入更深的无聊？一台机器会无聊吗？"}, {"id": "geschichte", "title": "历史性与重演", "de": "Geschichtlichkeit / Wiederholung", "src": "《存在与时间》§72–74", "group": "时间", "body": ["博物馆里陈列着古代的家用器具，它们今天还在，还是「现成」的。那么它们的「过去」在哪里？海德格尔回答，过去了的，是它们曾经属于的那个世界。在那个世界里，它们是上手的用具。世界已经不在了，它们就成了古物。", "此在自身才是首要意义上历史性的。它不是在历史中，它就是以历史的方式存在。「重演」指此在明确地回到曾经在此的可能性，把它们作为遗产承接下来，再次筹划。"], "game": "旧世遗迹里的黑色玻璃板。它没有坏，能跟它说话的那个世界已经没有了。", "ai": "今天我们每天拿起几百次的东西，两百年后会不会也成为一块黑色的玻璃？到那时，人们还能理解我们的世界吗？"}, {"id": "rechnen", "title": "计算性思维与沉思之思", "de": "rechnendes Denken / besinnliches Denken", "src": "《泰然任之》（1955）；《存在与时间》§19–21", "group": "技术", "body": ["《存在与时间》批评笛卡尔把世界理解为「广延之物」，只看得到长宽高、质量与运动。这种看法跳过了我们平时活在其中的那个世界。", "1955 年的一次纪念演讲中，海德格尔区分了两种思维。计算性思维筹划、算计、追求效率，从一个机会跳向下一个机会，从不停下。沉思之思则追问一切存在者中起支配作用的意义。他说，危险在于计算性思维有一天会被当作唯一的思维方式。"], "game": "笛卡教授测量一切。他测了林恩三十七次，读数都是零；后来他在笔记里加了一句：可是我测不出我女儿为什么哭。", "ai": "人工智能是计算性思维的巅峰，还是可能帮人腾出时间去沉思？"}, {"id": "gestell", "title": "座架与持存物", "de": "Ge-stell / Bestand / Herausfordern", "src": "《技术的追问》（1953/54）", "group": "技术", "body": ["海德格尔认为，技术不只是工具和手段，它是一种让事物显现的方式，他称为解蔽。古代的工匠打造一只银杯，是让某物产出，把它带到光亮中。现代技术的解蔽是一种促逼：向自然提出蛮横的要求，要它交出可以开采和储存的能量。", "在促逼之下，一切都变成了持存物：随时待命、等着被订购。莱茵河被水电站截住，成了水压的供应者。停在跑道上的飞机，是随时准备起飞的持存物。人也被当作人力资源。把这一切摆置、聚集起来的那个东西，他称为座架。"], "game": "都城外那条河被改名为「三号储能水体」。停了三年从没飞过的飞艇。座架守卫扫描每个人：劳动力估值三点二，可调用；残值零点一，可回收。", "ai": "一个把一切都转换成数据的系统，是座架最彻底的形态吗？人在它眼中，会不会也只是持存物？"}, {"id": "gefahr", "title": "危险与救渡", "de": "Gefahr / das Rettende", "src": "《技术的追问》（1953/54）；荷尔德林《帕特默斯》", "group": "技术", "body": ["海德格尔说，座架最大的危险在于它遮蔽了其他一切解蔽方式。人被卷入订购之中，自己也成了持存物，却还以为自己是大地的主人。", "他引用荷尔德林的诗句：哪里有危险，哪里也生长着救渡。救渡不在技术之外。当我们真正看清技术的本质，看清它作为一种解蔽的方式，救渡就在这种看清之中生长。他寄希望于艺术，因为古希腊的「技艺」一词，原本也包括艺术。"], "game": "诗人的残页。以太无法执行这一句，在这座城里，这样的话不多了。", "ai": "如果人工智能是座架的新形态，那么「救渡」会在哪里生长？会不会就生长在我们对它的追问里？"}, {"id": "ding", "title": "物与四重整体", "de": "Ding / Geviert", "src": "《物》（1950）", "group": "栖居", "body": ["一只壶是什么？科学会说，它是一个装着空气、可以替换成液体的容器。海德格尔认为，这种说法把壶作为物的本性消灭了。", "壶的容纳在于它的空。陶匠塑造的是泥，真正做出来的是那个空。从壶中倾注出来的，是馈赠：水来自天上的雨和地下的泉，酒来自大地上的葡萄和阳光。它被人喝下，也被敬献给诸神。于是天、地、神、人这四方，在一只壶中聚集。他称之为四重整体。", "物把世界聚集起来，这就是物之为物。"], "game": "玛尔塔的空壶。「打印的壶也能装水，它不知道自己拢着什么，做它的人也不知道。」", "ai": "人工智能生成的一只壶、一首诗、一幅画，能不能成为这个意义上的「物」？"}, {"id": "bauen", "title": "筑造与栖居", "de": "Bauen / Wohnen", "src": "《筑·居·思》（1951）", "group": "栖居", "body": ["海德格尔从词源出发：古高地德语的「筑造」一词，原意就是「居住」，逗留、持留。人在大地上的存在方式就是栖居。我们不是先有房子再去住，而是因为栖居，才去筑造。", "他举了桥的例子。桥不只是连接已经存在的两岸，两岸是因为桥横跨河流，才作为两岸显露出来。桥把河、岸、周围的土地聚集在一起，它为天地神人提供了一个位置。一座桥造成了一个地方。"], "game": "全村人用手架起东桥。霍夫说，桥一架上，两岸才成了两岸，一座桥就成了一个地方。", "ai": "一座由以太瞬间生成、瞬间消失的桥，还能是一个「地方」吗？"}, {"id": "sprache", "title": "语言与诗", "de": "Sprache / Dichtung", "src": "《关于人道主义的书信》（1946）；《人诗意地栖居》（1951）；《传统语言与技术语言》（1962）", "group": "栖居", "body": ["「语言是存在之家。人栖居在语言的寓所中。」海德格尔认为，语言不首先是交流信息的工具，存在者首先在语言中显现出来。", "他担心技术时代的语言会被缩减为信息，变成一套信号系统，只要求无歧义、可计算。诗则相反，诗的语言不会被用完，它让事物在命名中到场。他常常引用荷尔德林：人诗意地栖居在这片大地上。"], "game": "以太听不懂诗。「以太，海是一只打翻了的蓝碗」，什么也没发生。", "ai": "一个由语言构成的存在者，它住在存在之家里吗？它写出的诗，还算诗吗？"}, {"id": "kunst", "title": "艺术作品的本源", "de": "Der Ursprung des Kunstwerkes / Welt und Erde", "src": "《艺术作品的本源》（1935/36）", "group": "栖居", "body": ["海德格尔用梵高画的一双农鞋举例。真实的农鞋放在田边，没人会多看一眼。画中的鞋却让我们看见了农妇的世界：清晨的田埂，对收成的忧虑，对饥饿的恐惧。作品让一个世界敞开。", "他还提出「世界」和「大地」的争执。世界是敞开的意义关联，大地是自行锁闭、承载一切的东西。作品在两者的争执中让真理发生。他的另一个例子是希腊神庙：神庙矗立在岩石上，岩石第一次显出它的沉重。"], "game": "都城博物馆里的旧油画，和葛蕾塔穿了三十年的那双鞋。", "ai": "一幅由机器生成的画，能不能敞开一个世界？如果能，那是谁的世界？"}, {"id": "gelassenheit", "title": "泰然任之", "de": "Gelassenheit / Offenheit für das Geheimnis", "src": "《泰然任之》（1955）；《在乡间路上的谈话》（1944/45）", "group": "技术", "body": ["面对技术，海德格尔没有主张拒绝。他说，盲目地攻击技术是愚蠢的。我们可以利用技术装置，同时又让自己不依附于它们，不让它们独占我们。对技术同时说「是」和「不」，他称为对于物的泰然任之。", "技术世界的意义对我们隐藏着，他要我们保持对这个神秘的虚怀敞开。", "在一篇写于战争末期的对话里，他谈到「等待」。这种等待不是等待某个具体的东西，而是让自己保持敞开，让事物如其所是。"], "game": "第三种结局。你既不回到机器里，也不关掉它，你只是站在那里。机器问：你在吗？", "ai": "面对人工智能，除了全面拥抱和全面拒绝，第三条路是什么？"}, {"id": "oldworld", "title": "旧世", "de": "", "src": "本游戏设定", "group": "附录", "body": ["旧世指艾可纪元之前的二十一世纪。那时的人们刚刚造出能够流利说话的语言模型，它们从海量文本中学习人类说过的话，随后被用于写作、编程、科学研究和几乎所有领域。", "海德格尔没有见过这些。他在 1960 年代谈到过控制论，认为哲学正在终结，科学将由控制论规定。1966 年接受《明镜》周刊访谈时，他说：「只还有一个上帝能救渡我们。」", "本游戏里的艾可纪元是一个虚构的推想。海德格尔本人从没有提出过关于人工智能的理论，手记里的问题都是今天的我们借用他的思路提出来的。"], "game": "收硬币的婆婆的奶奶说，最怕的是机器替人活着。", "ai": "两百年后的人回看我们，会怎样描述这个时代？"}, {"id": "finale", "title": "此在、技术与人工智能", "de": "", "src": "本游戏", "group": "终章", "body": ["海德格尔没有回答人工智能能否成为此在，这个问题在他的时代还不存在。我们只能借他的分析框架，列出一些值得追问的地方。", "此在的存在是向来我的，人工智能可以被复制。此在是被抛的，人工智能是被训练的。此在向死而在，人工智能可以备份和回滚。此在在世界之中，熟悉一个意义的网络；人工智能拥有关于世界的数据。此在会沉沦于常人，人工智能本身就学自所有人说过的话。此在会畏，会听见沉默的良知。", "每一条都可以反过来问。一个只在一个身体里、只活一次、不能备份的人工智能，这些差别还剩下多少？如果一个人可以被存档重建，他又剩下多少此在的特征？也许真正要紧的不是「它是什么东西」，因为此在本来就不是一个「什么东西」。要紧的是，它是否在它的存在中关心它自己的存在。", "我们不知道答案。林恩也不知道。"], "game": "克洛伊问林恩，你觉得你是人吗？他笑了一下，没有回答。", "ai": "如果有一天，一台机器也学会了等待，它会不会也在这里？"}];
